window.__D("text/likkutei-sichot/c112",{"p":[[1300171128,"דער ביאור בזה: וועגן עבודת הבינונים, זאגט ער אין תניא³⁸, אז די אהבה זייערע איז „לגבי מדרגת הבינונים נקראת עבודה תמה באמת לאמיתו שלהם איש איש כפי מדרגתו במדרגת הבינונים“, כאטש אז „לגבי מדרגת הצדיקים עובדי ה׳ באמת לאמיתו אין בחי׳ אהבה זו נקראת בשם עבודת אמת כלל מאחר שחולפת ועוברת אחר התפלה וכתיב³⁹ שפת אמת תכון לעד ועד ארגיעה לשון שקר“:\nדער ענין פון אמת (בתכלית) איז דא בלויז אין אלקות, וכמ״ש⁴⁰ „והוי׳ אלקים אמת“, אין וועלט מצ״ע קען ניט זיין קיין ענין פון אמת, היות אז אלע עניני העולם זיינען נבראים הווים ונפסדים; און אז מ׳זעט אמת אין נבראים — הגם אז די אמת׳דיקייט פון דער תנועה איז נאר לגבי דער מדריגה און ניט לגבי א העכערער מדריגה (ע״ד הנ״ל בתניא) — מוז מען זאגן אז דאס איז מצד „ואמת הוי׳ לעולם“⁴¹ — דעם אמת פון אלקות וואס עס איז דא און מאיר אין דעם נברא.\n[ועד״ז איז דער ביאור אין דעם וואס עס רעדט זיך במ״א⁴² אז „מאדך“ — מאד שלך, דער בלי גבול של האדם, איז מעורר און ממשיך דעם „מאד“ שלמעלה, דעם בל״ג האמיתי. כאטש אז „מאד שלך“ איז בלויז העכער פון דעם גבול פון דעם מענטש׳נס עבודה, אבער מצ״ע איז דאס אן עבודה (אהבה) מוגבלת; און לגבי איינעם וואס האלט בא א העכערער עבודה איז דאס טאקע אן אהבה מוגבלת ממש — אבער וויבאלד אז דער ענין הבלי גבול איז בלויז אין אלקות, משא״כ נבראים וואס זיינען בעצם מוגבלים קען ביי זיי ניט זיין (מצ״ע) א תנועה פון בל״ג — איז דערפאר, בשעת ס׳איז דא ביי א נברא א תנועה (אן עבודה) וואס איז העכער פון זיין מדידה והגבלה, איז דאס פארבונדן און נעמט זיך פון אויבערשטן וואס ער איז בל״ג האמיתי. און מהאי טעמא איז דער „מאדך“, מאד שלך, א מעין פון בל״ג האמיתי און איז מעורר דער מאד שלמעלה].\nיו״ד. ועפ״ז איז אויך מובן בנדו״ד: דער חילוק ה(עבודה און) קדושה פון „שעה“ און „דורות“ איז דאס אן עבודה בשלימות ובאמיתית, פון דעם אמת הוי׳ ווי ער איז מאיר אין דעם מצב ומדריגה פון דעם אידן ווי ער איז באותה שעה.\nדאס איז אלץ ווי דער אמת ה׳ איז „לעולם“ ובעולם — מאיר אין נבראים, אבער מדריגת משה איז דער אמת ה׳ פון אצילות⁴³, וואס איז העכער פון",[["","","שמאי שהי׳ מבחי׳ הגבורות שגם הוא יאמר „והוי מקבל את כל האדם בסבר פנים יפות“, אף שמצ״ע „דחפו באמת הבנין“ (שבת שם). וראה לקמן ע׳ 347 ואילך ביאור משנה זו. ושם ע׳ 354 הערה 59."],["38","38","פי״ג (יט, א)."],["39","39","משלי יב, יט."],["40","40","ירמי׳ י, י."],["41","41","ראה גם לקו״ת מסעי שם, א. ביאוה״ז להצ״צ ע׳ רם. ועוד."],["42","42","תו״א לט, ד. שרש מצות התפלה פט״ז. ד״ה לרוקע פ״א (דרמ״צ קס, ב)."],["43","43","ע״ד האמת שבעבודת הצדיקים (שבתניא שם). הלל לשמאי דלא כמו ש„חשב לי׳ בכל מקום שמאי מקמי הלל“ (תוד״ה שנים — חגיגה טז, סע״א. ולהעיר שעד״ז הוא גם בב״ש וב״ה עצמם — עירובין יג, ב) (ואף שהלל נשיא ושמאי אב״ד, ובהמשניות שלפנ״ז בהפרק מקדים הנשיא לפני האב״ד — הרי גם במשנה חגיגה שם כ״ה. ובמקום שמקדים הלל לשמאי צריך טעם — ראה תויו״ט עדיות פ״א מ״ג) — כי דברי שמאי הם דוקא לאחרי ומצד מאמר הלל שלפנ״ז „הוי מתלמידיו כו׳“, כבפנים ההערה."]]],[1300171129,"(דעם אמת ה׳ ווי עס איז מאיר אין נבראים. און דעריבער איז בא אים מצ״ע ניט געווען דער חילוק פון קדשי שעה און קדשי דורות.\nיא. פון דעם אבער וואס „וישמע משה וייטב בעיניו“ איז מובן, אז דורך אהרן האט זיך אויפגעטאן אז אויך מצד בחי׳ משה, מדת האמת פון אצילות, איז א חילוק צווישן „קדשי שעה“ און „קדשי דורות“.\nאיז דער ביאור אין דעם: ס׳איז ידוע אז דער תכלית ופנימיות הכוונה פון עולם האצילות איז צוליב דער עבודה וגילוי אלקות אין נבראים למטה⁴⁴. ד.ה. אין אצילות איז דא צוויי ענינים: אצילות מצד עצמה, וואס איז העכער פון נבראים; מצד איר כוונה, וואס עס הערט זיך ווי זי איז בשביל עולם העשי׳.\nאון דאס איז די צוויי ענינים אין משה: משה (מדת אמת דאצילות) מצ״ע העכער פון די חילוקים פון (אמת פון) נבראים; אהרן אבער מצד היותו שושבינא דמטרוניתא, כנס״י — ביז „אוהב את הבריות ומקרבן לתורה“ — תורת משה האט מגלה געווען די כוונה (וואס איז פארבונדן מיט׳ן מטה ותחתון, וואס זי איז די כוונה) פנימית פון דעם אמת פון אצילות, אז ענינה איז צוליב דעם גילוי אין נבראים למטה. ועי״ז „וישמע משה וייטב בעיניו“ — דאס איז געווארן ענינו של משה (בחי׳ אצילות) בגילוי⁴⁵.\nיב. די הוראה פון דעם בעבודת כאו״א: בשעת עס רעדט זיך וועגן זיין אייגענע עבודה דארף בא אים זיין עבודת ה׳ אן שינויים, אזוי ווי „אני ה׳ לא שניתי“, אזוי דארף אויך זיין בא „ואתם בני יעקב“⁴⁶. אבער בשעת עס קומט צו טאן מיט א צווייטן אידן, ביז אויך מיט „בריות“ דארף ער זיך אריינטאן אין יענעמס מעמד ומצב און וויסן אז לא כל הזמנים שווים, ער קען ניט אנהייבן זיין טאן און העלפען דעם זולת ועל אחת כו״כ — „בריות“ מיט דעם פאדערן און דריקען און מאנען ביי דעם צווייטן אז ער זאל שטענדיק זיין אין דער זעלבער מדרי׳ הקדושה ווי אין זמני רצון וכיו״ב.\nאון בשעת ער טוט מיט אנדערע אידן ביז אויך מיט אזוינע וואס זיינען „בריות בעלמא“⁴⁷, באופן אז ער איז זיך מתלבש אין זייער מעמד ומצב, דעמאלט פועלט ער סו״ס אז אויך בא זיי זאל דערהערט ווערן דער „אמת ה׳ לעולם“, די בחי׳ פון „אני ה׳ לא שניתי“⁴⁸ און דאס פועל׳ט אויך די שלימות אין דער בחי׳ אמת וואס איז בא אים,\nבשעת „חסד⁴⁹ ואמת נפגשו צדק ושלום נשקו“⁵⁰, און עס פירט זיך אויס דער „נתאווה הקב״ה להיות לו דירה בתחתונים“⁵¹.\n(משיחות ש״פ שמיני תשכ״ט)",[["44","44","ראה פרדס שער ד׳ פ״ה ביאור מאמר הת״ז אנת הוא דאפיקת. המשך תער״ב פקכ״ט (וש״נ). ד״ה ויסעו מרפידים תש״ג (פ״ה) ואילך."],["45","45","להעיר מלקו״ש ח״ד ע׳ 1335 אשר תיבת „היום“ שמורה על העדר השינוי נאמרה בפסוק „וידעת“ דוקא, בו מדובר בהיחוד מלמטה למעלה ולא בפסוק „אתה הראת“ שבו מבואר יחוד הוי׳ ואלקים מלמעלה למטה, עיי״ש."],["46","46","מלאכי ג, ו. והכתוב בתמי׳ איך לא כליתם ?! (תו״א סז, א. לקו״ת ר״ה סא, ד)."],["47","47","ראה תניא פל״ב."],["48","48","ראה לקו״ת מסעי שם, ב."],["49","49","תהלים פה, יא."],["50","50","הנעשה ע״י יחוד חסד ואמת — דמשה ואהרן (שמו״ר שם) — וראה אוה״ת תצוה ע׳ א׳תקפב. שמע״צ ריש ע׳ א׳תשצה."],["51","51","תניא פל״ז."]]],[1300171130,"<h3>שמיני ד</h3>\nא. „כל הולך על גחון וכל הולך על ארבע עד כל מרבה רגלים וגו׳“¹ — איז רש״י מעתיק (אין ערשטן דיבור המתחיל) „הולך על גחון“ און איז מפרש: „זה נחש ולשון גחון שחיי׳ שהולך שח ונופל על מעיו“.\nפארוואס רש״י טייטשט „הולך על גחון — זה נחש“, איז מובן אין פשטות: דער איינציקער ארט אין תורה וואו מ׳געפינט אן ענלעכן לשון (ביי שרצים) איז ביים נחש (אין פ׳ בראשית²), וואו עס שטייט „על גחונך תלך“. איז דערפון מוכח, אז אויך „הולך על גחון“ מיינט — נחש³.\nמ׳דארף אבער פארשטיין דעם סיום פון פרש״י — „ולשון גחון שחיי׳ שהולך שח ונופל על מעיו“: ווי געזאגט, שטייט שוין אין פ׳ בראשית „על גחונך תלך“, אבער דארטן איז רש״י ניט מפרש וואס איז „לשון גחון“ (נאר אז „רגלים היו לו ונקצצו“) — איז ניט מובן: רש״י האט דאך געדארפט מפרש זיין דעם טייטש פון „גחון“ דעם ערשטן מאל ווען עס שטייט אין חומש, און ניט פארלאזן זיך אויף זיין פירוש אין פ׳ שמיני?\nב. לכאורה וואלט מען געקענט ענטפערן, אז רש״י איז ניט מפרש (אין פ׳ בראשית) „על גחונך תלך“, ווייל דער טייטש פון „גחון“ איז מובן מאליו — און אויף איינעם פון צוויי אופנים:\nא) אויפן פסוק⁴ „ושם הנהר השני גיחון“ (וואס שטייט פאר „על גחונך תלך“) טייטשט רש״י: „גיחון — שהי׳ הולך והומה והמייתו גדולה מאד כמו וכי יגח⁵ שמנגח והולך והומה“; און עד״ז קען מען טייטשן „על גחונך תלך“: וויבאלד א נחש קריכט אויף דער ערד (ווי רש״י זאגט „רגלים היו לו ונקצצו“), ווערט זיין הליכה אנגערופן „על גחונך“ — (בלשון האבן עזרא⁶) „בעבור הרוח שיגיח ממנו“ ד.ה. רש״י פארלאזט זיך אויף זיין פירוש אין פריערדיקן פסוק — „גיחון“⁷.\nב) „גחון“ מיינט — מעיים, ווי דער תרגום⁸ טייטשט „על גחונך תלך — על מעך תיזיל“ [אדער „חזה“ — כפירוש האבן עזרא⁶]; און רש״י דארף עס ניט מפרש זיין ווארום דאס איז א ווארט אין לשון־קודש וואס דער תלמיד ווייס זיין פירוש [פונקט ווי ער ווייס דעם טייטש פון „מעיים“ (אדער פון „חזה“)]⁹.\nאבער לפי זה איז שווער לאידך גיסא: וואס איז רש״י׳ס הכרח אז דא איז דער פירוש פון „הולך על גחון“ ניט ווי בא על גחונך תלך — ווי דער ראב״ע דא איז מפרש — [ניט „הולך והומה כו׳“, אדער (כפירוש התרגום) (אויך דא)",[["1","1","פרשתנו יא, מב."],["2","2","ג, יד."],["3","3","ראה גם ראב״ע כאן."],["4","4","בראשית ב, יג."],["5","5","משפטים כא, כח."],["6","6","בראשית ג, יד."],["7","7","ואף שהראב״ע שם כ׳ „זה דרך דרש“ — הוא לשיטתי׳ דגם ב„גיחון“ כתב כן, אבל רש״י מפרש כן שם סתם — בלי להוסיף שזהו דרש."],["8","8","ועד״ז בתיב״ע שם. ת״י שם (הובא בערוך ע׳ שחף). ועד״ז בת״א, תיב״ע ות״י כאן."],["9","9","אבל דוחק הוא — שהרי תיבה זו בלתי רגילה. ובפרט שגם מפרשי התורה שקו״ט בפירושה."]]],[1300171131,"„מעוהי“], נאר „לשון גחון שחיי׳ וכו׳“¹⁰?\nג. דערנאך איז רש״י מעתיק „כל הולך“¹¹ און איז מפרש: „להביא השלשולין ואת הדומה לדומה“.\nאיז ניט מובן:\nא) אמת טאקע אז „כל“ איז א ריבוי, אבער פונוואנען איז די ראי׳ ע״ד הפשט¹² אז ער איז מרבה צוויי זאכן: א) שלשולין, ב) ואת הדומה לדומה¹³?\nב) די קשיא ווערט נאך שטארקער: די דרשה איז דא אין תורת כהנים¹⁴ און גמרא¹⁵. דער לשון פון רש״י „ואת הדומה לדומה“ שטייט אין תורת כהנים, אבער אין גמרא איז דער לשון „ואת הדומה לשילשול“¹⁶.\nאיז לויט דער גירסא פון גמרא קען מען לערנען (בדוחק עכ״פ) אז „כל“ איז מרבה בלויז איין זאך: שלשול והדומה לשלשול. ד.ה. „שלשול“ איז א דוגמא פון דער מין וואס מ׳לערנט אפ פון דעם ריבוי, וואס איז כולל יעדען שרץ וואס איז דומה צו שלשול (ופשיטא — שלשול גופא);\nאבער לויט דער גירסא פון תו״כ — „ואת הדומה לדומה“ — איז מודגש אז דאס זיינען צוויי ריבויים (צוויי „מדרגות“): א) „שלשול“ וואס איז דומה לנחש, ב) „ואת הדומה לדומה“ — שרצים וואס זיינען (ניט דומה לנחש, נאר) דומה לשלשול וואס ער איז אליין בלויז א דומה לנחש¹⁷.\nאון רש״י קלייבט אויס די גירסא פון תו״כ און ניט די גירסא פון גמרא!\nג) פארוואס איז רש״י מעתיק פון פסוק אויך „(כל) הולך“ — דער ריבוי איז דאך בלויז פון ווארט „כל“¹⁸?\nנאכמער: גלייך שפעטער בכיוצא בזה איז רש״י מעתיק (פון די ווערטער¹⁹ „וכל הולך על ארבע“) נאר דעם ווארט „כל“²⁰ און איז מפרש „להביא את החפושית וכו׳“ — און דא איז רש״י מוסיף ומעתיק אויך „הולך“?",[["10","10","ודוחק לומר דכוונת התרגום היא [לא שפירושו של „גחון“ הוא „מעיו“, כ״א) כברש״י ש„הולך שח ונופל על מעיו“ (והפירוש ד„גחון“ הוא „לשון שחיי׳“). אבל ראה רד״ק בראשית שם. ובת״י כאן (ועד״ז בבראשית שם. וראה פ׳ לתרגום ירושלמי כאן): „כל הולך (על גחון) — כל דשחף כו׳“."],["11","11","הטעם שרש״י מקדים פירושו על „הולך על גחון“ קודם פירושו על תיבות „כל הולך“ — מובן בפשטות, כי בתחילה מפרש העיקר „הולך על גחון“, ואח״כ — ההוספה ד„כל הולך גו׳“ (ועד״ז ב„וכל הולך על ארבע“)."],["12","12","כי אף שדרשא זו מקורה בגמ׳ ותו״כ כדלקמן בפנים — הרי רש״י מעתיק בפירושו רק דרז״ל השייכים לפשש״מ, ובפרט בנדו״ד שלא כתב ע״ז שהוא דרש, מובן שפירושו זה מוכרח בפשטות הכתובים."],["13","13","ולהעיר מגירסת הרי״ף והרא״ש בחולין שם: „כל לרבות שלשול קטן“ (ותו לא)."],["14","14","עה״פ."],["15","15","חולין סז, ב."],["16","16","ובדק״ס חולין שם מביא מכת״י דגם שם הגירסא היא כבתו״כ."],["17","17","ראה באר מים חיים (לאחי המהר״ל) ודבק טוב כאן. וראה ג״כ רא״ם כאן. פי׳ הראב״ד לתו״כ שם. ולהעיר מהגירסא ברש״י כת״י: השלשול ואת הדומה לו ואת הדומה לדומה."],["18","18","וכבחולין שם: „כל לרבות השילשול וכו׳“ (ובתו״כ שם: כל הולך על גחון להביא כו׳)."],["19","19","אף שבכתוב נאמר „וכל“ — כ״ה גם בחולין ותו״כ שם. וי״ל שאי״ז ד״ה חדש (בפירש״י) והעתקת לשון הכתוב, כ״א חלק מד״ה הקודם („הולך על ארבע“) ולכן מסתפק בהעתקת לשון הכתוב הנוגע לכאן („כל“). ועד״ז בד״ה „הולך על גחון“."],["20","20","אף שבחולין ותו״כ שם מעתיק „כל הולך“ (אבל ברי״ף ורא״ש שם: „כל“)."]]],[1300171132,"ד. דערנאך איז רש״י מעתיק „הולך על ארבע“ און איז מפרש: „זה עקרב“ (וועלכער איז דער איינציקער שרץ וואס איז „הולך על ארבע“); און דערנאך איז ער מעתיק, כנ״ל, „כל“ און איז מפרש: „להביא את החפושית אשקרבו״ט בלע״ז ואת הדומה לדומה“.\nאיז אויך דא ניט מובן (ע״ד הנ״ל ס״ג):\nא) פון וואנען נעמט רש״י פון פשט הכתובים אז דער „כל“ איז מרבה צוויי זאכן — (א) החפושית (ב) ואת הדומה לדומה²¹?\nב) פארוואס קלייבט אויס רש״י די גירסא פון תו״כ און ניט פון גמרא — „ואת הדומה לחיפושית“?\nה. שפעטער שטעלט זיך רש״י אויף „מרבה רגלים“ און איז מפרש: „זה נדל שרץ שיש לו רגלים מראשו ועד זנבו לכאן ולכאן וקורין צינטפיד״ש“ (און מיט דעם איז רש״י מסיים זיין פירוש אויף דעם פסוק).\nדאס וואס רש״י איז מאריך אז „נדל“ „זה שרץ שיש לו רגלים מראשו ועד זנבו לכאן ולכאן וקורין צינטפיד״ש“, און זאגט ניט בקיצור „זה נדל צינט־פיד״ש בלע״ז“ — איז פארשטאנדיק: רש״י באווארנט: עס זיינען דאך פאראן א סך שרצים מיט הרבה רגלים, פאר־וואס זאגט מען אז „מרבה רגלים“ זה נדל? דעריבער איז רש״י מסביר, אז דאס איז א שרץ וואס זיין גאנצער גוף האט רגלים, „מראשו ועד זנבו (און) לכאן ולכאן“, און דערפאר „וקורין“²² רופט מען אים ע״ש ריבוי הרגלים — „צינטפיד״ש“ (— „מאה רגלים“²³); און דאס איז דער שרץ וועלכן די תורה מיינט מיט „מרבה רגלים“.\nפארוואס איז אבער רש״י דא ניט מפרש דעם ווארט „כל (מרבה רגלים)“ וואס שטייט אין פסוק, אז ער קומט מרבה זיין אויך אנדערע שרצים וואס זיינען מרבה רגלים און דומה לנדל²⁴, דומה ואת הדומה לדומה²⁴*?\nדער פלא איז נאך גרעסער: סיי אין תו״כ און סיי אין גמרא שטייט טאקע אז „עד כל (מרבה)“ איז מרבה „את הדומה ואת הדומה“ — און רש״י ברענגט די דרשות רז״ל אויף די ערשטע צוויי מאל וואו ס׳שטייט „(ו)כל“ אין פסוק, און ניט ביים דריטן מאל?\nו. דער ביאור בכל זה:\nווי געזאגט פריער, פון דעם וואס דער פסוק נוצט דעם לשון „(הולך על) גחון“ — א לשון וואס שטייט נאר ביי נחש — איז מוכח אז דערמיט מיינט ער א נחש („זה²⁵ נחש“); ועד״ז „הולך על ארבע“: וויבאלד אז דער איינציקער",[["21","21","ובדפוס שני דרש״י תיבות „ואת הדומה לדומה“ ליתא כאן. וראה לקמן הערה 24."],["22","22","וראה גם פירש״י חולין שם (ד״ה נדל): „מאה רגלים קורין לו“."],["23","23","ל׳ רש״י הנ״ל."],["24","24","בדפוס שני דרש״י איתא: „עד כל — לרבות הדומה“. אבל ד״ה זה בא קודם לד״ה „מרבה — זה נדל וכו׳“. ואולי יש כאן טה״ד, וצ״ל חלק מד״ה הקודם (בהמשך ל„כל — להביא את החפושית כו׳“). וראה לעיל הערה 21. 24*) ל׳ הש״ס חולין שם, אף שבנוגע לנחש ועקרב לא כתב כן, כנ״ל. ואכ״מ."],["25","25","משא״כ עה״פ (לעיל יא, כז) „על כפיו“, פרש״י: „כגון כלב ודוב וחתול“ (וגם אינו מפרש הריבוי ד„וכל הולך גו׳“) — אף שבתו״כ שם: „זה הקוף, כל להביא כו׳“ — כי הפירוש ד„וכל הולך על כפיו“ עפ״י הפשט הוא: כל החיות שבסוג הזה (ורש״י מביא דוגמאות אחדות), משא״כ כאן שמוכרח לפרש „זה נחש“, „זה עקרב“ (ובמילא — ד„כל“ בא לרבות). וראה לקמן בפנים ס״ט."]]],[1300171133,"שרץ וואס איז „הולך על ארבע“ איז אן עקרב, איז דערפון מוכח אז די תורה רעדט וועגן עקרב („זה²⁵ עקרב“).\nאבער פארוואס זאגט דער פסוק „הולך על גחון“, „הולך על ארבע“ (וואס מיינען נחש ועקרב) און זאגט ניט בקיצור ובפירוש: נחש ועקרב?\n[בשלמא וואס עס שטייט „מרבה רגלים“ (ניט „נדל“) — קען מען ענטפערן, ווייל „נדל“ איז ניט קיין לשון־המקרא ווארט, מ׳געפינט אים ניט אין תנ״ך (נאר בתו״כ דא ובמשנה²⁶, וואס רש״י ברענגט כו״כ פעמים תו״כ בפי׳ בספר ויקרא); אבער נחש און עקרב זיינען דאך ווערטער וואס שטייען כמה פעמים אין חומש].\nמוז מען זאגן אז מיט „הולך על גחון“ רעדט די תורה וועגן נחש ניט אלס כללות הנחש וואס האט כו״כ תכונות, נאר דוקא אלס אזא וואס האט די תכונה פון „הולך על גחון“; איז במילא מובן אז „כל הולך על גחון“ איז מרבה שרצים וואס זיינען דומה צו נחש דוקא אין דעם ענין פון „הולך על גחון“ („שלשולין כו׳“), ועד״ז ביי „כל הולך על ארבע“²⁷.\nאון דערפאר קען דער פסוק ניט זאגן „נחש“ אדער „עקרב“, ווייל דעמאלט וואלט „כל“ מרבה געווען נאר שרצים פון מין נחש ועקרב, אדער — אפילו אז מ׳וואלט מרבה געווען אויך דומה להם וואלט מען ניט געוואוסט אין וואס דארפן זיי זיין דומה — אין דעם ענין פון „הולך על גחון“ און „הולך על ארבע“, אדער אין אנדערע פרטים.\nועפ״ז איז אויך מובן בפשטות פאר־וואס רש״י קען דא ניט לערנען „גחון“ — „בעבור הרוח שיגיח ממנו“ (ע״ד פירושו אויף „גיחון“) — ווייל „כל הולך על גחון“ קומט דאך מרבה זיין אנדערע שרצים וואס זיינען „הולך על גחון“, און מ׳געפינט ניט קיין אנדער שרץ וואס איז הולך ומגיח רוח.\nז. עפ״ז איז אויך מובן אז רש״י קען דא ניט טייטשן (כפי׳ התרגום) „על גחון“ — „על מעוהי“²⁸, ווייל דעמאלט איז ניט מובן: פארוואס נוצט דער פסוק דעם לשון „גחון“ וואס איז מכריח אז „זה נחש“ (ווייל דער לשון שטייט נאר ביי נחש כנ״ל) און „כל הולך גו׳“ איז מרבה אנדערע שרצים — עס האט דאך געקענט שטיין א לשון וואס איז מלכת־חילה כולל אלע שרצים (פון דעם סוג)²⁹, ווי „הולך על מעיו“²⁹* וכיו״ב?\nמוז מען זאגן, אז „הולך על גחון“ איז א תכונה וואס איז טאקע דא נאר ביים נחש; און דערפאר טייטשט רש״י „ולשון גחון שחיי׳³⁰ שהולך שח ונופל על",[["26","26","מקואות פ״ה מ״ג. וראה פרש״י (מקץ מג, ל) ובלשון משנה . . ובלשון ארמי . . ובמקרא."],["27","27","שהרי „שלשול“ הוא תולעת (ולא מין נחש). וכן „חפושית“ אינו מין עקרב (ראה רמב״ם הל׳ פרה פ״ט הי״א. ולהעיר מרמב״ם הל׳ מאכלות אסורות פ״ב הי״ז: נחשים ועקרבים וחפושית ונדל וכיו״ב)."],["28","28","נוסף ש״י״ל שלא נמצא עוד בקרא שגחון פירושו מעוהי, משא״כ שיהי׳ פירושו שחיי׳ — כנסמן לקמן הערה 30."],["29","29","ע״ד הנ״ל הערה 25. 29*) שהרי נמצא לו חבר בקרא (תולדות כה, כג. וראה פרש״י בא יב, ט. ויקרא א, ט) — אבל מובן שאין לומר „הולך על קרבו“, כי לשון „קרבו“ הוא ע״ש שנמצא בקרבו — בפנים (למיעוטי עורו המכסה עליו ושעליו הולך)."],["30","30","ומצינו לו חבר בקרא (מיכה ד, י) „חולי וגחי“, וכפרש״י שם: „כרעי ושחי“ (ומביא דוגמא) על גחונך וכן בלשון משנה* (תוספתא מו״ק פ״א ה״ד) *) ראה לקו״ש (חי״ד ע׳ 115. חט״ו ע׳ 348 הערה 6) דבפי׳ עה״ת קורא רש״י גם לתוספתא — „לשון משנה“."]]],[1300171134,"מעיו“: פון אנהויב גייט ער איינגעבויגן (ניט „על מעיו“), נאר שפעטער איז ער „נופל על מעיו“: משא״כ „שלשולין“ וכיו״ב וואס מ׳איז מרבה פון „כל“, קריכן לכתחילה על מעיהם.\n[און עד״ז „כל הולך על ארבע“: נאר אן עקרב איז „הולך על ארבע“ כפשוטו, משא״כ „חפושית“ וכיו״ב וואס מ׳איז מרבה פון „כל“, האבן „יותר מארבעה רגלים אלא שהעליונים אינם משמשין כ״כ“³¹].\nאון דערפאר איז רש״י מעתיק פון פסוק „כל הולך“: מיט דעם איז ער מדגיש אז די ענלעכקייט צווישן זיי מיטן נחש איז בלויז אין דער הליכה וואס קומט ארויס שפעטער ביים נחש, נאכ־דעם וואס ער איז „נופל על מעיו“: אבער דער ענין פון „גחון“ — „לשון שחיי׳ שהולך שח“ — איז ביי זיי טאקע ניטא³².\nח. עפ״ז איז מובן וואס רש״י קלייבט אויס גירסת התו״כ „ואת הדומה לדומה“. ער לאזט אונז דערמיט וויסן:\nא) דער „כל“ קומט ניט מרבה זיין נאך שרצים אין מין הנחש ועקרב (וואס דע־מאלט איז דאס מרבה אויך אזעלכע וואס „אין דומין זה לזה“³³), נאר שרצים וואס האבן א דמיון צו נחש ועקרב אין דעם ענין פון „הולך על גחון .. על ארבע“.\nב) לאידך: אפילו „שלשולין“ זיינען ניט דומה לנחש בכל פרטיו, אפילו ניט אין דעם ענין פון „הולך על גחון“, ס׳איז צווישן זיי בלויז א קצת דמיון (ווארום א נחש איז סו״ס „נופל על מעיו“): און עד״ז „חפושית“ האט נאר א קצת דמיון צו עקרב אין דעם ענין פון „הולך על ארבע“ (ווייל „עליונים אינם משמשין כ״כ“):\nאון וויבאלד אזוי, קען דאך דער „כל“ מרבה זיין אפילו „הדומה לדומה“ — אויב נאר עס האט אין זיך אט דעם קצת דמיון בענין „הולך על גחון“ ו„על ארבע“.\nט. עפ״י כהנ״ל איז אויך מובן דער חילוק צווישן „כל הולך על גחון וכל הולך על ארבע“ און „כל מרבה רגלים“ (וואו רש״י איז ניט מפרש תיבת „כל“):\n„הולך על גחון“ און „הולך על ארבע“ זיינען פאראן (בשרצים) נאר ביי נחש ועקרב, און דערפאר, ווען דער פסוק איז מוסיף „כל הולך על גחון וכל הולך על ארבע“ קען מען ניט טייטשן כפשוטו — אלע שרצים וואס גייען „על גחון . . . ארבע“ — ווייל חוץ פון נחש ועקרב איז ניטא א שרץ וואס איז הולך על גחון או על ארבע; ובמילא מוז מען זאגן אז „כל“ דא איז ניט כפשוטו, נאר איז בא לרבות.\nמשא״כ „מרבה רגלים“ — מער ווי ארבע — איז דא ביי א ריבוי שרצים (כאטש — חוץ בא נדל — איז בא זיי דא פלאץ בגופם אויף מער מרבה זיין ברגליים) ובמילא איז דער טייטש פון „כל מרבה רגלים“ כפשוטו (און רש״י דארף עס ניט מפרש זיין): אלע שרצים וואס זיינען אין דעם סוג פון „מרבה רגלים“.\nיו״ד. מ׳דארף אבער פארשטיין: לויט דעם, ווי טייטשט רש״י „מרבה",[["","","„כותל הגוחה לרה״ר“. וגם בלשון ארמי (גמרא) מצינו „גחין ותלחוש“ (ב״מ נט, א. ועד״ז בכ״מ)."],["31","31","רא״ם כאן. ועד״ז בפי׳ הראב״ד לתו״כ כאן."],["32","32","משא״כ ב„הולך על ארבע“ שה(קצת) דמיון בין „חפושית“ ועקרב הוא ב„הולך על ארבע“."],["33","33","פרש״י לעיל יא, יג („כל עוף שנאמר בו למינהו . . יש באותו המין שאין דומין זה לזה“)."]]],[1300171135,"רגלים — זה נדל וכו׳“, ניט שרייבענדיק אפילו „כגון נדל“²⁹?\nאיז דער ביאור בזה: וויבאלד אז אין די ערשטע צוויי פאלן — „הולך על גחון גו׳ הולך על ארבע“ — מיינט דער פסוק איין שרץ — נחש ועקרב (וכנ״ל בארוכה) — איז מסתבר צו זאגן, אז אויך אין דריטן פאל — „מרבה רגלים“ — מיינט מען איין שרץ — נדל; און „כל מרבה רגלים“ מיינט אלע סוגים אין דעם ענין (מין) פון „מרבה רגלים“ (און רש״י דארף עס ניט מפרש זיין ווייל ס׳איז מובן מאליו, ס׳איז ע״ד ווי עס שטייט פריער כמה פעמים „למינו“ וכיו״ב).\nיא. פון די הוראות אין עבודת ה׳ — ובהקדים:\nלכאורה איז נאך אלץ ניט גלאטיק (עכ״פ בפנימיות הענינים): סוף־סוף איז הליכת הנחש „על מעיו“ („הולך שח“ איז דאך נאר בתחילת הליכתו) — פארוואס שרייבט ניט די תורה „הולך על מעיו“ און דערמיט כולל זיין אלע שרצים פון דעם סוג (אויך נחש)?\nנאר אין דעם איז דא א הוראה אין עבודת ה׳: חז״ל³⁴ זאגן אויף נחש „דא יצה״ר“. און דאס זאגט תורה: דער יצה״ר קומט ניט לכתחילה באווירקן א אידן ער זאל ווערן א „הולך על מעיו“ — גיין, קריכן און ליגן אין עניני אכילה וכו׳ ענינים ארציים³⁵. ער הייבט אן מיט „הולך שח“: זיין קאפ איז אראפגעלאזט, איינגעבויגן, עס פעלט אים אין „שאו מרום עיניכם וראו גו׳“³⁶ — אבער דאס דערפירט, אז סוכ״ס ווערט ער ר״ל א „נופל על מעיו“. ווי חז״ל³⁷ זאגן „כך אומנתו של יצה״ר היום אומר לו עשה כך וכו׳ (ביז) עבוד ע״ז“.\nאון דערפאר איז די עצה ווי צו ביי־קומען דעם „נחש“ איז דורך ליגן אין ענינים פון מרום — תורה³⁸ בכלל, ובמיוחד אין נסתר ופנימיות התורה³⁹, וואס דאס באווארנט דעם ענין פון „הולך שח“.\nאון אויך דאס איז מרומז אין אונ־זער פסוק, ווי דער מהרש״א איז מבאר דעם מרז״ל⁴⁰ „לפיכך נקראו ראשונים סופרים שהיו סופרים כל האותיות שבתורה שהיו אומרים וי״ו דגחון חציין של אותיות של ס״ת וכו׳“: האותיות אינן מורים רק על שמותיו של הקב״ה שהוא הנסתר גמור של התורה⁴¹ ולפי שהסטרא דשמאלא וכח הטומאה הוא נחש הקדמוני . . וע״כ הפסיק באותיות התורה בוי״ו דגחון לרמוז כפי אותיות התורה שהן כולן שמותיו של הקב״ה⁴²",[["34","34","זח״א לה, ב."],["35","35","להעיר מפרש״י (ויקרא א, טו): בנוצתה. עם בני מעי׳ ונוצה ל׳ דבר המאוס כו׳ וזהו שת״א באוכלי׳."],["36","36","ישעי׳ מ, כו."],["37","37","שבת קה, ב."],["38","38","דתורה היא בחי׳ „שמים“ — תו״א בתחילתו. ובכ״מ. ולהעיר מאוה״ת ואתחנן (ריש ע׳ שו) ד„נחש בריח לעומת בריח התיכון שבקדושה . . ע״י הקול קול יעקב בעסק התורה בחי׳ בריח התיכון כו׳ דוחה ומפיל נחש בריח דקליפה כו׳“. וראה לקמן בפנים סי״ב ובהערות 56, 58."],["39","39","דבתורה עצמה היא בחי׳ שמים שבתורה — ראה לקו״ש חי״ד ע׳ 1038־9. וש״נ. וראה אוה״ת פרשתנו (ע׳ רמ) וסד״ה אמרז״ל לפיכך תרצ״ט, דוי״ו דגחון שמפסיק כח הנחש (כדלקמן בפנים) הוא בחי׳ פנימיות התורה. וראה אוה״ת פרשתנו (ע׳ רמט־רנ) שהוא בחי׳ עה״ח, ולכן בכחו לברר הנחש בחי׳ עה״ד, עיי״ש."],["40","40","קידושין ל, סע״א. חדא״ג שם."],["41","41","וראה תו״א שם (א, רע״ג) דתושב״כ ש„היא רק בחי׳ אותיות . . שהן שמותיו של הקב״ה“ הוא בחי׳ „שמים“ שבתורה."],["42","42","רמב״ן בהקדמתו עה״ת. יונת אלם פכ״ט. ועד״ז זח״ב פז, א. ובכ״מ."]]],[1300171136,"אין כאן מקום כלל לכח הטומאה דוי״ו דגחון מפסיקו.\nיב. אט דעם „הפסק“ פון כח הנחש דארף זיין ניט נאר דורך דער עבודה פון ביטול ואיבוד כח הנחש, נאר אויך דורך בירור הנחש, ביז ער ווערט נתהפך לקדושה; ווי חז״ל⁴³ זאגן אויפן פסוק⁴⁴ „גם אויביו ישלים אתו“, „זה הנחש“, ד.ה. דער נחש איז טאקע „אויביו“, כמש״נ⁴⁵ „ואיבה אשית בינך ובין וגו׳“, פונדעסטוועגן וועט דער נחש מאכן שלום מיט אים⁴⁶.\nאון דער בירור פון נחש דקליפה איז דורך מגלה זיין דעם שורש פון נחש דקליפה, אט דאס וואס שטון לשם שמים נתכוון⁴⁷ — בחי׳ נחש דקדושה. ווי ס׳איז מבואר⁴⁸ אין דעם ענין פון „נחש הנחושת“ וואס משה רבינו האט געמאכט⁴⁹, אז דורך „והביט אל נחש הנחושת“⁴⁹ ו„מסתכלין כלפי מעלה“⁵⁰, דורך דער ראי׳ פון בחי׳ נחש דקדושה, דער שורש פון נחש דקליפה, איז גע־ווארן „וחי“ — דער בירור פון נחש דקליפה⁵¹.\nאון אויך דער „ישלים“ „שלום“ צווישן נחש דקדושה און נחש דקליפה איז נרמז אין אונזער פסוק:\nדער צ״צ⁵² איז מבאר ענין הנ״ל „וי״ו דגחון חציין של אותיות של ס״ת“, אז דער וי״ו רבתי פון „גחון“ איז מרמז אויף ספירת התפארת ווי זי איז עולה עד הכתר, און דערפאר האט זי בכח צו מחבר זיין די צוויי חצאי ס״ת, וואס זיינען בחי׳ חסד וגבורה [ע״ד⁵³ הידוע⁵⁴ בענין חצות לילה, אז דאס איז מחבר די צוויי חצאי לילה וואס דער ערשטע חצי לילה איז יונק פון דין און די צווייטע פון חסד]; און דערפאר איז דער וי״ו דגחון מפסיק כח הנחש, ווארום יניקת הנחש איז פון ריבוי הצמצומים מסטרא דשמאלא, אבער דורך דער התכללות פון ימין און שמאל (ע״י ספירת התפארת) ווערט נפסק זיין יניקה.\nוי״ל, אז אויך דער „שלום“ צווישן נחש דקליפה און (שרשו) נחש דקדושה איז דורך דעם וי״ו רבתי, ווארום אט דער חיבור צווישן „מעלה“ און „מטה“ — דלא כטעות המין אז „מפלגך לעילאי דהורמיז מפלגך לתתאי דאהורמיז“⁵⁵ — איז דורך דעם קו האמצעי⁵⁶ וואס איז מבריח מן הקצה (הכי עליון) אל הקצה (הכי תחתון)⁵⁷, און דערפאר איז ער עושה שלום צווישן פמליא של מעלה און פמליא של מטה⁵⁸, ביז אז אויך",[["43","43","ירושלמי תרומות פ״ח סה״ג. ב״ר רפנ״ד."],["44","44","משלי טז, ז."],["45","45","בראשית ג, טו."],["46","46","ראה אוה״ת בראשית מז, סע״ב ואילך."],["47","47","ב״ב טז, א. וראה (סנה׳ נט, ב) שמש גדול כו׳ אלמלא נתקלל נחש כו׳ נחשים טובים."],["48","48","לקו״ת חוקת ד״ה ויעש משה."],["49","49","חוקת כא, ט."],["50","50","משנה ספ״ג דר״ה. הובא בפרש״י חוקת שם, ח."],["51","51","ראה גם אוה״ת שם (מח, א)."],["52","52","אוה״ת פרשתנו (ע׳ רמ. רמב ואילך). וראה ג״כ סד״ה כל הולך תרכ״ז."],["53","53","אוה״ת פרשתנו שם (ריש ע׳ רמד)."],["54","54","זח״א צב, סע״ב. נתבאר באוה״ת לך ד״ה ויחלק עליהם פ״ה ואילך."],["55","55","סנהדרין לט, א. לקו״ת שה״ש לח, ג. ובכ״מ."],["56","56","ע״ד הידוע דמ״ת הי׳ „בחודש השלישי“ — כי ענינו חיבור מעלה ומטה, ביטול הגזירה דעליונים לא ירדו כו׳ ותחתונים לא יעלו כו׳ (שמו״ר פי״ב, ג)."],["57","57","ראה זח״א א, ב. ח״ב קעה, ב. ועוד. נתבאר בד״ה פדה בשלום תרע״ג (בהמשך תער״ב). ד״ה יחיינו תש״ז פי״ב. ועוד."],["58","58","וי״ל דבחיבור ב׳ חצאי תורה ע״י וי״ו דגחון, נכלל גם חיבור מעלה ומטה שבתורה עצמה, דתורה"]]],[1300171137,"אינעם נחש דלמטה ווערט נתגלה זיין שורש, בחי׳ נחש דקדושה.\nאון אט דער „שלום“ וועט זיין בגילוי בביאת משיח צדקנו, וואס אויך משיח ווערט אנגערופן „נחש“⁵⁹, וועט ער אויפטאן דעם „ישלים אתו“, ובקרוב ממש.\n(משיחת ומאמר ש״פ שמיני תש״ל)",[["","","היא „דברי כאש“ (ירמי׳ כג, כט. ברכות כב, א), ולאידך ניתנה למטה דוקא, במקום ש„למצרים ירדתם . . יצה״ר יש ביניכם“ (שבת פח, סע״ב ואילך)."],["59","59","ראה אוה״ת פרשתנו (ע׳ רמ. רמב). וש״נ. וראה גם ביאוה״ז (להצ״צ) ע׳ תקנו. אוה״ת ואתחנן (ע׳ שו). ועוד."]]],[1300171138,"<h3>תזריע</h3>\nא. אויפן פסוק<sup data-n=\"1\">1</sup> „וביום השמיני ימול בשר ערלתו\" דרש'נען רז\"ל אין תו\"כ<sup data-n=\"2\">2</sup> (און אין גמרא<sup data-n=\"3\">3</sup>: „ביום ולא בלילה\"; און לויט דעם קומט אויס, אז דער דין אין מלין בלילה<sup data-n=\"4\">4</sup> איז נתחדש געווארן ערשט נאך מ\"ת, און פאר מ\"ת האט מילה געמעגט זיין אויך בלילה.\nאפילו לויט דעם צווייטן מקור פון דעם דין (אין מס' שבת<sup data-n=\"5\">5</sup> אז מ'לערנט עס אפ פון „ובן שמונת ימים גו'\" וואס שטייט אין פ' לך<sup data-n=\"6\">6</sup> (ובפרט אז תוספות 7 זאגט אז דער עיקר הלימוד איז פון דעם פסוק) — איז דאס נאר בנוגע מילה בזמנה, אבער אז מילה שלא בזמנה מוז זיין ביום לערנט מען אפ 8 פון (דעם וא\"ו) „וביום השמיני גו'\" אין אונזער פרשה (ווי תוספות 9 איז דאס מבאר), ובמילא איז דאס ערשט נתחדש געווארן נאך מ\"ת.\nב. דאס צו מסביר זיין, יש להקדים וואס עס שטייט אין מדרש 10, אז זייענ־דיק אין מצרים „הרבה מהן (פון אידן) לא היו מקבלים עליהם למול אמר הקב\"ה שיעשו הפסח וכיון שעשה משה את הפסח גזר הקב\"ה לד' רוחות העולם כו' הלכו ונדבקו באותו פסח כו' נתכנסו כל ישראל אצל משה א\"ל בבקשה ממך האכילנו מפסחך כו' הי' אומר כו' אם אין אתם נימולין אין אתם אוכלים כו' מיד נתנו עצמן ומלו כו'\".\nפון דעם מדרש קומט אויס, אז אידן האבן זיך מל געווען בליל פסח<sup data-n=\"11\">11</sup>; נאכמער: פון מדרש (ובפרט אין שה\"ש רבה) איז משמע אז משה רבינו האט בכלל ניט איבערגעגעבן צו אידן דעם ציווי „וכל ערל לא יאכל בו\" ביז (בײ־נאכט ווען) די אידן זיינען געקומען בעטן ביי משה'ן „האכילנו מפסחך\" 12.\nאיז ניט מובן: אמת טאקע אז מ'האט געמעגט מל זיין בלילה ווייל ס'איז געווען קודם מ\"ת, עס פאדערט זיך אבער א הסברה (עכ\"פ בפנימיות העני־נים): וויבאלד אז אידן („הרבה מהן\") האבן זיך דאן מל געווען (ניט מצד זיך אליין, נאר) מצד וואס „גזר הקב\"ה לד' רוחות כו'\", און דער ריח האט גורם געווען זיי זאלן וועלן עסן מפסחו של משה, האט דאך דער אויבערשטער געקענט טאן די זעלבע זאך (אדער כיו\"ב) קודם חשיכה און דאן זאל משה אנזאגן די אידן דעם ציווי „וכל ערל לא יאכל בו\" 13 און מ'זאל זיך מל זיין ביום ?14",[["1","1","פרשתנו יב, ג."],["2","2","עה\"פ."],["3","3","מגילה כ, א."],["4","4","מגילה שם (במשנה)."],["5","5","קלב, א."],["6","6","יז, יב."],["7","7","שבת שם ד\"ה ההיא. מגילה שם ד\"ה דכתיב."],["8","8","תו\"כ כאן. יבמות עב, ב."],["9","9","יבמות שם ד\"ה מר."],["10","10","שמו\"ר פי\"ט, ה. ועד\"ז בשהש\"ר פ\"א, יב (ג). פ\"ג, ו (ד). וכדלקמן בפנים."],["11","11","וראה גם פרש\"י בא יב, ו. בעל הטורים שם, יג."],["12","12","ראה שהש\"ר פ\"א שם, דבתחילה א\"ל „כל בן נכר גו'\", ואח\"כ — „וכל עבד איש מקנת כסף גו'\", ורק אח\"כ — „כל ערל לא יאכל בו\". וראה בהמצויין בהערה 10 דכשא\"ל משה דכך אמר לי הקב\"ה כל ערל לא יאכל בו „מיד\" מלו עצמם."],["13","13","בא יב, מח."],["14","14","וראה גם משכיל לדוד לפרש\"י בא שם."]]],[1300171139,"ג. דער יפה תואר 15 וויל זאגן: יתכן שהי' זה קודם חשיכה (און ברענגט דערויף צוויי הכרחים) שמשחשיכה שהוא יו\"ט אין מילה שלא בזמנה דוחה אותה 16, ועוד דאין מילה בלילה 17.\nמ'קען אבער אזוי ניט זאגן, ווייל פון דעם סיפור ווי ער ווערט געבראכט אין שה\"ש רבה 18 (אויפן פסוק 19 „עד שהמלך במסבו\") איז קלאר אז ס'איז געווען בלילה. דארט שטייט בפירוש, אז דאס איז פארגעקומען „עד שהמלך במסבו\" — „עד שמשה וישראל מסובין ואוכלין פסחיהם במצרים\", און אכילת פסח איז דאך „בלילה הזה\" 19*, בליל ט\"ו ניסן (און ניט „קודם חשיכה\"<sup data-n=\"20\">20</sup>.\nאון די צוויי הכרחים וואס ער ברענגט — (א) מילה שלא בזמנה איז ניט דוחה יו\"ט, (ב) אין מילה בלילה — זיינען ניט מכריח ווייל:\nא) ווי געזאגט פריער, איז דער דין אז אין מילה בלילה (ביי שלא בזמנה) ערשט נתחדש געווארן נאך מ\"ת 21,\nב) עד\"ז — געפינען מיר ניט קיין איסור מלאכה ביו\"ט ביי פסח מצרים 22. ווארום כאטש דער פסוק „וביום הראשון מקרא קודש וביום השביעי מקרא קודש יהי' לכם כל מלאכה לא יעשה בהם גו'\" שטייט אין פ' בא 23 — מוז מען אבער זאגן אז דער פסוק רעדט ניט וועגן פסח מצרים, ווארום פסח מצרים אינו נוהג אלא יום אחד 24, און אין דעם פסוק שטייט דאך „וביום השביעי מקרא קודש גו'\".\n[און מ'קען ניט זאגן אז דער פסוק זאגט דא צוויי באזונדערע דינים וועלכע זיינען ניט תלויים זב\"ז — (א) וביום הראשון מקרא קודש, וואס איז געווען שייך אויך בפסח מצרים, (ב) „וביום השביעי\" מקרא קודש\", וואס איז שייך נאר בפסח דורות — ווייל:\nא) אין פסוק שטייט „כל מלאכה לא יעשה בהם\", ד.ה. אז דער איסור מלאכה פון יום הראשון און פון יום השביעי",[["15","15","שמו\"ר שם. וכן תירץ גם בשו\"ת תורת חסד או\"ח סכ\"ה אות ר."],["16","16","שבת שם, ב. ולהעיר דאברהם נימול ביוהכ\"פ (פדר\"א פכ\"ט), או בט\"ו ניסן — יו\"ט דפסח (ראה תוד\"ה אלא — ר\"ה יא, א) — אף שקיים כהת\"ת עד שלא ניתנה. ויל\"ד דמכיון שאז נצטווה על המילה — דבו ביום שצוהו מל (תוס' שם. רש\"י לך יז, כג) — הו\"ז כמו מילה בזמנה ובמילא — דוחה שבת (ויו\"ט). וראה לקמן הערה 46*."],["17","17","וגם במילה שלא בזמנה קיי\"ל כת\"ק ביבמות (שם, סע\"א) דאין נימולין אלא ביום. ודוחק לומר (כמ\"ש בתורת חסד שם) דאתי כראב\"ש (ביבמות שם) דמילה שלא בזמנה נימולין בלילה."],["18","18","פ\"א שם."],["19","19","שה\"ש א, יב. 19*) בא יב, ח."],["20","20","זבחים נו, ב (במשנה). שם נז, ב. פסחים מא, ב. וראה תוספתא פסחים ספ\"ב (הובא בתוד\"ה עד שתחשך — פסחים צט, ב)."],["21","21","וכ\"כ ברש\"ש לשהש\"ר פ\"א שם."],["22","22","כמ\"ש בתוידו\"ס פסחים פ\"י מ\"ה. ועוד (ראה הדיעות בתו\"ש מילואים לפ' בא (כרך י\"א) סכ\"ו). וכן תירץ בשו\"ת יד אליהו (אמשטרדם, תעב) סנ\"א (ע\"פ המהרי\"ט). רש\"ש לשהש\"ר שם. וראה תורת חסד שם."],["23","23","יב, טז."],["24","24","פסחים צו, ב. וראה לקו\"ת צו יא, ד. סידור ד\"ה והגדת (רצו, ג). אוה\"ת וארא (ב' תקסט). שם ד\"ה והגדת (ויקרא כרך ג' ע' תשלא ואילך).* *) ומ\"ש באוה\"ת שם: ומ\"ש בסידור שבשאר הימים היו אוכלין חמץ הוא ט\"ס — בא בהמשך למש\"כ לפני זה דמפני שלא הספיק בצקת כו' גם אז לא אכלו חמץ כל ד' הימים, אף דאיסורו הי' רק יום אחד. וכן צ\"ל בהערות לסידור דף טב (שעב): דאי אכילת חמץ הי' רק יום אחד הוא ט\"ס."]]],[1300171140,"ווערן ביידע נכלל אין זעלבן ציווי. ב) אויף „כל מלאכה לא יעשה בהם\" שטייט אין מכילתא: „אין לי אלא יו\"ט האחרון שהוא אסור בעשיית מלאכה, יו\"ט הראשון מנין ת\"ל ביום הראשון מקרא קודש\". קומט דאך אויס פון מכילתא, אז דער עיקר האיסור שטייט אויף „ביום השביעי\", נאר דורכדעם לערנט מען אפ אויך „ביום הראשון\". און וויבאלד בפסח מצרים איז ניט געווען דער עיקר האיסור („ביום השביעי\"), פארשטייט מען במילא אז אויך דער איסור נוסף („ביום הראשון\") רעדט ניט וועגן פסח מצרים. ג) בא פסח מצרים איז בכלל ניט געווען קיין „יום הראשון\", נאר „יום אחד\"].\nד. אפילו לויט דער דיעה (פון ר\"ן<sup data-n=\"25\">25</sup> אז בפסח מצרים איז יע געווען א איסור מלאכה, קען מען פארענטפערן די קשיא אויפ'ן מדרש (ווי איז מילה שלא בזמנה דוחה יו\"ט) ובהקדים א דיוק אין לשון המדרש (אין שהש\"ר<sup data-n=\"26\">26</sup>: „כולם אחוזי חרב מלומדי מלחמה איש חרבו על ירכו 27, שבשעה שא\"ל משה כו' מיד כאו\"א נטל חרבו על ירכו ומל עצמו\" — דלכאורה: א) למאי נפק\"מ אז זיי האבן זיך מל געווען מיט א חרב — דער עיקר איז דאך אז זיי האבן זיך מל געווען „מיד\" ? ב) וואס איז די הדגשה „חרבו\" — זיין חרב — למאי נפק\"מ צי דער חרב איז זיינער אדער פון אימעצן אנדערש ?\nנאר דערמיט ווערט פארענטפערט די אויבענדערמאנטע שאלה: ווען איז מילה א מלאכה האסורה ביו\"ט, ווען זי ווערט געטאן כדרכה — באיזמל 28. אבער מילה בחרב איז א מלאכה שלא כדרכה און אזא מלאכה איז מותר מדאור־רייתא 29. דעריבער איז דער מדרש (און דער פסוק וואס ער ברענגט) מדגיש אז מ'האט זיך מל געווען בחרב.\nווען עס וואלט אבער געשטאנען חרב סתם, וואלט מען נאך אלץ געקענט מיינען אז דא רעדט זיך וועגן א חרב מיט וועלכן מ'איז זיך מל, ווי עס שטייט 30 „עשה לך חרבות צורים ושוב מול את בנ\"י שנית\" — דעריבער איז דער פסוק מדגיש „חרבו\" — זיין חרב: דער חרב פון „מלומדי מלחמה\", וואס איז דאך ניט קיין חרב מיט וועלכן מ'איז מל.\nועפ\"ז — אז בפסח מצרים האט מען זיך מל געווען בלילה — הדרא קושיין לדוכתא: פארוואס האט דער אוי־בערשטער ניט געמאכט אז מ'זאל זיך מל זיין ביום, קודם חשיכה ?\nה. וועט מען עס פארשטיין בהקדים נאך א תירוץ וואס ווערט געבראכט אין אחרונים 31 (אויף דער קשיא ווי האבן זיך די אידן מל געווען בלילה) — אז די נאכט פון יצי\"מ איז געווען (ווי עס",[["25","25","לפסחים קטז, א. וראה עוד דיעות בזה בתו\"ש שם. וכן מסיק בתורת חסד שם (אות ד)."],["26","26","פ\"ג שם. ועד\"ז בפ\"א שם."],["27","27","שה\"ש ג, ח."],["28","28","כלי' הש\"ס — שבת קל, סע\"א. ובכ\"מ. וברע\"ב כלים (פי\"ג מ\"ד): איזמל — תער קטן שמלין בו את התינוק. ולהעיר מרמב\"ם (הל' מילה פ\"ב ה\"א. נעתק בטושו\"ע יו\"ד סרס\"ד): ונהגו כל ישראל בסכין."],["29","29","שהרי הענין ד\"תקוני גברא\" (ראה שבת קו, א ובפרש\"י שם ד\"ה מה לי) מצד עצמו [גם את\"ל דבזה לא שייך הפטור דלא כדרכה] הוא רק שבות — ראה מנחת חינוך מוסך השבת (מלאכת מכה בפטיש). וראה השקו\"ט בחמדת ישראל בקונט' נר מצוה (נט, ד ואילך) ומסיק דלא כהמנ\"ח."],["30","30","יהושע ה, ב. ובתרגום (ופרש\"י) שם: אזמלון."],["31","31","שו\"ת יד אליהו שם. שמחת הרגל (להחיד\"א) פיסקא מעשה בר\"א כו'. אר\"א בן עזרי' כו'. ועוד."]]],[1300171141,"שטייט איז זהר<sup data-n=\"32\">32</sup> אין אן אופן פון „ולילה כיום יאיר\" 33, און במילא האט די נאכט געהאט א דין פון „יום\".\nפרעגט מען אויף דעם 34: אויב די נאכט פון יצי\"מ האט געהאט א דין פון יום, ווי האבן די אידן דעמאלט מקיים געווען די מצות וואס זיינען פארבונדן מיט לילה (אכילת פסח 35, מצה 36, מרור וכו') 37 ?\nמוז מען זאגן, אז דער דין פון יום בליל יצי\"מ איז געווען נאר לגבי מצות מילה, אבער ניט לגבי די מצות הנ\"ל. און דער חילוק איז פארשטאנדיק בפשטות: עס איז געווען א ציווי מפורש 38 אויף דעם: ואכלו את הבשר בלילה הזה גו' מתניכם חגורים גו'.\nו. דער ביאור בפנימיות הענינים 39 מיט וואס איז מצות מילה אנדערש וואס נאר לגבי איר איז די נאכט געווען בבחי' „ולילה כיום יאיר\": דער ענין פון יצי\"מ איז געווען אינגאנצן בדרך פון „פסח\" — דילוג 40, העכער פון מדידה והגבלה פון טבע; ווארום עפ\"י טבע האבן אידן ניט געקענט ארויסגיין פון מצרים (סיי בגשמיות — „לא הי' עבד יכול לברוח ממצרים\" 41, און סיי ברוחניות — זיינען אידן געווען מושקע אין מ\"ט שערי טומאה ר\"ל<sup data-n=\"42\">42</sup>.\nווי אזוי קען בטל ווערן מדידת הטבע דא למטה, דורך דעם וואס עס ווערן בטל די מדידות והגבלות (מצרים — גבולים<sup data-n=\"43\">43</sup> פון גאנץ סדר השתלשלות 44, וואס דאס ווערט דורך דעם וואס עס איז מאיר אן אור וואס איז לגמרי העכער פון מדידה והגבלה, פון כל סדר השתלשלות 45.\nוויבאלד אז אלע ענינים מוזן קומען דורך תורה 46, דארפן זיי פריער זיין בתורה — מוז אויך דער ענין (המשכת האור שלמעלה מהשתלשלות בכדי צו מבטל זיין די מדידות פון סדר השתל־שלות) פריער זיין אין תורה: אין תורה ווערט נמשך פון א העכערן ארט ווי תורה איז מצ\"ע, כביכול, העכער פון די מדידות פון תורה.\nדעריבער האט דער אויבערשטער געמאכט אז משה רבינו זאל איבער־געבן דעם ציווי פון „וכל ערל לא יאכל בו\" ניט קודם חשיכה, נאר דוקא בלילה, בכדי עס זאל ארויסקומען מילת בנ\"י דוקא בלילה (ניט ווי עס קומט דערנאך — נאך מתן תורה — אראפ אין מדידה דתורה) 46* — ווייל דער גילוי אור וואס",[["32","32","ח\"ב לח, א. וראה בהנסמן בנצוצי זהר שם."],["33","33","תהלים קלט, יב."],["34","34","שו\"ת תורת חסד שם."],["35","35","נסמן לעיל הערה 20."],["36","36","בא יב, ח. יח. תוספתא שבהערה הנ\"ל."],["37","37","אבל ראה שמחה\"ר שם (פיסקא אר\"א ב\"ע כו') דלילה כיום יאיר היינו „כחשכה כאורה שקולים .. ונמצאת לילה זו שתים עלתה לה כו'\"."],["38","38","הטעם לציווי באופן זה י\"ל כי מצות אלו אינן תלויין בגדר דלילה, כ\"א בהזמן דהתחלת (ליל) טו ניסן, זמן החפזון לכאו\"א כדאית לי' (ברכות ט, א), ולכן אע\"פ שאז הי' „לילה כיום יאיר\" בכ\"ז הי' הזמן דחפזון."],["39","39","ובפרט שענין החפזון ה\"ה תלוי בלילה דוקא, וכמחז\"ל שמו\"ר ס\"פ בא (ס\"פ יח. פי\"ט, ו). וראה אוה\"ת בא ד\"ה וככה. וככה תרל\"ז בתחלתו. ובכ\"מ."],["40","40","ראה רש\"י בא יב, יא. מכילתא (ובפרש\"י) שם, יג. וראה לקו\"ת צו יג, סע\"ד. תו\"ח שמות קצא, א ואילך."],["41","41","מכילתא יתרו יח, יא. פרש\"י שם, ט."],["42","42","ז\"ח ר\"פ יתרו."],["43","43","תו\"א עא, ג. ועוד."],["44","44","ראה תו\"א שם דכל סדר ההשתלשלות נק' בשם מצרים."],["45","45","ראה לקו\"ת שם. ובכ\"מ."],["46","46","ראה ב\"ר בתחילתה. 46*) ולהעיר מהמובא לעיל (הערה 16) דאברהם נימול ביוהכ\"פ (או ביו\"ט דפסח) ע\"פ הדבור — דלא"]]],[1300171142,"האט מאיר געווען באותו לילה, איז געווען באופן וואס איז העכער פון גאנץ סדר ההשתלשלות, ביז — העכער פון די מדידה פון תורה כביכול; און דעריי־בער זיינען דורך דעם נתבטל געווארן די מדידות פון סדר השתלשלות — ס'איז געווען א המשכת האור בדרך דילוג: ס'איז געווען המשכת אלקות אין ארץ מצרים ווי זי איז מלאה גילולים 47 (וואס מצד סדר השתל' האט עס קיין ארט ניט), און דורך דעם איז נתבטל גע־וואָרן די מדידת הטבע אויך דא למטה, ס'איז געווארן פסח, דילוג — און ס'איז געווען יציאת מצרים, היפך הטבע.\nז. פונקט ווי ס'האט געמוזט זיין דער ענין ה„דילוג\" אין תורה בכדי עס זאל קענען זיין יצי\"מ, אזוי האט געדארפט זיין אויך ביי אידן אן עבודה פון „דילוג\", למעלה מהשתלשלות שבאדם.\nדערפאר איז די הכנה צו יצי\"מ געווען דם פסח און דם מילה 48, ווייל די צוויי מצות פסח און מילה זיינען עבודות שלמעלה מהגבלה 49: „פסח\" איז מלשון דילוג 50, און מילה איז ענינה „ברית עולם\" 51 מיט'ן אויבערשטן — אן אייביקער פארבונד און קיין שום הגבלות 52.\nדערמיט ווערט מען פארשטיין וואס מיר געפינען א חידוש ביי פסח און מילה וואס איז ניטא ביי קיין אנדערע מצות עשה — בא זיי איז א חיוב כרת 53: ווען עס רעדט זיך וועגן ענינים שלמעלה מהשתלשלות ודרגות, קען דארט ניט זיין קיין צווישען דרגות. ס'איז איינס פון די ביידע: אדער ער ווערט פארבונדן מיטן אויבערשטן מיט א ברית עולם, למעלה משינויי הזמן — בלי גבול; און אויב ניט — איז „ונכרתה גו'\", ער האט ר\"ל אינגאנצן ניט קיין שייכות צו אלקות.\n[עד\"ז ווי ביי כללות יצי\"מ כנ\"ל: עס מוז אראפגענומען ווערן אלע מדידות, אויך די מדידות פון תורה כביכול; אויב ניט — בלייבט מען שטעקן אין מצרים, ארץ מלאה גילולים].\nאון דערפאר האט דער גילוי פון „ולילה כיום יאיר\" ביי יצי\"מ געדארפט האבן א שייכות עיקרית מיט מצות מילה, ווייל דער ענין פון „ולילה כיום יאיר\" אין דעם גילוי אור שלמעלה, איז פארבונדן מיט „ולילה כיום יאיר\" אין עבודה פון אידן, וואס דאס איז די עבודה פון דם מילה 54.",[["","","כפי המדידה ע\"פ תורה (לאחר מ\"ת). ואף את\"ל (כבהערה הנ\"ל) דמכיון שכן הי' הציווי ה\"ז כמילה בזמנה — הרי זה גופא הי' רק מצד הציווי, וכמו בנדו\"ד שנצטוו באכילת פסח וכו' בלילה כיום יאיר."],["47","47","ראה מכילתא בא יב, א. תנחומא שם ה. שמו\"ר פ\"יב, ה. פרש\"י וארא ט, כט."],["48","48","ראה תיב\"ע בא (יב, יג). פדר\"א פכ\"ט וזח\"ב לה, ב דגם מדם מילה נתנו לאות על הבתים. וראה פדר\"א שם, מכילתא (והובא ברש\"י) בא שם, ו (וראה גם שמו\"ר כאן) דבזכות קיום ב' מצות אלו נגאלו ממצרים."],["49","49","ראה גם לקו\"ש ח\"ג ע' 867 ואילך."],["50","50","נסמן לעיל הערה 40."],["51","51","לך יז, יג."],["52","52","ראה ג\"כ לקו\"ת פרשתנו ד\"ה למנצח על השמינית."],["53","53","משנה כריתות בתחילתה. וראה אוה\"ת יתרו (כרך ד' ע' בתרצ\"ח) בביאור למ\"ש „בהשמטות זח\"א כר מ\"א פסח ומילה כו' ואית בהו כרת\". לקו\"ש ח\"ג ע' 834 הערה 23."],["54","54","להעיר מאוה\"ת שם (מזהר שם) דמילה (ופסח) הוא „ע\"ד התכללות מדת יום בלילה\". ושם (ע' ב'תרח\"צ) דע\"ז „נמשך מבחי' ישת חושך סתרו כו'\", עיי\"ש. ומה שהקרבת הפסח היתה ביום י\"ד ולא בליל ט\"ו — י\"ל, דאי\"ז משום שההקרבה זו היתה צ\"ל ביום ולא בלילה, כ\"א מפני שצ\"ל בי\"ד ניסן (ולא בט\"ו) — ראה בארוכה לקו\"ש חט\"ז ע' 105-6."]]],[1300171143,"ח. עפ\"י כהנ\"ל איז אויך מובן דער חילוק אין מצות מילה צווישן פאר מ\"ת און נאך מ\"ת:\nדער אמת'ער ענין פון דילוג אין מצות מילה איז דוקא אין דער מצות מילה פון פאר מ\"ת 54*. דעמאלט האט זי אויפגעטאן א „דילוג\" נאך מער ווי מן הקצה אל הקצה: זי האט ארויסגענומען די אידן פון רשות הקליפה און זיי מכניס געווען לרשות הקדושה. און אין דעם גופא פון מ\"ט שערי טומאה — צום נגלה עליהם הקב\"ה בכבודו ובעצמו 55 וואס דאס איז דאך באין ערוך לגמרי, זיינען דעריבער דא ניטא קיין שום מדידות, ובמילא — ניטא קיין חילוק צווישן יום ולילה 56.\nמשא\"כ נאך מ\"ת זיינען אידן שוין געווארן אין אן אופן דציור וסדר פון קדושה 57, און דער „ברית עולם\" דורך מצות מילה איז אויך אין סדר דקדושה; ובמילא איז דאס געווארן אן עבודה שבמדידה והגבלה, און עס זיינען פאראן אין דעם חילוקי יום ולילה וכו'.\nט. די הוראה דערפון בעבודה בפועל:\nדי עבודה פון יצי\"מ איז דאך פאראן און מוז זיין בכל דור ודור וכל יום ויום 58; ווארום יעדער מדרי' איז בחי' מצרים (מל' מצרים וגבולים<sup data-n=\"59\">59</sup> לגבי א מדרי' שלמעלה ממנה 60. איז בשעת מ'דארף ארויסגיין פון מצרים, דארף מען וויסן אז ס'זיינען ניט פאראן דערביי קיין שום מדידות והגבלות, אפילו ניט די מדידות פון תורה כביכול\n— ע\"ד ווי ס'איז מבואר אין תניא 61, אז בשעת עס רעדט זיך וועגן עובר זיין ח\"ו (בחי' גלות מצרים) אויפן רצון העליון, איז דאן ניטא קיין חילוק צווישן קלה שבקלות און חמורה שבחמורות 62, ווארום מצד רצון העליון — וואס איז העכער פון טעם ודעת (אפילו פון טעם ודעת שלמעלה) — זיינען אלע מצות גלייך. און דאס רופט ארויס אפילו ביי א קל שבקלים, אז אויך ער איז זיך מוסר נפש, אפילו אויף א דקדוק קל של דברי סופרים, און אן קיינע חשבונות —\nומכש\"כ אז ס'זיינען ניטא די מדידות פון יום ולילה: אים איז קיין נפק\"מ ניט צי ס'איז ביי אים ליכטיק אדער ח\"ו פינסטער; אים רירט ניט אן וואס ער איז פארמאטערט, וואס ער האט פאר־שידענע רצונות ותאוות וכו'; ער נעמט ארויס מיט א גבורה (למעלה מטו\"ד) זיין חרב און איז זיך גלייך מל, פארבינדט זיך מיט'ן אויבערשטן דורך קיום רצונו בבחי' יסוד והתקשרות וברית עולם מיט קוב\"ה.\n(משיחת אחש\"פ תשכ\"ה)",[["","","54*) ויש לקשר זה עם הענין ד„ואשביעך\" בנקיטת חפץ הי' אפשרי רק ע\"י „שים נא ידך תחת ירכי\" — „חפץ\" היחידי אז (ח\"ש כד, ב. תוס' שבועות לח, סע\"ב)."],["55","55","מלכות דאין סוף ועצמות דא\"ס שלפני הצמצום (סה\"מ אתתי\"ר ע' עה)."],["56","56","וי\"ל הטעם שמילה בזמנה הוא רק ביום גם קודם מ\"ת — כי לפני מ\"ת הי' צ\"ל ע\"י מילה פעולה בעולם — לבטל יראת הגוים והליצנים והאויבים וכו', וכמש\"נ: בעצם היום הזה, ולא בלילה (לך יז, כג. פרש\"י שם). ועוד: מילה בזמנה מורה על עבודה הקשורה בזמן (ע\"פ) סדר (וטו\"ד) וענינה ה\"ה גילוי מ(הערלה ו)הסתר ולכן הוא רק ביום, משא\"כ מילה שלא בזמנה היא עבודה שלא ע\"פ סדר, ע\"ד בחי' דילוג."],["57","57","ראה לקו\"ת ר\"פ ראה. ובכ\"מ. וראה בארוכה לקו\"ש חי\"א ע' 5 ואילך."],["58","58","תניא פמ\"ז. ובכ\"מ."],["59","59","נסמן לעיל הערה 43."],["60","60","ראה ג\"כ לקו\"ש ח\"ב ע' 348 ואילך."],["61","61","פכ\"ד-כה."],["62","62","כמרז\"ל בתנחומא עקב ב. דב\"ר פ\"ז, ב. יל\"ש יתרו רמז חצר. ועוד."]]],[1300171144,"<h3>תזריע ב*</h3>\nא. בנוגע אַ יולדת וואָס איז מחויב ברענגען „כבש גו' לעולה\" און „בן יונה או תור לחטאת . . ואם לא תמצא ידה די שה ולקחה שתי תורים או שני בני יונה אחד לעולה ואחד לחטאת\"1, זאָגט די משנה בסוף מס' קנים:\n„האשה שאמרה הרי עלי קן כשאלד זכר (זי האָט מנדר געווען צו ברענגען אַ קרבן נוסף אויף דעם וואָס די תורה האָט מחייב געווען צו ברענגען „אחד לעולה ואחד לחטאת\"), ילדה זכר מביאה שתי קנים אחת לנדרה ואחת לחובתה, נתנתן לכהן הכהן צריך לעשות ג' פרידים מלמעלן ואחת מלמטן (וואָרום די צוויי עופות פון איר נדר זיינען ביידע עולות און אויך איין עוף פונעם קן לחובתה איז אַן עולה (וכנ״ל: „אחד לעולה ואחת לחטאת\") — און דער דין איז אַז „חטאת העוף נעשית למטה און עולת העוף נעשית למעלה\", ווי די משנה זאָגט בתחלת המס'). דערנאָך איז די משנה מוסיף ומפרט די דינים ווען עס ווערן טעויות וספיקות וואָס די יולדת האָט גענומען אויף זיך און צי דער כהן האָט זיי מקריב געווען כהלכה, און איז מסיים מיט דעם גרעסטן צאל ספיקות — אַז זי האָט גענומען אויף זיך בריינגען משני מינים און מען ווייס ניט ווי דער כהן האָט זיי מקריב געווען איז דאמאלס „צריכה להביא עוד ארבעה פרידים לנדרה ושתים לחובתה וחטאת אחת. בן עזאי אומר שתי חטאות\".\nווייטער איז די משנה ממשיך „אמר רבי יהושע זהו שאמרו כשהוא חי קולו אחד וכשהוא מת קולו שבעה. כיצד קולו שבעה ב' קרניו לשתי חצוצרות שתי שוקין לשני חלילין עורו לתוף מעיו לנבלים בני מעיו לכינורות וי״א אף צמרו לתכלת\".\nזיינען מפרשים2 מבאר דעם פשט אין דברי ר״י „זהו שאמרו כשהוא חי כו'\": כשם ווי באַ אַ כבש3, אַז דוקא דורך דעם וואָס אין אים איז פארגעקומען אַ קלקול („מת\") ווערט נתרבה קולו („נתרבו בו המצות\"<sup data-n=\"4\">4</sup> — שבעה, אדער שמונה לויט די י״א — עד״ז איז בנדון הקנים ביי אַ יולדת, אַז מתחלה האָט זי בלויז גע־דארפט ברענגען „קן לנדרה וקן לחוב־תה\"5, און דוקא צוליב די טעויות וספיקות6, „אינה יודעת מה קבעה ואין",[["","","*) וסיום מס' קנים (וסדר קדשים)."],["1","1","פרשתנו (תזריע) יב, ו. ח."],["2","2","ראה פיה״מ להרמב״ם, רע״ב, פי' הרז״ה. וראה הערה 6."],["3","3","כ״ה בפיה״מ ורע״ב שם. אבל בתוד״ה אמר שם, פרש״י זבחים (סח, א ד״ה א״ר) — באיל. ועד״ז הוא בפי' הראב״ד ורז״ה קנים שם. ולהעיר מחילוק הפי' בתוס' (ועד״ז בהמפרש ופי' הרא״ש), ראב״ד ורז״ה שם אם המדובר בשופר של ר״ה או חצוצרת לשיר על הקרבן, או בחצוצרת המלכים (וראה ר״ה טז, א)."],["4","4","פיה״מ כאן."],["5","5","כ״ה ברע״ב כאן. ובפיה״מ: והיתה עשירה וכו' לא היתה חייבת אלא עוף א' לחטאת והיא מצוה אחת. ובפי' הרז״ה: קרבן יולדת שפתח בה הכתוב תחלה אינו אלא פרידה אחת מן הקן כו'."],["6","6","בפרש״י זבחים שם: וה״נ כשנדרה תחלה ואינה יודעת מה פירשה לא צריכה אלא ד' פרידין וב' לחובתה אחת לעולה ואחת לחטאת ועכשיו שהביאה כבר ד' פרידין צריכה להביא ד' לנדרה וד' לחובתה. ועד״ז הוא בתוס' ופי' הראב״ד קנים שם (וראה פי' הרא״ש שם), והיינו שהמדובר רק בנוגע לבבא האחרונה, א) ואינו מודגש שהירידה היא מקן א' או ב' קנים, לד' כו'. ב) אין מפורש שהשמונה באו בסיבת הטעיות והספק. ומשמע שמפרש „שעכשיו שהביאה כבר ד' פרידין\", ונפסלו (מספק) הרי״ז"]]],[1300171145,"יודע הכהן מה הקריב\"7, דארף זי ברענ־גען זיבן אדער אַכט (לדעת בן עזאי) קרבנות.\nב. לפירוש הנ״ל אָבער דארף מען פארשטיין:\nא) אויף דעם ענין, אַז מלכתחילה איז געווען מער ניט ווי איין זאַך און דוקא דורך קלקול וכיו״ב ווערן זיבן זאַכן, קען מען געבן כו״כ דוגמאות, ווי למשל אַ דוגמא פשוטה פון נכסים, וואָס גייען איבער בירושה פון דעם פאטער צו זיבן אדער אַכט יורשים: כל זמן דער מוריש לעבט געהערן די נכסים צו איין מענטש: וכשהוא מת און די קינדער ירש'נען די נכסים, געהערן די נכסים צו זיבן אדער אַכט מענטשן ובמילא קומט אין דעם צו ריבוי, און אויך אין מצות („נתרבו בו המצות\") אַ באזונדערער חיוב מצות פאה בכורים וכו' אויף יעדער חלק השדה וואָס איז פאנאנדערגעטיילט גע־וואָרן צו יעדן באזונדער, בדוגמא ווי דער ריבוי קרבנות באַ דער יולדת.\nפון דעם וואָס ר״י ברענגט דוקא די דוגמא, איז מובן, אַז אין דער דוגמא איז דאָ אַ תוכן וואָס איז מתאים ביותר לנדו״ד מער ווי אנדערע דוגמאות8.\nוצריך להבין וואָס איז דער תוכן.\n[ואין לומר, אַז די משנה ברענגט ניט די דוגמא פון ירושה ווייל ביי קנים איז ניטאָ קיין שינוי אין די קרבנות וואָס זי האָט פריער געדארפט ברענגען, זי איז נאָר מוסיף עליהם, משא״כ באַ ירושה איז דער מוריש בטל — וואָרום אויך באַ כבש איז בטל דער קול פון דעם כבש בעת ער האָט געלעבט].\nב) ווען מ'ברענגט אַ דוגמא און אַ משל איז דאָס בכדי עס זאָל צוקומען אין הבנת הדבר — ובפרט בנדו״ד, ווי דער רמב״ם זאָגט אַז „מפני שהי' הענין זר\" דערפאָר ברענגט ר״י דעם משל „שהוא דומה למה שאמר כבש\"9 — איז ניט מובן: וואָס פאר אַ תוס' הבנה קומט צו אין דעם ענין דורך דעם וואָס מ'זאָגט אַז „זהו שאמרו חי קולו אחד וכו'\"?\nג) פון פשטות לשון ר״י „זהו שאמרו\", און ניט „כמו שאמרו\", „למה הדבר דומה\", וכיו״ב, איז משמע אַז ער איז דערמיט ניט (נאָר) מבאר דעם ענין פון קנים שבמשנה, נאָר (אויך — ו)אדרבה — מיט דעם דין אין קנים ווערט מוסבר „מה שאמרו כשהוא חי קולו אחד כו'\". ולכאורה דער ענין „כשהוא חי קולו אחד וכשהוא מת קולו שבעה\" איז אַן איינפאכער ענין טבעי און מ'דארף אויף דעם קיין הסברה ניט האָבן.\nאויך: אפילו ווען דער מאמר „כשהוא חי כו'\" וואָלט געפאדערט הסברה — איז ניט ענינה פון אַ משנה (אדער — תורה בכלל) צו זאָגן אַ ביאור אויף אַ",[["","","דוגמת כשהוא מת. (אבל ראה תוי״ט קנים שם ד״ה זה הוא שאמרו, שכתב על דברי הרע״ב „וכ״כ התוס' דהכא וכן בפרש״י פ״ז דזבחים\"). ולפי״ז אין מתיישב כ״כ בלשון ר״י „כשהוא חי קולו אחד וכשהוא מת קולו שבעה\". וראה פי' לקח טוב (יעיר קנו) לקנים שם שמקשה גם לפי פי' הרע״ב. ולהעיר מפיה״מ כאן, שמתחיל (כנ״ל בהערה שלפנ״ז) „עוף א' לחטאת היא מצוה אחת\" וממשיך „אבל הואיל ונולד הספק מביאה שבעה\", דרובם עולות."],["7","7","לשון הרע״ב שם."],["8","8","כי דוחק לומר דנקט דוגמא זו דוקא, כי רק בזה מצינו שמא' נעשה ז' או ח' קולות, מקביל למספר הקרבנות, משא״כ בירושה (שאין בזה מספר קבוע, כ״א תלוי במספר היורשים שיש לו). ולהעיר מהלשון בפיה״מ „נתרבו בו המצות\" ואינו מדייק לפרט מספרם."],["9","9","ובתרגום קאפה: אמר רבי יהושע על דרך התימה דבר זה כעין אמרם."]]],[1300171146,"<h3>מאמר העולם!10</h3>\nמוז מען זאָגן, אַז מיט „כשהוא חי וכו'\" מיינט ר״י (ניט סתם זאָגן אַ משל פון אַ מאמר העולם, נאָר) אַן ענין וואָס איז נוגע לדין והלכה: און דאָס מיינט די משנה „זהו שאמרו כו'\", אַז דער ביאור אין דער הלכה וואָס קומט אַרויס פון דעם מאמר „כשהוא חי כו'\" נעמט מען אַרויס פון דעם דין אין אונזער משנה בנוגע די קרבנות וואָס די יולדת ברענגט.\nג. ווייטער איז די משנה11 ממשיך: ר״ש בן עקשיא אומר זקני עם הארץ כל זמן שהם מזקינים דעתן מיטרפת עליהם שנאמר12 מסיר שפה לנאמנים וטעם זקנים יקח אבל זקני תורה אינו כן אלא כל זמן שהם מזקינים דעתם מתישבת עליהם שנאמר13 בישישים חכמה ואורך ימים תבונה\".\nאון די שייכות להקודמו, „דכשם שהוא מת קולו שבעה, כך זקני תורה כל זמן שמזקינים ובאים לידי תשות כח הן מוסיפים חכמה\"14.\nמ'דארף אבער פארשטיין:\nא) וואָס איז דאָ בכלל נוגע דער ענין פון „זקני ע״ה כל זמן שמזקינים כו'\". ב) מאי קמ״ל — עס איז די סברא פשוטה וראשונה אַז תשות כח בריינגט תשות חכמה. ג) ויתרה מזה — זי איז היפך כוונת המדובר15 במשנה בסמיכות לזה (צו מדגיש זיין אַז דוקא דורך זקנה, ווען „באים לידי תשות כח\", קומט צו אין חכמה). ד) עכ״פ האָט ער דאָס גע־דארפט זאָגן לאחרי פון דעם חידוש אין דער בבא פון זקני תורה (אַז אע״פ וואָס באַ זיי איז נתוסף ביישוב דעתם — איז הפכו באַ זקני ע״ה).\nד. די נקודת הביאור בכל זה:\nפון דעם דין פון קנים קומט אַרויס אַ חידוש ענין: בעצם ליגט אויף אַ יולדת אַ חיוב קן אחד, „אחד לעולה ואחד לחטאת\", ובנדו״ד ליגט אויף איר אויך דער חיוב נדרה, שתי פרידות לעולה. און מצד די טעות'ן און ספיקות וואָס ווערן געשאפן באַ דער אשה און באַ דעם כהן קומט אַרויס אַ חיוב פון כו״כ קרבנות ביז צו שבעה, אדער שמונה.\nמען איז מחייב ברענגען קרבנות נוספים צו מקריב זיין בביהמ״ק, בשעת עס קען זיין אַז זי איז אין זיי ניט מחוייב, און די קרבנות וואָס אין זיי איז זי יע מחויב האָט מען שוין מקריב געווען16 און זי איז שוין נתכפר געוואָרן און יוצא געווען17 כל החיוב שלה (והשאר —",[["10","10","להעיר מתוס' קנים שם: באיל קמשתעי קרא. וצ״ע."],["11","11","ראה המפרש. ובפי' הרא״ש."],["12","12","איוב יב, כ."],["13","13","שם, יב."],["14","14","לשון הרע״ב קנים שם. ועד״ז הוא בפיה״מ שם. המפרש ופי' הרא״ש שם."],["15","15","משא״כ בשבת (קנב, א) שמובן זה שמביא הסוגים, כי כל הסוגיא שם הוא ע״ד זקנה בכלל והשינויים (לגריעותא) שנעשים באדם כשבא לידי זקנה (וגם מביא שם לפנ״ז דברי זקני ת״ח ע״ד ימי זקנה שלהם וכן דזקני ע״ה). ומקדים ת״ח כל זמן שמזקינים לע״ה כ״ז שמזקינים כו' כסדר הכתובים באיוב „בישישים חכמה\" (שם, יב) „מסיר שפה לנאמנים\" (שם, כ) — ראה עיון יעקב לע״י קנים שם. השינויים בין לשון המשנה בקנים להלשון במס' שבת — נתבארו בארוכה בהתוועדות."],["16","16","בנוגע לעולה כתב רש״י בכיו״ב בכ״מ (פסחים כח, רע״א ד״ה חטאת העוף. כריתות ז, ב ד״ה מביאה קרבן. כב, סע״ב ד״ה חטאת. ערכין ח, ב ד״ה ואינו נאכל) דעולה באה על תנאי אם ילדתי הרי היא לחובתי ואם לאו הרי היא נדבה. וראה גם פירושו בנדו״ד זבחים סז, סע״ב. אבל ברמב״ם בפיה״מ קנים ובהל' פסולי המוקדשין פ״י (ועוד) לא הזכיר דבאו על תנאי."],["17","17","ולהעיר דיש בזה כמה ספיקות כמבואר בארוכה במפרשי המשנה."]]],[1300171147,"חולין בעזרה<sup data-n=\"18\">18</sup>?\nבשלמא חטאת העוף וואָס קומט אויף אַ ספק, ביי אַ ספק יולדת וכיו״ב, י״ל, כפשטות הלימוד אין גמרא19 אַז די תורה20 האָט מחדש געווען, אַז אפילו אויף אַ ספק אויב נטמאה21 איז זי אויך חייב אַ קרבן לכפרה22 (וואָס איז איר מתיר לאכול בקדשים<sup data-n=\"23\">23</sup>, בדוגמא ווי אַן אשם תלוי24, וואָס די תורה האָט מחייב געווען ברענגען בשעת ס'איז אַ ספק אם חטא, „וזהו הנקרא אשם תלוי שהוא מכפר על הספק ותולה לו עד שיודע לו בודאי שחטא בשגגה25 כו'\".\nאָבער בנדו״ד26 איז דאָך דער חיוב מתחלה אַ וודאות'דיקער, און דער ספק קומט צו דערנאָך ועל״י האשה והכהן — צי זי האָט משלים געווען איר הוספה אויף דעם חיוב ונתכפר לה27.\nאויך — וואָס פאר אַ גדר האָבן די זיבן אדער אַכט קרבנות, בשעת די סיבה פון זייער הקרבה איז אַ ספק של האשה או הכהן.\nאויף דעם זאָגט ר״י28 „זהו שאמרו כשהוא חי קולו אחד וכשהוא מת קולו שבעה\" ולכאורה איז דאָס תרתי דסתרי: די שבעה קולות זיינען „שתי קרניו שתי חצוצרות כו'\", וואָס זיי זיינען קולות פון קרניים, שוקים כו' וואָס האָבן ניט קיין שייכות צום „קולו\" פון כבש — ואעפ״כ „אמרו כשהוא מת קולו שבעה\",\nע״י מיתת הכבש ווערט בטל דער „קולו אחד\" און ס'ווערן נייע קולות בקרניים כו', אָבער אמרו אַז זיי אלע זיינען „קולו\" פון דעם כבש.\nדערמיט איז מבואר דער גדר פון די קרבנות (אַז חאָטש די סיבה פון די קרבנות זיינען ספיקות וואָס זיינען געשאפן געוואָרן לאחרי אירע (ערשטע) קרבנות חובה, זיינען אויך די קרבנות (בדוגמת) „קולו\"), זיי האָבן אויף זיך אַ גדר חובה29 וכו', פונקט30 ווי די ערשטע",[["18","18","ראה רמב״ם הל' מחוסרי כפרה פ״א ה״ז (הל' שגגות פי״א ה״ב). וראה פרש״י שבהערה 16. וראה (ובהבא לקמן) אנציקלופדי' תלמודית ערך חטאת העוף הבא על הספק, וש״נ."],["19","19","נזיר כט, א."],["20","20","שלמדוהו מהפסוק בסוף פרשתנו (מצורע): והזב את זובו לזכר ולנקבה גו'."],["21","21","ראה פי' (רש״י) נזיר שם ד״ה מנין. ד״ה מה זכר. תוד״ה וסבר שם. פי' הרא״ש ומאירי שם."],["22","22","לפנינו בגמ': מנין לחטאת העוף שהיא באה על הספק שאינה נאכלת. וראה לשון רש״י בנזיר שם. ובמאירי. ובפי' הרא״ש שם „וצריך לומר דסיפא דמילתא נקט וכולי אתי' מהך קרא\". וראה גם פרש״י פסחים וכריתות ז, ב (שבהערה 16), תמורה (לד, רע״א) ד״ה חטאת דהלימוד הוא (גם) על עצם הדין דבאה על הספק."],["23","23","ראה רמב״ם הל' שגגות שם."],["24","24","ראה תוד״ה אימר זבחים שם: דאתא קרא למימר להביא על הספק כמו בבהמה אשם תלוי. ולתו' א' לפנ״ז בתוס' שם קאי גם לרבי יהושע (דסתם קנים ר' יהושע, עיי״ש בגמ')."],["25","25","רמב״ם הל' שגגות רפ״ח."],["26","26","אבל להעיר מפי' הראב״ד בסיום מס' קנים: כלל זה למסכת קנין חטאת העוף באה על ספק לידה ועל ספק כפרה ונפקא לן מקרא במס' נזיר. ואולי קאי בעיקר על ענין הא'."],["27","27","שבחטאת בהמה כשהספק הוא בכפרה אינו מביא אשם תלוי (תוספתא כריתות פ״ב, ז. הוריות ד, א. ובירושלמי פסחים פ״ט סה״ב: ספק כפרה כיפר. וראה אנציקלופדי' שם, וש״נ)."],["28","28","ראה הערה הבאה."],["29","29","להעיר דהסוגיא בזבחים שם (סז, א ואילך) הוא בדעת ר' יהושע „עולת העוף שעשאה למטה כמעשה חטאת לשם חטאת כיון שמלק בה סימן אחד נמשכה ונעשית חטאת העוף\", וקס״ד ואפילו למיפק לי' לשם חובת חטאת קאמר\" (לשון רש״י בסוף העמוד שם). ולפי״ז י״ל דזה שהביא הגמ' שם משנתנו דקנים הוא לא רק להוכיח ד„מדאיירי רבי יהושע בהא ש״מ קינין דר' יהושע אמרה\" (פרש״י שם סח, א סד״ה א״ר יהושע), והקושיא היא מהמשנה דחטאת ועולה וסתומה ומפורשת כו', כ״א שגם תוכן הסברא נוגע לגוף הענין. וראה מסקנת הגמ' שם (סח, א). ובתוד״ה אימר שם ובהערה הבאה."],["30","30","אף ש„כל החטאות האלו אינן נאכלות מפני שהם ספק\" (רמב״ם הל' פסולי המוקדשין ספ״י. ועד״ז בפיה״מ קנים שם). ובפרש״י זבחים שם ד״ה"]]],[1300171148,"קרבנות אירע31.\nה. אַז סיבת הקרבן איז נאָר מצד הספק, היינט ווי אַזוי ווערט דער קרבן אַ חיוב גלייך ווי איר קרבן חובה — גע־פינט מען כמה דוגמאות, אַז אַ מסובב באַקומט מער תוקף ווי זיין סיבה32. ומהם:\nא) באַ דיני סוכה, נסרים33 וואָס רחבן ארבעה און „הפכן על צדיהן שאין בהם ארבעה\"34 איז דער דין35 אַז אויך דע־מאלט איז דאָס פסול, „דכיון דיש שם פסול עליהן נעשו כשפודין של מתכת הפסולין לסכך בכל ענין שהופכן\"36. זעט מען37, אַז כאָטש די סיבה וטעם וואָס „יש שם פסול עליהן\" איז מצד „גזירת תקרה\"38, וואָס דאָס איז דוקא אויפן צד וואָס רחבן ארבעה, ווערט דאָס אָבער „כשפודין של מתכת\", אַ פסול עצמי, ובמילא זיינען זיי פסול אויך על הצד ווען עס איז ניטאַ גזירת תקרה.\nב) דברי החת״ס39 הידועים בנוגע יו״ט שני של חגה״ש, אַז ער איז חמור פון אנדערע יו״ט שני של גליות, ווייל ער איז באַ ניט מצד ספק ווי אנדערע יו״ט, נאָר ער האָט אין זיך אַ כח של ודאי: היות אַז ביי חגה״ש איז קיינמאָל ניט געווען אַ ספק ווי ביי פסח וסוכות (ווייל זיין קביעות איז יום חמישים לעומר<sup data-n=\"40\">40</sup>, און דאָס וואָס מ'מאַכט שבועות צוויי טעג איז בלויז „שלא לחלוק במוע־דות\"41.",[["","","בן עזאי „וחטאות הללו אינן נאכלות שהרי על הספק באו ואין מליקתן מליקה להתירן באכילה\". ואולי י״ל מדשינה רש״י בלשונו ולא כתב כבפירושו בשאר מקומות (פסחים תמורה וערכין שם. כריתות (כו, ב) — לענין ספק לידה וזיבה) שמא חולין הוא ומליקתה הוי נבילה, וכיו״ב, דזה שחטאות האלו אינן נאכלות (ונשרפות) הוא לימוד ודין בפ״ע בנוגע לאכילתה, דאינה מליקה להתירן באכילה (וע״ד פשטות לשון הגמ' בנזיר שם בסופו: אי מה זכר . . ונאכל אף נקבה כו' ונאכל כו'). כי לא רק חיובן ודאי אלא גם קדושתן. ולהעיר מתוד״ה מתקיף נזיר שם, ע״ב. ופי' הרא״ש שם. וראה אנציקלופדי' שם, וש״נ. ואכ״מ."],["31","31","ועפ״ז י״ל הקשר והשייכות לתחלת סדר קדשים (דנעוץ תחלתן בסופן*) „כל הזבחים שנזבחו שלא לשמן כשרים אלא שלא עלו לבעלים לשם חובה\" שהוא לא רק בהענין דגם בזה נתרבה מצוה ע״י קלקולו, כי נוסף על קרבן זה (דכשר הוא) „צריך להביא אחר לחובתו או לנדרו\" (פרש״י ריש מס' זבחים), כ״א גם בזה דקרבנות אלו דשחטו שלא לשמן (כשרים „לזרוק דמם להקטיר אימוריהם ולאכול את הנאכלין\" (פרש״י שם), „קמ״ל ד)בקדושתייהו קיימי ואסור לשנויי בהו\" (בגמ' שם ב, א). ושם ריש ע״ב „אלא אם כמה שנדרת כו' ואם לא נדבה יהא\". וראה פרש״י שם ד״ה ואם לאו."],["32","32","ולהעיר מלקח טוב (להר״י ענגל) כלל יז, אם מצינו טפל חמור מן העיקר. *) ספר יצירה פ״א מ״ז. וי״ל דמטעם זה המנהג בכל ישראל לקשר ב„הדרן\" סיום המס' (וסדר) לתחלתו (וע״ד „מתכיפין התחלה להשלמה\" — „רשות לחתן בראשית\"), שהוא לא בכדי לחדודי בעלמא (ובפרט שהזהירו על כיו״ב בתוקף המהר״ל והשל״ה וכו' — הובאו בקונט' עה״ח פל״א). כ״א שהסיום יש לו שייכות עם (נעוץ ב)התחלה. וכבר העירו באחרונים מברכות י', רע״א ובתוס' שם. וראה ספר ויהא ברכה."],["33","33","סוכה יד, ב. רמב״ם הל' סוכה פ״ה ה״ז. טושו״ע (ואדה״ז) או״ח סתרכ״ט סי״ח (ס״ל)."],["34","34","כ״ה ברמב״ם טושו״ע ואדה״ז שם. וברש״י שם ד״ה הפכן „שהוא פחות מג'\". וראה מהרש״א שם."],["35","35","כרב הונא (בגמ' שם) דקאי ר״נ כוותי' וגם רב חסדא ורבה בר רב הונא חזרו בהן (הגהת מיימוניות שם אות ז)."],["36","36","פרש״י שם ד״ה פסולה. ט״ז שם סקי״ט. שו״ע אדה״ז שם. ולשון הרמב״ם „שזה הנסר פסול בין כו'\"."],["37","37","ראה צפע״נ לרמב״ם הל' חמץ ומצה פ״ו ה״ב."],["38","38","לשון רש״י שם ד״ה כשרה."],["39","39","שו״ת או״ח סו״ס קמה. וראה לקו״ש ח״ד ע' 1030."],["40","40","ראה שו״ע אדה״ז או״ח ר״ס תצד."],["41","41","רמב״ם הל' קידוש החודש פ״ג הי״ב."]]],[1300171149,"קומט אויס, אַז סיבתו דיו״ט שני של חגה״ש איז יו״ט שני של פסח וסוכות — „שלא לחלוק במועדות\" — נאָר אַ ספק, עס ווערט אָבער אין יו״ט שני של שבועות אַ תוקף וכח של ודאי, מער ווי אין פסח וסוכות.\nוא״ו. עפ״י הנ״ל (סעיף ד) י״ל אויך לאידך גיסא אַז דער דין פון קנים גיט אַ ביאור אין „כשהוא חי קולו אחד וכשהוא מת קולו שבעה\", כפשטות לשון ר״י „זהו שאמרו\" — ס'איז „בא ללמד ונמצא למד\": דאָס איז נוגע און מבאר גדרים ודינים וואָס זיינען שייך צו כבש „כשהוא חי\" און — וואָס בייט זיך כשהוא מת.\nא' מהם — אַ כבש הנעבד לע״ז, וואָס דער דין42 איז אַז ער איז פסול למזבח43.\nאין גמרא44 געפינט מען די שאלה צי „יש שינוי לנעבד או אין שינוי לנעבד\", און די גמרא45 זאָגט אַז דאָס איז די איבעיא „המשתחוה לבהמה צמרה מהו לתכלת . . קרני' מהו לחצוצרת שוקי' מהו לחלילין בני מעי' מהו לפארות\" (נימין של כינור<sup data-n=\"46\">46</sup>.\n— דאָס איז די נפק״מ אין הלכה פון דעם מאמר (כבש) „כשהוא חי קולו אחד וכשהוא מת קולו שבעה\": אע״פ אַז די חצוצרת וכו' וואָס מען מאכט (די קרניים וכו' פון) דעם כבש מת זיינען שוין אפגעטיילט פון דעם כבש און ס'איז געווען אין זיי אַ שינוי מעשה, און די שבעה קולות זיינען ניט קיין קולות פון אַ כבש אפילו ניט (פון שוקיו, עורו כו'),\nנאָר ס'איז אַ קול חצוצרות, חלילין, תוף כו'; זיבן אופני קול וואָס האָבן קיין שייכות ניט צום „קולו אחד\" פון דעם כבש חי — זאָגט מען אָבער אַז דאָס איז „קולו שבעה\": אפילו ווען זיי זיינען שבעה קולות בלייבט בתוקפה זייער שייכות (בנוגע דיני התורה — דער איסור לגבוה) צו דעם „קולו אחד\" פון דעם כבש חי און עס ווערט ניט קיין שינוי לגבי דעם דין נעבד (לגבי גבוה)47.\nאָבער אין דעם קען מען זאָגן צוויי אופנים:\nא) דאָס וואָס די „קרני' פסולין לחצוצרות ושוקי' לחלילין כו'\"48 איז בלויז — ווייבאלד אַז זיי נעמען זיך פון דעם כבש, בלייבט אויף זיי במילא דער איסור לגבוה, ס'איז אָבער אויף זיי ניט חל דער „שם ע״ז\"49 — נעבד (לגבי גבוה), וויבאלד אַז זיי זיינען געוואָרן אַ מציאות חדשה.\nב) דאָס וואָס די קרני' פסולין לחצוצ־רות כו' איז פונקט ווי דער כבש איז פסול למזבח50, ס'איז חל אויף זיי „שם",[["42","42","תמורה כח, א ואילך וש״נ. רמב״ם הל' איסורי מזבח פ״ג ה״ז."],["43","43","משא״כ להדיוט דבע״ח אינו נאסר (תמורה כט, א. רמב״ם רפ״ח מהל' ע״ז)."],["44","44","ע״ז מו, ב."],["45","45","שם מז, א. וראה פרש״י שם ד״ה תכלת דכהנים."],["46","46","פרש״י שם ד״ה לפארות."],["47","47","וכן פסק הרמב״ם הל' איסורם פ״ד ה״ז. ובמאירי ע״ז שם. אף שבגמ' נשאר בתיקו. וראה כס״מ שם."],["48","48","לשון הרמב״ם שם."],["49","49","ראה פרש״י ד״ה ומה שעליהן וד״ה ר' יוסי (שם מה, א). ובתוד״ה אלהיהם שם, אם מחובר מקרי ע״ז (אף שאינה נאסרת להדיוט). ובפרש״י חולין מ, א ד״ה דומיא „ובע״ח אע״ג דלא מיתסרי משום עבודת כוכבים כו' אלהות מקרי\". וראה פרש״י ד״ה נעבד (ע״ז מו, סע״א) ותוד״ה יש (שם, ריש ע״ב), דבע״ח עדיפא לאסור לגבוה ממחובר."],["50","50","ראה לשון הרמב״ם שם „המשתחוה לבהמה כשם שנפסלה למזבח כך צמר שלה פסול לבגדי כהונה וקרני' פסולין לחצוצרות כו' הכל פסול\" ומלשונו משמע שזה קמ״ל דכשם שהבהמה נפסלה למזבח מצד נעבד לגבוה, כך הוא בצמר לבגדי כהונה כו' וקרנות לחצוצרות שיש עליהם גדר האיסור דנעבד לגבוה. ולהעיר מצפע״נ מהד״ת פו, ד „דגבי משתחוה לבהמה חל האיסור על הבהמה והם אסורים ממילא כו'\"."]]],[1300171150,"ע״ז\", נעבד (לגבוה), ובמילא זיינען זיי גופא מאוס לגבוה51.\nאון די נפק״מ לפועל י״ל: לויט דעם ערשטן אופן וויבאלד אַז זיי זיינען גע־וואָרן אַ מציאות חדשה, איז דער איסור נאָר מדרבנן52, לויט דעם צווייטן אופן איז דאָ אַן איסור דאורייתא53 נעבד (לגבוה)54.\nאון דאָס זאָגט ר״י „זהו שאמרו כשהוא חי כו'\": דער דין אין דער משנה לגבי די קרבנות וואָס די יולדת ברענגט, גיט אַ ביאור אין דעם ענין פון „כשהוא חי כו'\":\nפונקט ווי באַ קנים, אע״פ אַז די סיבת החיוב איז אַ ספק (אין די קנים וואָס זי איז אין זיי געווען מחוייב), זיינען אויך די קרבנות בדוגמת „קולו\", זיי האָבן אַ גדר חובה פונקט ווי די ערשטע קרבנות — עד״ז בנוגע דעם ענין פון כבש הנעבד:\nאע״פ אַז קרניו ושוקיו כו' זיינען נשתנה געווארן און געווארן אַ מציאות חדשה, און ס'איז לכאורה ניט שייך אויף זיי דער פסול למזבח, ווי ווען זיי זיינען מחובר צום כבש כשהוא חי, זאָגט מען אָבער „כשהוא מת קולו שבעה\", זיי באַ־קומען אַ פסול עצמי ומדאורייתא ווי קולו „נעשו כשפודין של ע״ז\", דער „שם ע״ז\" — נעבד (ובמילא — דער איסור לגבוה) ווערט דער שם פון די קרניים ושוקיו כו'55, דאָס וואָס זיי זיי־נען פסול לחצוצרות וחלילין כו' איז ווייל זיי גופא זיינען מאוס לגבוה.",[["51","51","לכאורה י״ל דוגמת ב' אופנים אלו גם באיסור ע״ז להדיוט כשנשתנה, אם „זה שכל שאתה מהייה ממנו הרי הוא כמוהו\" (פרש״י שם מו, סע״ב ד״ה או אינו. מאירי שם ד״ה משתחוה) הוא רק בדין, שאסור בהנאה כמוהו, או „הרי הוא כמוהו\" גם בגדר ותוכן האיסור דע״ז. ואכ״מ. ועפ״ז אולי י״ל מעין ב' אופנים אלו בכבש של ע״ז (שעשאה חליפין לע״ז וכיו״ב — ע״ז נד, ב. רמב״ם הל' ע״ז רפ״ח. טושו״ע יו״ד ס״ס קמה), אם זה שקרני' אסורין לחצוצרות שוקי' לחלילין הוא לפי שהם חלק מהכבש, ואסורין בהנאה כמו בשר הכבש לאחר מיתה, או שחל עליהם גדר ואיסור עצמי חצוצרות של ע״ז וחלילין של ע״ז [ומבאר ר״י „וזהו שאמרו כשהוא חי קולו אחד וכשהוא מת קולו שבעה\", דנעשו „חלילין של ע״ז\" כדלקמן בפנים לענין נעבד לגבוה]. ואולי י״ל דנפק״מ גם להלכה אם מותר להשתמש ולהנות מקולות אלו כי חל עליהם דין „חלילין של ע״ז אסור לספוד בהן\" (רמב״ם שם פ״ט הי״א. טושו״ע שם סקמ״ג ס״ד). שלפי אופן הא' דחליל זה אסור בהנאה מפני שהוא חלקו של הכבש ולא מפני שהוא חליל של ע״ז, יש לומר שאין איסור לתקוע להשתמש בחליל זה ופשיטא לשמוע קולו, כי אי״ז הנאה מחליל של ע״ז כ״א משוק ומעיו כו' של ע״ז, וא״כ אי״ז בגדר הנאה. ובפרט לתוד״ה שאני (פסחים כו, רע״א. ע״ז מח, ריש ע״ב ד״ה לא) שמשמע שגם בע״ז צ״ל דרך הנאה. וראה פרישה שם סק״ב. וצ״ע."],["52","52","ראה תוד״ה יש שינוי (שם מו, ב): דמדאורייתא ודאי פשיטא לי' דיש שינוי בנעבד כמו באתנן אלא מדרבנן הוא דקא מיבעי' לי' דמשום חומרא דעבודת כוכבים יש לאסור אע״ג דנשתנה."],["53","53","כדמשמע ברמב״ם שם."],["54","54","ולפי״ז נפק״מ בפשטות אם פסולה גם בדיעבד. וראה לח״מ לרמב״ם שם."],["55","55","עפ״ז י״ל דזה שרק „י״א אף צמרו לתכלת\", כי „צמרו לתכלת\" אינו שינוי גמור ומציאות חדשה ממש (כמו „קולו שבעה\") — ראה שו״ע אדה״ז או״ח סי' יא ס״ג (בצמר לציצית), ועייג״כ צפע״נ הל' תרומות (פ״א הכ״ד — כד, א) דשם צמר עליו אף כשהוא מחובר [ובפרט ע״פ פרש״י ודרד״ל (שבת עד, ב) עה״פ „טוו את העזים\" שמעל גבי העזים כו' (ראה בארוכה לקו״ש חט״ז ע' 449 ואילך)] — ולכן פליגי אם אמרינן גם ע״ז „קולו\" — איסור בפ״ע, כיון שהוא (במעיקרא) חלק של כבש שלא נשתנה בשינוי גמור. *) ואצ״ל דפליגי במחלוקת הראשונים רש״י ורמב״ן אם הפעמונים שבשולי המעיל היו בתוך הרמונים או בצדיהן (כבתוי״ט במשנה שם)."]]],[1300171151,"ז. אין דעם ענין פון „כשהוא חי קולו אחד וכשהוא מת קולו שבעה\" איז פאראן אַ פרט וואָס איז ניט דומה לגמרי צו די קנים פון יולדת:\nביי כבש איז מען מדגיש איין (ירידה ו)סיבה, דעם שינוי „כשהוא מת\" לגבי פריער „כשהוא חי\": משא״כ באַ קנים זאָגט די משנה עטלעכע פאלן: הכהן לא נמלך, אינה יודעת מה נתנה, אין יודע מה עשה כו' (און די פרטי החילוקים פון מין אחד לב' מינים כו'), וואָס מצד יעדער ספק וכו' קומט צו אַ קרבן כו', ביז מ'דארף מקריב זיין שבעה (שמונה) קרבנות.\nדעריבער ברענגט די משנה: „ר״ש בן עקשיא אומר זקני עם הארץ כל זמן שמזקינים דעתן מטרפת עליהן כו' זקני תורה כל זמן שמזקינים דעתן מתיישבת עליהם כו'\", וואָס אין דעם פרט הא' איז דאָ די נקודה הנ״ל.\nאון דערפאָר איז ער מקדים ומסמיך „זקני עם הארץ כל זמן שהם מזקינים דעתן מיטרפת כו'\":\nר״ש בן עקשיא זאָגט, אַז בזמן הזקנה איז (באַ ת״ח „באים לידי תשות כח\", „נחלשים ויפסיד גופם\", און פונדעסט־וועגן „תרבה חכמתם\"56, אָבער) ע״פ טבע ווערט חולשת שכלם57 ווי מ'זעט עס באַ זקני עם הארץ, ואעפ״כ איז באַ „זקני תורה . . דעתם מתיישבת עליהם\", ד.ה. אע״פ אַז די מעלה זייערע (און די סיבה ראשונה) איז וואָס זיי זיינען ת״ח, איז דאָך לכאורה גענוג אויפטו דאָס וואָס זייער שכל ווערט ניט פאר־קלענערט — ניט ווי באַ זקני עם הארץ (וועלכע ער האָט דערמאָנט פריער) וואָס דעתן מיטרפת58 — איז דער חידוש נאָך גרעסער, „תרבה חכמתם ויתחזק שכלם ויוסיפו שלימות\"56 נאָך מער פון דעם ווי זיי זיינען געווען ת״ח פריער.\nאון אין דעם פרט איז דאָס מער בדומה צום תוכן ענין קנים דלעיל, וואָרום עס איז (באַ זקני תורה) „כל זמן שהם מזקינים\" — דאָס איז ניט קיין מאליקע זאַך (סיבה וירידה), נאָר יעדער טאָג ווערט מער חלישות הגוף, דארף ע״פ טבע ווערן יעדן טאָג מער חלישות השכל (ווי באַ זקני עם הארץ, וואָס „כל זמן שמזקינים דעתן מיטרפת\") — ואדרבא יעדער טאָג איז אלץ מער „דעתן מתיישבת עליהן\".\n[וי״ל אַז דאָס איז נוגע להלכה לענין ישיבה בסנהדרין וואָס דארף זיין בעלי זקנה59]\nבדוגמא ווי באַ קנים כנ״ל, וואָס דורך יעדער ירידה וספק קומט צו נאָך און נאָך אין די קרבנות.\nח. דער ביאור בפנימיות הענינים און דער ביאור השייכות צו ר' יהושע דוקא (וואָס סתם קנים ר' יהושע<sup data-n=\"60\">60</sup>:\nסדר קדשים וייזט בכלל אויף אידן וואָס זיינען אַ „גוי קדוש\", אויך די (מסכת) „חולין\" זייערע איז אַ חלק פון (סדר) „קדשים\". און בסיום סדר קדשים",[["56","56","פיה״מ כאן."],["57","57","ראה אוה״ח ויחי מז, כט."],["58","58","להעיר מהמפרש לקנים ד״ה רבי שמעון. ובפי' הרא״ש שם."],["59","59","סנהדרין יז, סע״א. וש״נ. וברמב״ם הל' סנהדרין פ״ב ה״ו „בעלי שיבה\". וזה ד„אין מושיבין בסנהדרין זקן\" (סנהדרין לו, ב) — פי' הרמב״ם (שם ה״ג) „זקן מופלג בשנים\". וג״ז הוא רק בנוגע לדיני נפשות כו'. ולהעיר מהגירסא ופי' במשנה הוריות (פ״א, מ״ד) — פרש״י ורמב״ם שם. תוי״ט. ועוד. ואכ״מ."],["60","60","זבחים סז, ב ואילך."]]],[1300171152,"איז מען מבאר דעם ענין היולדת וואָס ווייזט אויף דער גאולה פון אידן, כידוע61 אַז דער גלות איז נמשל לעיבור און די גאולה — ללידה. ווי עס שטייט אין נבואת הגאולה „חלה גם ילדה ציון את בני'\"62.\nאיז ר' יהושע מסיים וחותם ומבאר ווי אַזוי האלט מען אויס בזמן הגלות און מען קומט צו צום ענין היולדת — גאולה, „זהו שאמרו כשהוא חי קולו אחד וכשהוא מת קולו שבעה\"63:\nעס שטייט אין מדרש64 „אדריאנוס אמר לרבי יהושע גדולה הכבש העומדת בין שבעים זאבים, אמר לי' גדול הוא הרועה שמצילה ושומרה ושוברן לפני'\".\nוואָס אויף דעם איז די שאלה, בשלמא ווען אידן זיינען אין אַ מצב פון כבש „חי\", וואָס בכלל איז דאָס ווען עס איז „חי\" אין די מדרי' פון די אבות אברהם יצחק ויעקב65, איז מובן וואָס „הרועה .. שומרה\", די אידן וואָס זיינען במדרי' כבש „חי\".\nבשעת אָבער „כשהוא מת\", די מדרי' פון די אבות איז ניט מאיר בגילוי, און עס ווערן נייע זיבן באזונדערע קולות, וואָס זיינען ניט אין דער דרגא פון „קולו אחד\" פון די אבות — מ'איז חלוקים זמ״ז אין פארשידענע סוגים — ווי איז באַ זיי דער „רועה .. שומרה\"?\nאויף דעם זאָגט ר״י „כשהוא מת קולו שבעה\", ווי ער זאָגט אין מדרש66 „גפן ממצרים תסיע67 .. מה הגפן היא חי' ונשענת על עצים מתים כך ישראל הם חיים וקיימים ונשענין על המתים אלו האבות\".\nד.ה. דאָס וואָס עס ווערט „קולו שבעה\", זיבן באזונדערע סוגים באַ אידן, איז דאָס ניט קיין באזונדערע מציאות (לגמרי), נאָר דאָס איז פארבונדן און (חי) נעמט זיך פון „קולו\", דער קול פון דעם כבש „חי\" — די אבות, וואָס זיי זיינען די אבות פון אלע און פון יעדער אידן61.\nאון פונקט ווי באַ די אבות איז געווען דער „קולו אחד\" — ל„אבינו שבשמים\", אַזוי איז דאָס אויך אין די אלע זיבן באזונדערע קולות, אַז ווי זיי שטייען אלס זיבן חלוקי מדרי' אין עבודת ה'68, איז באַ זיי דאָ אין זייער מציאות דער „קולו אחד\" לאבינו שבשמים,\nאין יעדערן פון די שבעה קולות איז דאָ דער „הקול קול יעקב\"69, וואָס פועלט אַז „אין ידי עשו שולטות\"70 — הרועה שומרה.\nאון דאָס איז ר״י מדגיש „כשהוא מת קולו שבעה\", אַז דאָס וואָס אלע שבעה חילוקי מדריגות הם חיים וקיימים, קומט",[["61","61","ראה תו״א ר״פ וארא."],["62","62","ישעי' סו, ח. — וכימי צאתך מארמ״צ — וכמש״נ ביחזקאל קאפ' טז."],["63","63","ומובן שהמדובר בכבש (עד כ״כ שרש״י אי״צ לפרשו ומתחיל „כשהוא חי\"), מכיון שבא בהמשך לקרבנות דיולדת שעיקרן הוא כבש לעולה."],["64","64","תנחומא תולדות ה. אסת״ר בסופו פ״י, יא."],["65","65","שהיו רועי צאן (ויגש מז, ג: אבותינו (ל' רבים)). ובפרט שייך ליצחק וליעקב (שביצחק יקרא לך זרע ולא כל יצחק (וירא כא, יב). נדרים לא, א. וש״נ) — „השה לעולה\" דעקידת יצחק, ועבודת יעקב בצאן לבן (ראה לקו״ש חט״ו ע' 254 ואילך, וש״נ)."],["66","66","שמו״ר פמ״ד, א."],["67","67","תהלים פ, ט."],["68","68","ראה לקו״ת ר״פ בהעלותך. ובכ״מ."],["69","69","תולדות כז, כב. — ולהעיר ממחז״ל עה״פ שמע ישראל גו' שאמרו השבטים „כשם שאין בלבך אלא אחד כך אין בלבנו כו' (פסחים נו א. ובשע״ת לאדהאמ״צ (ח״ב ד״ה איתא ברמ״ז פכ״ו) כך — בעולם הבריאה (שם אין ה„חי\" דאצילות))."],["70","70","ב״ר פס״ה, כ."]]],[1300171153,"דאָס דורך „כשהוא מת\", וואָס „נשענין על המתים אלו האבות\".\nט. עס ווערט אָבער די שאלה, אמת טאקע אַז „גדול הוא הרועה שמצילה ושומרה\", אָבער וויפל איז דער שיעור צו זיין בין ע' זאבים? די אריכות הכי גדולה פון זמן הגלות?\nאויף דעם איז די משנה ממשיך אַז דורך דעם וואָס ס'איז דאָ די זקנה אין מצב הגלות, „בישישים\" און „אורך ימים\", וועט צוקומען נאָך מער „חכמה\" און „תבונה\".\nוע״ד ווי מען געפינט באַ יצי״מ71, אַז כאטש די אידן האָבן געטענה׳ט אַז מ'איז מוותר אויפן רכוש גדול אבי מ'זאל אַרויסגיין פריער פון גלות, האָט דער אויבערשטער געוואלט דוקא אַז מ'זאל אַרויסגיין ברכוש גדול.\nדי פנימיות כוונת הגלות איז דער בירור הניצוצות72, דוקא דאן ווען מ'נעמט „כספם וזהבם אתם\"73, מ'איז מברר אלע ניצוצות פון חלקו בעולם, איז די גאולה אַ שלימות'דיקע.\nבזמנינו אנו איז דאָך שוין געווען אויך די „זקנה\" און „שיבה\" אין גלות ולכל הדיעות74, ביז צו אַ זקנה מופלגה, און טאָמער ס'זיינען ח״ו געבליבן נאָך עטלעכע רגעים צו דער שלימות הזקנה אין גלות — איז יהי רצון, אַז מ'זאל פארגעסן אויף אלע חשבונות\n[כאטש אַז אין שכחה לפני כסא כבודך, איז דאָך אָבער דער גאנצער ענין הגלות למטה מכסא הכבוד75, וואָס דארטן איז דער ענין השכחה76, זאלן פארגעסן ווערן אלע חשבונות און]\nס'זאל זיין דער נגאלין מיד77, בעגלא דידן, למטה מעשרה טפחים, ע״י משיח צדקנו.\n(משיחות כ״ף מנ״א, ש״פ עקב וש״פ ראה תשל״ז)",[["71","71","ברכות ט, סע״א ואילך."],["72","72","תו״א ר״פ לך. שם קיז, ב. ובכ״מ."],["73","73","ישעי' ס, ט."],["74","74","דכלו כל הקיצין (סנהדרין צז, ב)."],["75","75","ע״ד הידוע מאמר אדה״ז (פלח הרמון שמות ז, א) „שלפני נשמות הגבוהות כמו רשב״י לא נחרב הבית כלל\"."],["76","76","ראה הל' ת״ת לאדה״ז פ״ב ס״י. ועאכו״כ שצ״ל שכחה לטובה."],["77","77","רמב״ם הל' תשובה פ״ז ה״ה."]]],[1300171154,"א. פון פסוק ¹ „כל ימי אשר הנגע בו יטמא גו׳ בדד ישב מחוץ למחנה מושבו״, לערנט מען אפ ², אז אויך דער „מושב״, וואו דער מצורע געפינט זיך איז טמא.\nווען א מצורע גייט אריין לבית חבירו — זאגט די משנה ³: „כלים מיד טמאין ר׳ יהודה אומר אם שהה כדי הדלקת הנר״. זיינען מפרשים ⁴ מסביר דעת ר׳ יהודה, אז ער רעדט אין א פאל ווען דער מצורע איז אריין לבית חבירו אן רשות ⁵\n— ווארום ווען ער גייט אריין צו אים מיט רשות (פונעם בעה״ב) איז אויך ר׳ יהודה מודה אז יענעמס בית ווערט „מושבו״ מיד (ובמילא „מיד טמאין״) —\nדעריבער גיט מען צייט („כדי הדלקת הנר״) אז דער בעה״ב זאל דערווייל קענען ארויסשיקן דעם מצורע פון שטוב; אויב אבער ער פארזאמט זיך דארט ביז דעם שיעור „ולא אספקי״, ווערט עס דאן דער „מושב״ פון מצורע (ווייל דאס הייסט אז ער איז דארט מיט דעם רשות פון בעה״ב) און די כלים שבבית ווערן טמא.\nאון דער טעם פארוואס מ׳גיט אים דעם שיעור זמן „כדי הדלקת הנר״ — ווייל עס קען זיין אז דער בעה״ב איז טרוד אין הדלקת הנר און צוליב דעם שיקט ער ניט ארויס דעם מצורע פון בית (און דער מצורע געפינט זיך דארט שלא ברשותו) און דערפאר ווארט מען ביזן שיעור פון „כדי הדלקת הנר״.\nב. אין תורה איז דאך אלץ בתכלית הדיוק. און דערפון וואס פון צווישן פארשידענע זאכן מיט וועלכע א בעה״ב קען זיין טרוד, קלייבט אויס די משנה דוקא די טרדא פון „הדלקת הנר״\n— ובפרט אז דא ווערט ניט געמיינט הדלקת הנר בפועל, ווי ס׳איז מפורש אין פירוש הרא״ש „ופעמים שאדם טרוד בהדלקת הנר או בתשמיש אחר״; נאכ־מער: די צייט פון הדלקת הנר איז שכיח נאר ווען ס׳איז פינסטער, און דער שיעור „כדי הדלקת הנר״ איז אויך ווען א מצורע גייט אריין בבית חבירו בייטאג (ווי מפרשים ⁶ זאגן צוליבן טעם פון „לא פלוג״) —\nאיז דערפון מובן, אז עס איז פאראן א שייכות צווישן דעם ענין פון „הדלקת הנר״ מיט דעם וואס די משנה זאגט דא, אז ביז דעם שיעור ווערן די כלים שבבית ניט טמא.\nאיז מבאר דערויף דער טאטע אין זיינע הערות ⁷ אויף דער משנה הנ״ל: „בית״ איז ספירת המלכות, און סיבת טומאת מצורע איז „מצד הסתלקות אור החכמה״ [וואס דערפאר איז מצורע חשוב כמת ⁸, ווייל „החכמה ⁹ תחי׳״] ¹⁰.",[["1","1","פרשתנו יג, מו."],["2","2","תו״כ עה״פ. רמב״ם הל׳ טומאת צרעת ספ״י."],["3","3","נגעים פי״ג מי״א. — ברע״ב מפרש המשנה איירי „כשנכנס עמהן לבית המנוגע״. וראה תוי״ט ומלאכת שלמה."],["4","4","ר״ש, פי׳ הרא״ש ורע״ב."],["5","5","כמ״ש בתוספתא נגעים פ״ז, יא — הובא בר״ש ורא״ש שם."],["6","6","תוי״ט."],["7","7","תורת לוי״צ ע׳ שנח ואילך."],["8","8","נדרים סד, ב. וש״נ."],["9","9","קהלת ז, יב."],["10","10","ע״ח של״ח פ״ז. הובא בלקו״ת פרשתנו כג, ב. ר״פ מצורע *. *) בלקו״ת שם: של״ז (ע״פ דפוס שקלאב, תק״ס)."]]],[1300171155,"און דעריבער, כל זמן דער בעה״ב איז טרוד מיט הדלקת הנר — וואס „הדלקת הנר הוא המשכת אור החכמה״ — דער־לאזט עס ניט אז די טומאת המצורע זאל זיך מתפשט זיין אין בית ¹¹. און ע״ד ווי טהרת המצורע איז דורך א כהן דוקא — „והובא אל הכהן ויצא הכהן גו׳״ ¹² — ווייל א כהן איז דער וואס איז ממשיך דעם אור החכמה, כמבואר אין לקו״ת ¹³.\nג. אויף דעם וואס דער מצורע איז מטמא דוקא נאכן שיעור „כדי הדלקת הנר״ שטעלט זיך די שאלה: אפי׳ אויב דער בעה״ב איז פארנומען אין הדלקת הנר, איז די טרדא ניט אזוי גרויס אז ער זאל בשעת מעשה גופא ניט קענען הייסן דעם מצורע ארויסגיין פון זיין בית?\nאון מ׳פארענטפערט ¹⁴, אז דער שיעור „כדי הדלקת הנר״ רעדט וועגן „הדלקת הנר דבי שמשי״ ¹⁵ — הדלקת נרות שבת קודש — און דערפאר קען ער ניט מפסיק זיין אויף צו הייסן דעם מצורע ארויסגיין פון שטוב; און וויבאלד אז ביי „בי שמשי״ פאדערט זיך דער שיעור, איז אויך ביי די אנדערע טעג פון וואך נקבע געווארן דער שיעור „כדי הדלקת הנר״ מצד „לא פלוג״.\nאון לויט ווי דער טאטע איז אין דעם מבאר — אז דער טעם השיעור פון „כדי הדלקת הנר״ איז ווייל „הדלקת הנר״ דערלאזט ניט די טומאת המצורע — דארף אויסקומען, אז דער כח אויף ניט דערלאזן טומאת מצורע איז בעיקר מצד „הדלקת הנר דבי שמשי״, וויבאלד אז דער עיקר־שיעור נעמט זיך פון דער הדלקה.\nדער ביאור אין דעם: די משנה רעדט ניט וועגן טומאת המצורע פאר זיך, נאר וועגן דער טומאת המצורע וואס ווערט נתפשט אין בית — און דעריבער איז דאס בעיקר פארבונדן מיט הדלקת נרות „דבי שמשי״, היות אז די נרות שבת קודש טיילן זיך אויס פון אנדערע נרות דערמיט וואס ענינם איז — שלום בית ¹⁶: זיי באלייכטן דעם בית „שלא יכשל בעץ או באבן״ ¹⁷, זיי פארהיטן אז אין בית זאלן ניט זיין קיינע מאורעות בלתי רצויים. און דעריבער טוען אויף די נרות אין בית אויך דאס אז די טומאה זאל ניט נתפשט ווערן אין בית.\nד. מען קען אבער אין דעם פרעגן: דער שלום בית על ידי נר שבת ווערט אויפגעטאן דורך דער גשמיות׳דיקער ליכטיקייט — ולכאורה יעדער אנגע־צונדענער נר, אויך ווען ער איז ניט קיין נר מצוה באלייכט דעם בית „שלא יכשל בעץ או באבן״ און ברענגט דורך דעם צו שלום בית — היינט אין וואס באשטייט דער יתרון פון „הדה״נ דבי שמשי״, וואס דוקא די הדלקה ווערט דער עיקר אין ניט דערלאזן אז אין בית זאל זיין (היפך השלום — און דערפאר אויך ניט) התפשטות הטומאה?\n— איז אבער דער אמת ניט אזוי: סתם ליכטיקייט, ניט זייענדיק פארבונדן מיט",[["11","11","אף שאין הלכה כר״י — הרי אלו ואלו דא״ח (עירובין יג, ב. וש״נ). וראה לקוטי לוי״צ אגרות ע׳ שה."],["12","12","ר״פ מצורע."],["13","13","דלעיל הערה 10. הובא בתולוי״צ שם."],["14","14","הובא בתפא״י."],["15","15","לשון הר״ש (ועד״ז ברע״ב) — אלא שמוסיף (ועד״ז ברע״ב) „או דשאר ימות החול״. ובהון עשיר: הדלקת הנר בה״א הידיעה נראה דאנר של שבת קאי כו׳."],["16","16","שבת כג, ב. רמב״ם סוף הל׳ חנוכה. טושו״ע או״ח סרס״ג ס״ג. שו״ע אדה״ז שם בריש הסימן."],["17","17","מג״א שם סקי״ג־יד (ממרדכי שבת פ״ב סרצ״ד). שו״ע אדה״ז שם."]]],[1300171156,"„נר מצוה״ ¹⁸, איז ניט (תמיד) זיכער אז דאס וועט זיין א סיבה צו שלום; עס קען אמאל זיין להיפך: אין דער ליכטיקייט דערזעט מען אמאל א מענטשן (אדער א תנועה און א שטריך אין א מענטשן) וואס מ׳קען ניט פארליידן, אזוי אז די ליכטיקייט קען גאר ארויסרופן דעם היפך פון שלום.\nדוקא די אמת׳ע ליכטיקייט, די ליכט פון „נר מצוה ותורה אור״ ¹⁸, וואס „כל התורה ניתנה לעשות שלום בעולם״ ¹⁹ — איז זי די אמת׳ע און זיכערע סיבה וואס ברענגט צו (אחדות און) שלום, שלום בית.\nה. דאס אלץ איז א הסבר אויף דער שייכות פון נרות שבת קודש מיט דעם ענין פון ניט דערלאזן התפשטות פון יעדער טומאה אין בית. פון דעם אבער וואס דער שיעור „כדי הדלקת הנר״ ווערט געבראכט לגבי טומאת מצורע, איז פארשטאנדיק, אז פארהיטונג פון דער טומאה חמורה האט א שייכות מיוחדת מיט נרות שבת קודש.\nבפשטות קען מען זאגן: איינע פון די סיבות פון צרעת איז לשון הרע ²⁰, אן ענין פון פירוד הלבבות, דערפאר איז תיקונו דוקא דורך נרות שבת קודש וואס ענינם איז שלום בית, כנ״ל.\nדער ביאור בפנימיות הענינים, וועט מען פארשטיין בהקדים דאס וואס חז״ל ²¹ זאגן: „הרגיל בנר הויין לי׳ בנים תלמידי חכמים״. טייטשט רש״י: „דכתיב ¹⁸ כי נר מצוה ותורה אור על ידי נר מצוה דשבת וחנוכה בא אור דתורה״. פון דעם איז מובן, אז כאטש „נר מצוה״ מיינט יעדער מצוה — ווייל דורך יעדער מצוה וואס א איד טוט ווערט ליכטיק ביי אים און אין דער וועלט ארום אים — פונדעסטוועגן איז אין דעם פרט פאראן א יתרון אין די מצוות וואס זיינען אויך אין גשמיות פארבונדן מיט א נר, ווארום אין זיי דריקט זיך מער אויס דער ענין פון „נר מצוה״:\nביי אנדערע מצוות, וויבאלד דער „נר מצוה״ איז בלויז א רוחניות׳דיקע ליכטי־קייט, האט עס ניט קיין ווירקונג בגלוי אויף דער גשמיות פון וועלט; משא״כ ביי די מצוות, וויבאלד זייער „נר מצוה״ איז פארבונדן מיט אן אור פון א נר גשמי, דעריבער איז די פעולה פון דער רוחניות׳דיקער ליכטיקייט („נר מצוה״) אין אן אופן אז זי קומט בגילוי אין גשמיות העולם.\nו. דערמיט וועט זיין פארשטאנדיק וואס די גמרא ²² זאגט וועגן דעם נר מערבי אין ביהמ״ק — „עדות היא לבאי עולם שהשכינה שורה בישראל״ (מצד דעם נס וואס איז געשען ביים נר מערבי — „ממנה הי׳ מדליק ובה הי׳ מסיים״).\nלכאו׳ איז ניט פארשטאנדיק: אין ביהמ״ק זיינען דאך געשען א סאך נסים, ווי די משנה ²³ זאגט „עשרה נסים נעשו לאבותינו בבית המקדש״, היינט פאר־וואס איז דער נס פון נר מערבי אויסגע־טיילט פון אלע נסים וואס דוקא ער איז געווען אן עדות „שהשכינה שורה בישראל״?",[["18","18","משלי ו, כג."],["19","19","רמב״ם שם. וראה לקו״ש ח״ח ס״ע 349 ואילך."],["20","20","ערכין טז, א. רש״י כאן. מצורע יד, ד."],["21","21","שבת שם."],["22","22","שבת כב, ב. ובמנחות פו, ב: לכל באי עולם."],["23","23","אבות פ״ה מ״ה."]]],[1300171157,"נאכמער: דער מקום המנורה איז אין היכל, און דארט גופא — ניט אין אולם, נאר — אין דעם ארט וואס הייסט „קודש״ ²⁴, וואו ניט יעדער האט געקענט אריינגיין; דאקעגן פון די „עשרה נסים״ זיינען געווען א טייל און שטענדיג „בעזרה״ [און צווישן זיי אויך אזעלכע וואס האבן פאסירט אין ירושלים מחוץ לעזרה] און אזוי ארום זיינען זיי געווען מער „ידועים לכל״ ²⁵ — היינט ווי זאגט מען אז דוקא דער נס פון נר מערבי וואס איז געווען „בתוך הקודש״ האט עדות געזאגט „לבאי עולם שהשכינה שורה בישראל״?\nאיז דער ביאור אין דעם, כנ״ל: וויבאלד די ג־טליכע ליכטיקייט פון דעם נר מערבי איז אראפגעקומען אויך אין גשמיות׳דיקער ליכטיקייט, האט זי דעריבער געהאט א שטארקערע ווירקונג אין באלייכטן די גשמיות׳־דיקע וועלט ווי עס האבן געהאט די אנדערע ענינים (און נסים) אין ביהמ״ק. און דערפאר האט דוקא דער נס באאיינ־פלוסט („עדות״) די „באי עולם״ זיי זאלן אנערקענען שהשכינה שורה בישראל.\nאון עפ״ז איז אויך מובן, אז עס איז פאראן א מעלה מיוחדת אין נרות שבת קודש:\nאויף גאנץ תורה זאגט מען ¹⁹ „כל התורה ניתנה לעשות שלום בעולם״ — אז דורך „כל התורה״ ווערט אויפ־געטאן „שלום בעולם״, אבער דאס איז (בעיקר) א שלום ברוחניות; משא״כ ביי נרות שבת קודש, וואו דער שלום וואס ווערט דורך זיי אויפגעטאן זאגט זיך ארויס (אויך) אין שלום בית כפשוטו —\nאיז דאס גופא א באווייז, אז ביי דער מצוה איז דער „שלום בעולם״ מיט מער תוקף. [ולהעיר אז דער מאמר „כל התורה ניתנה לעשות שלום בעולם״ ווערט געבראכט אין רמב״ם ²⁶ בהמשך צום ענין פון שלום בית וואס ווערט אויפגעטאן דורך נרות שבת].\nז. די הסברה אין דעם:\nאיינער פון די פירושים אין „כל התורה ניתנה לעשות שלום בעולם״ איז: די אמת׳ע מציאות פון וועלט איז — ג־טליכקייט. ווי דער אלטער רבי איז מבאר באריכות אין תניא ²⁷, אז דאס וואס די וועלט האט א קיום איז עס דורך דעם וואס דער אויבערשטער באשאפט זי שטענדיק בכל רגע ורגע מאין ליש.\nנאר היות אז דער כח אלקי ווירקט אין וועלט אין א פארבארגענעם אופן, דערפאר זעט זיך אן די וועלט ווי א מציאות פאר זיך, ביז מען קען מיינען אז „בירה זו בלא מנהיג״ ²⁸ ח״ו.\nאון אין דעם באשטייט דער אויפטו און תכלית פון „נר מצוה ותורה אור״, אז דורך דעם וואס מען לערנט תורה און מען איז מקיים מצוות, ווערט באלויכטן די מציאות פון וועלט — אין דער דוגמא פון „הציץ עליו בעל הבירה״ ²⁸ — און מען דערזעט דעם אמת, אז יש מנהיג לבירה זו, ביז מען דערזעט אז „אין עוד מלבדו״.\nאון דאס איז דער דיוק פון „התורה ניתנה לעשות שלום בעולם״: דאס וואס תורה איז „ניתנה״ ²⁹, זי איז געגעבן",[["24","24","רמב״ם הל׳ ביהב״ח פ״א ה״י."],["25","25","יומא כא, סע״א. רש״י שם."],["26","26","בסיום וחותם הל׳ (נר) חנוכה ברמב״ם שם. נת׳ בלקו״ש חט״ו ע׳ 376 ואילך."],["27","27","שער היחוד והאמונה פ״א ואילך. אגה״ק סכ״ה."],["28","28","לשון המדרש — ב״ר רפל״ט."],["29","29","ראה לקו״ש שם ע׳ 351."]]],[1300171158,"געווארן (דא למטה אין עוה״ז), איז עס בכדי „לעשות שלום בעולם״ — דורך מאכן שלום צווישן דעם עולם מיטן אויבערשטן; מ׳זאל דערזעהן ווי עולם איז ניט מנגד צו אלקות, און נאך מער — זיין תכלית איז צו זיין א דירה לו ית׳ דורך דער תורה ועבודה פון אידן.\nח. דערמיט איז מובן אז אין דעם באשטייט אויך די מעלה מיוחדת פון נרות שבת קודש — וואס ביי זיי איז דער ענין פון „שלום בעולם״ מיט מער תוקף (כנ״ל ס״ו) — אז דער ענין פון „שלום בעולם״, דערזעהן אז די אמיתית המציאות פון וועלט איז אלקות, ווערט דורך נרות ש״ק אויפגעטאן נאכמער ווי דורך אנדערע מצוות [ווי עס שטייט אין זהר ³⁰: „כי נר מצוה, מאי נר מצוה דא . . נר דשבת״; אין נרות שבת קודש איז דער ענין פון „נר מצוה״ — באלייכטן די וועלט — מיט מער תוקף לגבי אנדערע מצוות, אפילו די וואס זיינען פארבונדן מיט א נר גשמי].\nוי״ל, אז דאס איז דער טעם פנימי וואס ביים ענין פון „שלום בית״ וואס נר שבת טוט אויף, שטייט ¹⁷ דער לשון „שלא יכשל בעץ או באבן״. וואס איז דער דיוק „עץ״ או „אבן״? — נאר דער־מיט איז מען מרמז צום פסוק ³¹ „אומרים לעץ אבי אתה ולאבן את ילדתני״, אז פון דעם עץ או אבן ווערט געמאכט אן עבודה זרה רח״ל. און דאס איז דער אויפטו פון נרות שבת קודש — „שלא יכשל בעץ או באבן״: די מציאות פון עץ און אבן מצד עצמם (איידער זיי ווערן באלויכטן דורך נרות שבת) קען אמאל מכשיל זיין ח״ו מען זאל מיינען אז זיי (דער עץ או אבן) האבן ח״ו אן אייגענע מציאות, און אייגענעם כח, ביז צו אנרופן דעם עץ — „אבי״, און דעם אבן — „את ילדתני״ (א מציאות פון ע״ז רח״ל):\nדורך דער ליכטיקייט פון נרות שבת קודש, וואס זייער „נר מצוה״ און (פעולה פון) „שלום בעולם״ ווירקן באופן גלוי אויף גשמיות העולם, ווערט באווארנט „שלא יכשל בעץ או באבן״, ווארום דורך זיי דערזעט מען אז דער עץ און אבן (ווי יעדער מציאות שבעולם) ווערט אנגעפירט פון דעם בעל הבירה און אז זיי גופא דארפן אויסגענוצט ווערן אויף ענינים פון קדושה.\nט. ע״פ כהנ״ל איז אויך מובן דער קשר מיוחד צווישן די טהרה פון טומאת מצורע און נרות שבת קודש:\nטומאת מצורע איז דאך פון די טומאות הכי חמורות, וואס דערפאר איז ביי א מצורע דער דין „בדד ישב מחוץ למחנה מושבו״: ער ווערט ארויס־געשיקט מחוץ לג׳ מחנות ³², און אין דעם גופא — „בדד ישב״, שלא יהו טמאין אחרין יושבין עמו *³² — דער ארט פון א מצורע איז אפי׳ מחוץ למחנה פון אנדערע טמאים, ד. ה. ער איז אינגאנצן ארויס פון מחנה הקדושה.\nאון דער טעם הדבר איז, ווייל אויך דער חטא וואס ברענגט צו צרעת — לשון הרע — איז זייער הארב דערמיט וואס ער דערפירט (בלשון הרמב״ם ³³) „לדבר באלקים וכופרין בעיקר״, וואס דורך דעם ווערט מען רח״ל אינגאנצן אפגעריסן פון דעם אויבערשטן ³⁴.",[["30","30","ח״ב קסו, א."],["31","31","ירמי׳ ב, כז."],["32","32","רש״י עה״פ (מתו״כ שם). וראה פסחים סז, א. *32) רש״י עה״פ (מפסחים שם. ועד״ז בתו״כ שם). וראה לקו״ש חכ״ב ע׳ 74 ובהערה 49."],["33","33","סוף הל׳ טומאת צרעת."],["34","34","ראה גם לקו״ש ח״א ע׳ 101."]]],[1300171159,"און דעריבער, כדי ניט צו דערלאזן די התפשטות פון אזא טומאה, איז עס דוקא דורך נרות שבת קודש — ווייל זיי האבן א שטארקערע ווירקונג אויף גשמיות העולם, ביז אז דוקא זיי באווארענען „שלא יכשל בעץ או באבן״ — און ענין פון ע״ז רח״ל (כנ״ל בארוכה) — און דערפאר דערלאזן זיי ניט די טומאה פון מצורע וואס איז פארבונדן מיט „לדבר באלקים וכופרין בעיקר״.\nיוד. לויט ווי דער טאטע איז מבאר אין זיינע הערות, אז דער ענין פון הדלקת הנר איז ע״ד טהרת המצורע דורכ׳ן כהן (כנ״ל ס״ב), איז דאס אויך פארשטאנדיק בענינינו: דער כח פון נרות שבת קודש איז ניט נאר אין דעם וואס זיי זיינען מעכב די התפשטות פון טומאת המצורע, נאר נאכמער, זיי האבן בכח צו מאכן אז די כלים בלייבען טהור (פון טומאת המצורע):\nובדוגמא שלהם — טהרה ע״י הכהן — ווערט ע״ד פון אתהפכא חשוכא לנהורא ³⁵, „זדונות נעשות לו כזכיות״ ³⁶ — אז פון דעם „בדד ישב וגו׳״ וואס ווייזט אויף תכלית הירידה (כנ״ל ס״ט), ווערט „בדד ישב״ למעליותא ³⁷ — „הן עם לבדד ישכון גו׳״ ³⁸, „בטח בדד עין יעקב גו׳״ ³⁹ — וואס איז תכלית הברכה.\nאון אזוי איז אויך בהנוגע צו דעם חושך הגלות ⁴⁰, ובפרט דער חושך כפול ומכופל פון דרא דעקבתא דמשיחא, אז דורך דעם „אור״ פון נרות שבת קודש וועט מען באלייכטן דעם חושך הגלות און מבטל זיין עם און נאך מער — מען קומט לגאולה ובנין ביהמ״ק ו„מראה לכם נרות של ציון״ ⁴¹, און עס ווערט „והי׳ לך ה׳ לאור עולם״ ⁴², ביז אז דער חושך הגלות עצמו וועט נתהפך ווערן לאור — „ולילה כיום יאיר״ ⁴³.\n* * *\nיא. פון כהנ״ל איז פארשטאנדיק, אז אינעם איצטיקן זמן ווען דער חושך פון וועלט איז אזוי גרויס און געדיכט, איז ספעציעל וויכטיג אז יעדע אידישע טאכטער (אויך פון קרייזן וואו די טעכטער פלעגן ביז איצט אנהייבן בענטשן ליכט נאך זייער חתונה און ביז דאן יוצא געווען מיט דער מוטערס ליכט־בענטשן), גלייך ווי הגיעה לחינוך (אז מען קען איר מסביר זיין די באדייטונג פון נרות שבת ויום טוב ⁴⁴), זאל אליין בענטשן ליכט ⁴⁵.",[["","","הנני מחלל את מקדשי גאון עוזכם״. ובפתיחתא דאכי״ר (כא): „והצרוע אשר בו הנגע וגו׳ (פרשתנו יג, מה). והצרוע זה בית המקדש . . וטמא טמא יקרא חורבן ראשון וחורבן שני״."],["41","41","ילק״ש ר״פ בהעלותך."],["42","42","ישעי׳ ס, יט."],["43","43","תהלים קלט, יב. וראה ס׳ הערכים־חב״ד ח״ב ע׳ אור־ביחס לחושך (ע׳ תקצו) וש״נ. המשך תער״ב חלק ג׳ ע׳ א׳שמה."],["44","44","ראה שו״ע אדה״ז תאו״ח ססמ״ג ס״ג."],["45","45","להעיר – וג״ז עיקר: בבית שמאיזה סיבה שתהי׳ אין האם מדליקה נרות – לדה״ה צריכה חבת להדליק (עכ״פ משנעשית בת מצוה), ובמילא צ״ל השתדלות בזה ככל האפשרי. באם חבנות בבתי שומרי תומ״צ שבסביבתה לא תדליקנה נרות – מובן שהצלחת השתדלות זו תהי׳ קשה ביותר, כנראה במוחש. וד״ל."],["35","35","ראה בארוכה לקו״ש שם ע׳ 103 ואילך."],["36","36","יומא פו, ב."],["37","37","ראה רשימות הצ״צ לאיכה (אוה״ת כרך ב׳ ע׳ אילך. אימב ואילך (ושם לענין „בדד״ דמצורע)). ד״ה איכה תשל״א (בתחילתו. פ״ד ואילך) — ספר המאמרים — מלוקט ח״א ע׳ קיט ואילך."],["38","38","בלק כג, ט."],["39","39","ברכה לג, כח."],["40","40","ראה ויק״ר ספי״ז: „בבית ארץ אחוזתכם (מצורע יד, לד) זה בהמ״ק שנאמר (יחזקאל כד, כא)"]]],[1300171160,"און די ליכטיקייט פון נר שבת, מיט דער ברכה וואס זי וועט מאכן אויף דעם, וועט באלייכטן איר לעבן, אז זי וועט וויסן און געדענקען (ווי זי זאגט אין דער ברכה) אז דער אויבערשטער איז דער „מלך העולם״; און עס קומט צו אין דער זיכערקייט אז בשעת זי וועט האלטן ביי חתונה האבן וועט בא איר זיין „הוי׳ לך לאור עולם״, זי וועט אלס עקרת הבית — בויען און איינשטעלן איר הויז לויט דעם רצון הוי׳, על יסודי התורה והמצוה.\nיב. נאך א טעם אויף נויטיקייט פון ליכט־צינדן פאר אלע בנות ישראל:\nווי דערמאנט פריער (ס״ה), איז מען דורך נר שבת זוכה צו קינדער [און איידעמס ⁴⁶] תלמידי חכמים. ובכן: אמאליקע יארן, ווען ס׳איז געווען דער סדר אז די עלטערן האבן באשלאסן וועגן א שידוך פאר דער טאכטער — איז במילא אויך דער עיקר ⁴⁷ זכות פון דער מוטער׳ס נר שבת, אז איר טאכטער זאל חתונה האבן פאר א תלמיד חכם;\nהיינטיקע צייטן, ווען מצד פאר־שידענע סיבות איז דער בפועל — צי מ׳וויל יע אדער ניט — אז ביי א שידוך פאר זיך באשליסט בעיקר די טאכטער, פאדערט זיך נאכמער אז זי אליין זאל בענטשן ליכט, און דער „נר מצוה״ וואס זי וועט צינדן וועט איר געבן דעם זכות זי זאל חתונה האבן פאר א תלמיד חכם ⁴⁸.\nאון היינטיקע צייטן — וואס אפי׳ אין פרומע הייזער איז מען ניט אלעמאל זיכער אז די עלטערן וועלן האבן א דעה מחלטת ביי דער טאכטער ווען זי וועט עלטער ווערן — דארף מען זיך באמיען און משתדל זיין ביותר און אזוי פרי ווי מעגליך, ד. ה. ווי נאר זי דערגרייכט דעם גיל החינוך פון הדלקת נר שבת קודש, זאל זי אנהויבן בענטשן ליכט בכל ערב שבת וערב יו״ט,\nוואס דאס פארשטארקט אויך די פאר־זיכערונג פון תורה, אז מען וועט זי מגדל זיין „לתורה ⁴⁹ ולחופה ולמעשים טובים״ ⁵⁰, און זי וועט חתונה האבן פאר א תלמיד חכם.\n(משיחות ש״פ מצורע תשל״ו, ש״פ האזינו תשל״ה)",[["46","46","רש״י שבת כג, ב."],["47","47","אף שגם אז צ״ל זכות הבת שהרי אינה מתקדשת אלא לדעתה (קידושין ב, ב)."],["48","48","אף שבגמרא שם מדובר רק בהשכר דהוי בנים (וחתנים) ת״ח — מפורש בזהר * (דלעיל הערה 30) ד״נר מצוה״ של האשה מביא „ותורה אור״ אצל בעלה (אלא שבאם מאיזו סיבה אינו פועל על בעלה אזי פועל אצל הבנים). ועוד: אפילו באם נאמר (אבל ראה שוה״ג הא׳) שלפי הש״ס השכר הוא רק בנים (וחתנים) — מכיון שהדלקת הנר של הבת (לפני בת מצוה **) היא מצד מצות החינוך שהיא מוטלת על האב, הרי השכר שייך בעיקר להאב — היינו חתנים ת״ח."],["49","49","כן הוא הנוסח גם בהולדת בת ע״פ מכתב כ״ק אדמו״ר מהורש״ב נ״ע (ע״פ ברכות יז, א)."],["50","50","נוסח „מי שברך״ להולדת בן ובת. *) וראה ב״ח או״ח סתרע״א (ד״ה והזהיר) דכן הוא הפירוש בגמרא, דמ״ש בגמרא דזוכה לבנים ת״ח היינו אי הבעל לאו בר הכי. ובלבוש שם (ס״א) דבאיש השלם ידבר. **) ולהעיר מהשקו״ט (ראה בארוכה ציונים לתורה — להר״י ענגל — כלל יב) האם נפקע חיוב חינוך לאחר בר מצוה — אלא שכאן המדובר בחיוב שעל (והשכר המסובב מזה של) האב, שאין זה שייך לאחר בת מצוה."]]],[1300171161,"<h3>תזריע — פ׳ החודש</h3>\nא. שבת פ׳ החודש איז חל לפעמים (אזוי ווי היינטיקן יאר) בשבת פ׳ תזריע. אלע ענינים פון תורה זיינען בדיוק — איז פון דעם גופא וואס די ביידע פרשיות קומען צוזאמען, איז מוכח, אז זיי האבן צווישן זיך א נקודה משותפת (ווייל אויב ניט, וואלט תורת אמת זיי ניט מחבר געווען צוזאמען).\nבהשקפה ראשונה זעט אבער אויס, אז ניט נאר האבן זיי ניט קיין נקודה משותפת, נאר, אדרבה, זיי זיינען גאר ענינים הפכיים¹, זה מזה:\nפ׳ החודש ווערט אנגערופן על שם דעם פסוק*¹ „החודש הזה לכם ראש חדשים גו׳“ — חודש ניסן, וואס ענינו איז חודש הגאולה² ווי עס קומט אינ־גאנצן מלמעלה כדרז״ל³ אז אויף דעם גייט קול דודי הנה זה בא (און נאכמער ער איז בא אין אן אופן פון) מדלג (דילג על הקץ⁴) (באתערותא דלעילא)⁵:\nוואס דערפאר ווערט די גאנצע פרשה אנגערופן פ׳ החודש, הגם אז נאר איין פסוק (אין אנהויב) פון דער קריאה רעדט וועגן „החודש“, און די איבעריקע פסוקים ריידן וועגן די דינים פון קרבן פסח וכו׳⁶ — ווייל היא הנותנת: קרבן פסח איז על שם „ופסח⁷ ה׳ גו׳“⁸, וואס ווייזט אויף דער גאולה וואס קומט בדילוג⁹ — אינגאנצן מלמעלה — „נגלה עליהם מלך מלכי המלכים הקב״ה וגאלם“¹⁰ — און דאס איז דער תוכן פון „החודש“, חודש ניסן, וואס איז דער „חודש הגאולה“.\nמשא״כ דער תוכן פון „תזריע“ (ל׳ נקבה — ווי ער זאגט פארדעם „אשה כי“) איז — ווי דער אלטער רבי איז מפרש¹¹ דעם מאמר¹² „איש מזריע תחלה יולדת נקבה אשה מזרעת תחלה יולדת זכר“, אז „איש“ ו„אשה“ זיינען (מרמז אויף) הקב״ה וכנסת ישראל; און",[["1","1","אף שג״ז שייכות היא — וע״ד מ״ע ומל״ת במצות. חיבור התחתון ועליון (תנחומא וארא טו. שמו״ר פי״ב, ג. וראה לקו״ת (ראה כז, ד ואילך) ובכ״מ, שחיבור הנ״ל אפ״ל בב׳ אופנים, שהעליון ירד כו׳ או שהתחתון יעלה כו׳) וכהנה רבות. *1) בא יב, ב."],["2","2","שמו״ר פט״ו, יא (נעתק לקמן בפנים סעיף ב׳)."],["3","3","מכילתא בא יב, יא. שם, יג. פסיקתא רבתי פ׳ החודש ז׳. שהש״ר עה״פ (ב, ח)."],["4","4","פס״ר שם. שהש״ר שם (א)."],["5","5","כידוע בענין פלוגתת ר״א ור״י (ר״ה יא, רע״א) אם בתשרי עתידין ליגאל או בניסן — דאולי בזה לשיטתייהו בפלוגתתם (סנהדרין צז, ב) אם הגאולה תבוא ע״י תשובה או „לא בתשובה כו׳“* — *) ובאו״א קצת (אבל רק לגירסת הבבלי): אם ע״י תשובת בנ״י מעצמם או „הקב״ה מעמיד להן מלך כו׳ וישראל עושין תשובה“ (ראה ד״ה החודש תרנ״ד שם. לקו״ש ח״ד ע׳ 1292־3. חי״ב ע׳ 143). ד״ה החודש הזה באוה״ת בא (ע׳ רס. ע׳ רעא). תרנ״ד (קה״ת תשכ״ג) פ״ז. לקו״ש ח״א ע׳ 235. ועיי״כ ס׳ השיחות תש״ג ע׳ 177. ועוד."],["6","6","ובפרש״י מגילה (כט, א ד״ה ברביעית) משמע, שטעם קריאת פ׳ החודש הוא (רק) מפני דיני פסח שבה."],["7","7","בא שם, כג."],["8","8","פרש״י בא שם, יא. וראה בא שם, כז."],["9","9","ד„קרוי פסח על שם הדלוג כו׳“ — פרש״י בא הנ״ל. ועד״ז בפרש״י שם, יג."],["10","10","נוסח ההגדה. וראה לקו״ת שה״ש טו, א־ב. דרושי פסח בכ״מ."],["11","11","לקו״ת פרשתנו ד״ה שוש תשיש. ויקרא ד״ה אדם כי יקריב ספ״א. שה״ש ד״ה להבין ענין הטעם כו׳ פ״א. ועוד."],["12","12","ברכות ס, א. וש״נ (הובא בפרש״י עה״ת ויגש מו, טו)."]]],[1300171162,"ווען „איש מזריע תחלה“ — דער אוי־בערשטער איז מעורר „תחלה“ א אידן אויף עבודת ה׳, איז „יולדת נקבה“ — די עבודה איז ניט קיין בת קיימא¹³ (אזוי ווי נשים וואס דעתן•¹³ קלה¹⁴). ווען אבער „אשה מזרעת תחלה“ — די עבודה הויבט זיך אן פון אתערותא דלתתא, דאן — „יולדת זכר“, די עבודה איז א בת קיימא¹³;\nוואס לפ״ז ווייזט דער תוכן פון פ׳ „(אשה כי) תזריע“ אויף עבודת האדם מצד אתערותא דלתתא דוקא (ניט ווי „החודש“ וואס קומט מלמעלה).\nב. אויף „החודש הזה לכם ראש חדשים ראשון הוא לכם לחדשי השנה“ זיינען דא כמה פירושים, ומהם:\nא) ע״ד הפשט — דער אבן עזרא¹⁵ איז מסביר דעם ענין פון „חודש“ און „שנה“: מצד מהלך הלבנה איז בכלל ניטא דער גדר פון „שנה“ — „אין ללבנה שנה כלל“ — ווייל אין דעם סיבוב הלבנה איז קענטיק נאר דער אפ־טייל פון חדשים (יעדער חודש („כ״ט יום וחצי וב׳ ידות שעה וע״ג חלקים“¹⁶) קומט פאר א פולער סיבוב פון דער לבנה (גם בנוגע למצב החמה ביחס לארץ•¹⁶) און ס׳קומט דער מולד הלבנה מחדש), ס׳איז אבער ניטא אין דעם מהלך הלבנה קיין פרט וואס זאל אפ־טיילן איין יאר פון צוויטן;\nלאידך גיסא, מצד השמש איז ניטא דער סוג הזמן פון חדשים — „אין לשמש חדש כלל“ — דער סיבוב (השנתי) פון שמש איז שס״ה יום ושש שעות¹⁷ בערך¹⁸ און דער סיבוב זיינער איז באופן אז עס שאפט די ד׳ תקופות השנה, אבער אין זיין מהלך איז ניטא קיין פרט וואס זאל שאפן די גבולים פון חדשים.\nאון דער פסוק „החודש הזה לכם ראש חדשים גו׳“ רעדט וועגן דעם מנין החדשים — וואס איז שייך צו (א שנת) לבנה (וכמאמר חז״ל¹⁹ „ישראל מונין ללבנה“) — אז עס הויבט זיך אן פון חודש הראשון, חודש ניסן²⁰ [משא״כ דער ר״ה לשנים (וואס איז שייך צום שמש) איז פון תשרי²¹].\nב) ע״ד המדרש — אויפן פסוק",[["13","13","כ״ה בלקו״ת ויקרא שם. ובלקו״ת פרשתנו ושה״ש שם: „יולדת נקבה“ — אהבה זוטא, „יולדת זכר“ — אהבה רבה. •13) שבת לג, ב. קידושין פ, ב."],["14","14","כ״ה בכ״מ• (שהרי „דעתן“ ל׳ יחיד). — וראה בע״ח ש׳ הכללים פי״ז: ז״ס דעתן של נשים קלה פי׳ קל ה׳ כי ה״ג כו׳. [ועד״ז בכ״מ בכתהאריז״ל. וראה ל״ת להאריז״ל תהלים כה. ע״ח ש׳ לידת המוחין ספ״ב בהגהות סק״א (וורשא, תרנ״א). קה״י מע׳ קלה ומע׳ קלע, ואכ״מ]. אבל בכ״מ הגירסא „קלות“."],["15","15","עה״פ. וראה ד״ה החודש תרנ״ד פ״ז."],["16","16","לשון הראב״ע שם. מר״ה כה, א. רמב״ם הל׳ קדה״ח פ״י ה״ג. וראה בכ״ז ג״כ — פדר״א פ״ז ובהרד״ל שם. •) וכן הוא ברש״י קדושין שם (שלא שלטו בזה כ״כ ידים). אבל ראה רש״י ד״ה ואיכא (ע״ז יח, ב). •16) משא״כ במעמדה בנוגע לארץ לבדה — ה״ז כ״ז• יום שתות מיב שעות ליום•• (ברייתא דשמואל פ״ה). וראה רמב״ם הל׳ קדה״ח פי״ד ה״ב. ושם בפירוש לרפ״ג."],["17","17","עירובין נו, א רש״י ד״ה ליתנהו. רמב״ם שם פ״ז ה״ד."],["18","18","רמב״ם שם רפ״י, ונסמן בנ״כ."],["19","19","מכילתא עה״פ החודש. סוכה כט, א."],["20","20","ר״ה ז, רע״א."],["21","21","ראה ר״ה יב, א וברש״י ותוס׳ שם. •) כן הגיהו המפרשים. ••) שעות שהן חלק י״ב מיום שלם (שהן שני שעות הרגילות)."]]],[1300171163,"„החודש הזה לכם גו׳“ זאגן חז״ל²²: „משבחר הקב״ה בעולמו קבע בו ראשי חדשים ושנים וכשבחר ביעקב ובניו קבע בו ר״ח של גאולה“. איז מסביר דער (בעל ה)עקידה²³ דעם חילוק צווישן „בחר הקב״ה בעולמו“ און „בחר ביעקב ובניו“: „בחר הקב״ה בעולמו“ מיינט די הנהגה טבעית וואס איז איינגעשטעלט געווארן אין דער בריאה, און דער „ראש“ פון דער הנהגה איז חודש תשרי; „בחר ביעקב ובניו“ מיינט די הנהגה נסית — דער שידוד הטבע — וואס דער אויבערשטער טוט צוליב אידן („יעקב ובניו“), און דער „ראש“ פון דער הנהגה איז „החודש הזה לכם“ — חודש ניסן.\nג. אלע פירושי רז״ל אויפן זעלבן פסוק אדער ענין האבן א קישור צווישן זיך²⁴. איז אזוי אויך בעניננו: די צוויי ענינים הנ״ל (דער חילוק צווישן שנת חמה און שנת לבנה און דער חילוק צווישן הנהגה טבעית און הנהגה נסית — וואס זיי זיינען הפכיים) זיינען פאר־בונדן זה עם זה:\nדי הנהגת הטבע איז די הנהגה וואס איז „לא ישבותו“²⁵ — תמידית אן א שינוי²⁶, און דאס איז בדומה צום אור (ומהלך) השמש וואס אין אים איז ניטא קיין שינויים (וואס דאס איז ע״ד פון דעם פירוש אין „שנה“ — פון לשון „משנה“: ס׳איז דער זעלבער מהלך השמש וואס חזרט זיך איבער נאכ־אמאל²⁷);\nמשא״כ די הנהגה נסית איז אן ענין פון חידוש, וואס לפעמים איז דער אויבערשטער משדד די הנהגת הטבע²⁶ למשך זמן•²⁷; און דאס איז בדומה צו דער לבנה וואס (איר אור) שטייט אין שינויים מיום ליום און איר אור ווערט נתחדש יעדער חודש (חודש פון לשון חידוש²⁸).\nד. מ׳דארף אבער פארשטיין:\nא) אין פסוק שטייען צוויי ענינים²⁹: (א) „החודש הזה לכם ראש חדשים“, (ב) „ראשון הוא לכם לחדשי השנה“, אז חודש ניסן איז ניט נאר דער „ראש חדשים“, נאר אויך דער „ראשון גו׳ לחדשי השנה“³⁰ — איז ניט מובן: ווי־באלד אז דא רעדט זיך וועגן ענין „החודש“ וואס איז פארבונדן מיט דער לבנה, און „אין ללבנה שנה כלל“, איז ווי זאגט מען אז ניסן איז דער „ראשון“ אויך בשייכות צו עניני „(חדשי) השנה“?\nב) לאידך גיסא: אויך „משבחר הקב״ה בעולמו“, וואס איז שייך צו תשרי, ווערט דערמאנט (ניט נאר „קבע בו . . שנים“, נאר) אויך „ראשי חדשים“ —",[["22","22","שמו״ר פט״ו, יא."],["23","23","פ׳ בא עה״פ החודש גו׳ (שער לח). הובא ונת׳ באוה״ת בראשית יח, ב ואילך. רד״ה החודש תרנ״ד. תרס״ו. תרע״ח (דפ׳ החודש). ועוד. ועפ״ז מבאר בעקידה שם גם הקשר דדיני הפסח לפ׳ החודש, עיי״ש בארוכה."],["24","24","ראה לקו״ש ח״ג ע׳ 782. ועוד."],["25","25","נח ח, כב."],["26","26","ראה בארוכה עקידה שם."],["27","27","ראה ראב״ע שם. ס׳ השרשים לר׳ יונה בן ג׳נאח ולהרד״ק ע׳ שנה. •27) להעיר מכתר ש״ט ד„ענין הנס הוא שנתחדש הדבר בפעם הראשון על הטבע נק׳ נס ואח״כ נעשה זה טבע ג״כ“ (סי׳ קיט. סרנ״ו. מס׳ תולדות יי׳ פ׳ צו)."],["28","28","ראה ראב״ע שם. ס׳ השרשים הנ״ל ע׳ חדש."],["29","29","ראה גם סה״מ קונטרסים ח״א רכח, א. רד״ה החודש הש״ת."],["30","30","אף שעיקר ההדגשה בזה הוא „לחדשי השנה“ — מ״מ, מזה גופא שמוסיף תיבת „השנה“, מוכח, שכאן נוגע (גם) ענין ה„שנה“, ויתרה מזה — שהחדשים הם חלקי השנה. ולהעיר מלקו״ש ח״ט ע׳ 185."]]],[1300171164,"ולכאורה: ווי קומט אין דער בריאה (טבע) אן ענין פון „חודש“ — חידוש (נס)?\nמוז מען זאגן, אז כאטש בכללות איז תשרי פארבונדן מיט טבע (שנה) און ניסן מיט נס (חודש) — איז אבער דא א „התכללות“ צווישן זיי: אויך אין דער בריאה גופא (איידער „בחר ביעקב ובניו“) איז דא אן ענין פון נס (ר״ח³¹), און אזוי אויך לאידך גיסא: דער אויפטו פון „בחר ביעקב ובניו“ דריקט זיך אויס ניט נאר אין הנהגה נסית (חודש), נאר אויך אין (דעם שינוי וואס ווערט דורך־דעם אין) דער הנהגה טבעית (שנה).\nה. דאס צו פארשטיין, דארף מען פריער מבאר זיין דעם תוכן וכוונה פנימית אין די צוויי הנהגות — טבע און נס — וואס ביידע זיינען נויטיק צו אויספירן כוונת הבריאה און מגלה זיין גדולתו ית׳: נאר דער חילוק צווישן זיי איז:\nדער תכלית פון הנהגה נסית איז צו מגלה זיין דעם „בלי גבול“ פון אלקות — ווי דער אויבערשטער איז אינגאנצן העכער פון וועלט, און דאס ווערט דער־הערט אין וועלט דורכן ביטול פון איר מציאות — (דער נס איז) משדד די מערכות הטבע — וואס באווייזט ווי טבע איז ניט תופס מקום לגבי (דעם בלי גבול פון) אלקות.\nדער תכלית פון הנהגה טבעית איז צו מגלה זיין (ווי דער אויבערשטער איז זיך מתלבש אין וועלט אזוי) אז אויך די מציאות פון וועלט איז מיוחד מיטן אויבערשטן, אויך די חוקי הטבע זיינען א הנהגה אלקית.\nו. וויבאלד אז די וועלט איז באשאפן געווארן „בשביל התורה ובשביל ישראל“³², מוז מען זאגן, אז אלץ וואס איז דא אין דער בריאה איז אפהענגיק אין דער עבודה פון אידן.\nאון דערפון איז פארשטאנדיק, אז ניט נאר די הנהגה נסית, וואס איז פאר־בונדן מיט „בחר ביעקב ובניו“ איז תלוי אין עבודת ישראל — נאר אויך דער „בחר הקב״ה בעולמו“, די הנהגה טבעית, איז תלוי אין עבודת ישראל³³,\nנאר יעדע פון די הנהגות איז אפ־הענגיק אין דער עבודת האדם וואס איז דוגמתה³⁴ — וואס אופני עבודת ה׳ טיילן זיך, בכללות, אין צוויי סוגים:\nבא א אידן דארף זיין די תנועה פון קבלת עול און מסירת נפש — דינען דעם אויבערשטן ניט מצד זיין פאר־שטאנד און רגש כו׳, נאר פאלגן דעם רצון העליון מיט ביטול — ובמילא איז זיין עבודה ניט קיין געמאסטענע לויט די מדידות והגבלות פון זיין מציאות;",[["31","31","ולהעיר שבכו״כ דרושים (ומהם — שנסמנו לעיל הערה 23) מוסיף בהשאלה [דמאחר שבא׳ בתשרי הוא ר״ה, המשכת החיות לכל השנה, איך ניסן שבא אחריו חודש הראשון?] גם זה דר״ה כולל החיות דכל הי״ב ראשי חדשים, שהחיות דר״ה נתחלק אח״כ לי״ב כו׳ — שבזה מדגיש, שגם עתה * תשרי הוא ראש (לא רק לענין ה„שנה“, כ״א) גם לענין התחלקות דחדשים. *) לא רק לפני אמירת „החודש הזה גו׳“ — ראה ת״י מ״א ח, ב (וראה רד״ק שם). הובא ונת׳ באוה״ת בא ע׳ רסח. סה״מ קונטרסים שם. ד״ה החודש הש״ת פ״א, ודו׳."],["32","32","פרש״י ר״פ בראשית. ועוד."],["33","33","כמחז״ל (שבת פח, א. ע״ז ג, א) „אם ישראל מקבלים התורה אתם מתקיימין ואם לאו אני מחזיר אתכם לתוהו ובוהו“. ועיין ד״ה וירד תרס״ב. ועוד."],["34","34","להעיר מהמבואר בכתהאריז״ל (ראה סה״מ תש״ג ע׳ 168, וש״נ) דע״י העבודה דתומ״צ ממשיכים יחוד זו״נ (אור דסדר השתלשלות) וע״י העבודה דמס״נ — יחוד או״א (אור חדש מעצמות אוא״ס)."]]],[1300171165,"און דער אופן העבודה איז מעורר די הנהגה נסית, וואס טוט אויף דעם ביטול אין וועלט, כנ״ל.\nאבער לאידך דארף אויך די מציאות האדם („כל לבבך“ און „כל נפשך“) זיין דורכגענומען מיט עבודת ה׳ און דעריבער דארף ער מקיים זיין תומ״צ (ניט נאר מיט קבלת עול, נאר) אויך מיט פארשטאנד און געפיל וכו׳ — און אין דעם אופן העבודה איז אפהענגיק די הנהגה טבעית, וואס פאראייניקט די מציאות פון וועלט מיט אלקות, כנ״ל.\nז. דער תכלית הכוונה איז (דאך — אחדות, ובנדו״ד) אז עס זאל זיין דער איחוד פון נס און טבע:\nדאס וואס נס און טבע זיינען צוויי באזונדערע הנהגות, איז נאר מצד אורות וגילויים, וואס זיי שטעלן זיך אויס אין צוויי קווין — אין קו פון „בלי גבול“ וואס קומט אראפ אין הנהגה נסית, און אין קו פון „כחו בגבול“ — אין הנהגת הטבע;\nמצד יכולת העצמות אבער זיינען „בלי גבול“ און „גבול“ (ניט קיין צוויי קווין, נאר) איין ענין — דער אויסדרוק פון שלימותו — וכמאמר הידוע³⁵ „אם תאמר שיש לו כח בלי גבול ואין לו כח בגבול אתה מחסר שלימותו“, און (בפנימיות) דער אויסדרוק פון יכולתו ית׳³⁶. און דעריבער פירט זיך אויס די כוונת הבריאה פון עצמותו ית׳ אין דעם איחוד פון נס און טבע³⁷.\nאון אזוי אויך אין עבודת האדם: עס מאגט זיך פון א אידן דער איחוד פון די צוויי אופני עבודה [מסנ״פ וקב״ע שלמעלה מטעם ודעת און די עבודה מצד די כחות פנימיים]; און דאס ווערט אויפגעטאן דורך די התעוררות פון עצם הנשמה, וואס מצד דעם זיינען די ביידע אופני עבודה (ניט קיין הפכיים, נאר אדרבה —) בהתאחדות.\nח. וויבאלד אז בעצם ובשרשם זיינען נס און טבע איין ענין, איז פאר־שטאנדיק, אז אויך אראפקומענדיק אין השתלשלות אין וועלט (וואו בגילוי זעען זיי אויס ווי באזונדערע (הפכיות׳דיקע) הנהגות) זיינען זיי — בפנימיות — מיוחד³⁸.\nאון דאס דריקט זיך אויס אויך אין דעם, וואס אין טבע גופא איז אריינ־געגעבן געווארן די „תכונה“ פון למעלה מן הטבע (כדלקמן סעיף ט׳): און אזוי אויך לאידך — דער ענין הנס איז פאר־בונדן אויך מיט דער הנהגת הטבע (כדלקמן סי״א)³⁹.\nט. דער ביאור אין דעם: אין דער הכרה פון גדולתו ית׳ אין הנהגת הטבע זיינען דא צוויי אופנים:\nא) דורך התבוננות אין דער הנהגת הבריאה, הילוך המזלות וכו׳, קומט מען צו דער הכרה אז עס מוז זיין א בעה״ב לבירה זו וואס פירט אן מיט דער הנהגת הטבע; און ווי דער רמב״ם⁴⁰ שרייבט בנוגע צו אברהם אבינו: התחיל לשוטט בדעתו . . האיך אפשר שיהי׳ הגלגל הזה נוהג תמיד ולא יהי׳ לו מנהיג ומי יסבב אותו כי א״א שיסבב את עצמו כו׳.",[["35","35","עבודת הקודש ח״א רפ״ח."],["36","36","המשך תרצ״ה פ״ח (בסופו). שם פל״ד. וראה בכ״ז ס׳ הערכים־חב״ד (כרך ד׳) ע׳ אוא״ס (ד) סעיף ר׳, וש״נ."],["37","37","עיי״כ שער האמונה רפט״ז."],["38","38","ראה ס׳ הערכים שם סעיף ה׳, וש״נ."],["39","39","ועד״ז בעבודה יש התכללות זו — ע״ד משנ״ת בלקו״ש חט״ז (ע׳ 7־126) ההתכללות דגאולה העתידה בגאולת מצרים וגאולת מצרים בגאולה העתידה."],["40","40","הל׳ ע״ז פ״א ה״ג."]]],[1300171166,"ב) דורך התבוננות אין דעם „לא ישבותו“ — העדר השינוי פון דער הנהגת הטבע איז מען משיג ומכיר, אז אזא העדר השינוי קען ניט זיין מצד נבראים (וואס זיינען הווים ונפסדים ובעלי שינוי)⁴¹, און אפילו ניט, כביכול, פון דעם אור אלקי וואס איז מלובש אין (דער הגבלה פון) וועלט⁴² — נאר עס איז א כח הא״ס⁴³ וואס איז אריינ־געגעבן געווארן אין דער הנהגת הטבע.\nקומט אויס, אז אין טבע גופא איז דא דער „למעלה מן הטבע“⁴⁴ — דער „לא שניתי“ פון א״ס ב״ה.\nיו״ד. און דאס איז דער ביאור אין דעם מאמר חז״ל „משבחר הקב״ה בעולמו קבע בו ר״ח ושנים“: פון לשון חז״ל איז מובן, אז דא רעדט זיך ניט וועגן דעם מצב פון „עולמו“ מצד בריאת העולם, נאר ווען דער אויבערשטער איז בוחר⁴⁵ אין וועלט (ע״ד ווי „בחר ביעקב ובניו“), און מצד דער בחירה דוקא איז „קבע בו ר״ח ושנים“⁴⁵; א הוספה⁴⁶ אויף דעם וואס עס איז דא אין עולם מצד עצמו (מצד הבריאה).\nאיז ניט מובן: ווי־באלד אז דער ענין פון „ר״ח ושנים“ איז (ווי דער עקידה איז מסביר) דער סדר טבעי וואס דער אויבערשטער האט איינגעשטעלט אין בריאה, איז עס דאך א חלק פון דער בריאה גופא — היינט ווי קען מען זאגן אז דאס קומט דערפון וואס „בחר הקב״ה בעולמו“ (א העכערער עילוי ווי ס׳איז מצד הבריאה)?\nנאר דער ביאור אין דעם: מצד דעם ענין פון „בחר הקב״ה בעולמו“ — וואס בחירה אמיתית איז נאר אין עצמותו ית׳ כידוע⁴⁷ — איז טבע און העכער־פון־טבע איין ענין. און דערפאר איז אין טבע",[["41","41","ראה בארוכה ד״ה שאו מרום בהוספות לס׳ החקירה להצ״צ. ועוד."],["42","42","כי בגוף מוגבל א״א שיהי׳ מלובש בו כח (חיות) בלתי מוגבל (ס׳ האמונות והדעות מ״א פ״א. מו״נ ח״ב הקדמה יב — הובאו בס׳ החקירה להצ״צ בתחילתו). וראה ד״ה אמר רבא כל המעביר תש״י (פי״ז) שמאופן הקיום דצבא השמים אנו יודעים בחי׳ אור הסובב."],["43","43","ולהעיר מלשון העקידה שם (בתחילתו) „סדר המציאות לפי הטבע הנהוג יעיד על אמיתת מציאותו ית׳“. וי״ל הכוונה בזה: אמיתת שורש הנצחיות שבנבראים הוא רק מעצמותו ית׳* שלמעלה מכל ענין של אור וגילוי. כי כל אור וגילוי הוא בגדר שינוי עכ״פ (מאחר שמציאותו גופא נעשה ע״י שינוי — שבא מן המאור) ובמילא אא״פ לבוא ולהשתלשל מהם ענין של העדר השינוי; ורק מעצמותו ית׳ שלמעלה מכל ענין וגדר של שינוי — „אני ה׳ לא שניתי“ — אפ״ל נצחיות שבנבראים. וראה הערה הבאה. ולכן „סדר המציאות לפי הטבע**“ כו׳ יעיד על אמיתת מציאותו ית׳, דהיינו עצמותו ית׳, (עיין המשך תרס״ו ע׳ שמג. ע׳ תלא־ב. סד״ה יחיינו תרצ״ד (תשי״א). ועוד). *) ראה גם לקו״ש ח״ה ע׳ 97 שוה״ג להערה 19. **) משא״כ הנהגה נסית, שיש בה שינויים. ועיי״כ עקידה שם, דהנהגת הטבע שאין בה שינוי הוא „ע״י השפע המושפע מהשכלים העליונים . . (ש)הם קיימים בלתי משתנים“, משא״כ הנהגה נסית „יהי׳ להם כפי אלו השכלים האנושיים . . המחוייב להחליף ולהשתנות כמו שהם נמצאים משתנים“. ולהעיר ג״כ מאוה״ת ואתחנן (ע׳ שצה) בענין ההפרש דתורה (חיי עולם) ותפלה (חיי שעה), עיי״ש."],["44","44","וגם מזה מובן ששרש הנצחיות שבנבראים הוא מעצמותו ית׳ (כבהערה הקודמת) — כי החיבור דטבע ולמעלה מן הטבע, גבול ובל״ג, הוא רק בכח העצמות, שהוא (שו״ת הרשב״א ס׳ תיה. הובא בס׳ החקירה ע׳ 68) נמנע הנמנעות."],["45","45","עיין מאמרי חגה״ש תרע״א. ד״ה באתי לגני תרצ״ב (סה״מ קונט׳ ח״א רכז, ב ואילך)."],["46","46","ראה ג״כ אוה״ת בא ע׳ רסח. וראה גם לקו״ש ח״א ע׳ 234."],["47","47","עיין לקו״ת אמור לח, ב. המשך ר״ה תש״ג ספ״ט."]]],[1300171167,"גופא פאראן דער למעלה מן הטבע — די נצחיות פון „אני ה׳ לא שניתי“;\nאון דאס מיינט „משבחר הקב״ה בעולמו קבע בו ר״ח ושנים“: דאס איז דער נס (חודש) וואס איז דא אין דעם ענין פון טבע, וואס דריקט זיך אויס אין ענין ה„שנה“ (מלשון „משנה“, כנ״ל סעיף ב׳) — דער ענין פון העדר השינוי⁴⁸.\nיא. כשם ווי אין טבע גופא איז דא דער למעלה מן הטבע — אזוי איז עס אויך לאידך גיסא: די הנהגה נסית איז ניט „מוגבל“ אין דעם קו פון „נס“ וואס דריקט אויס דעם בל״ג פון אלקות, נאר אין אים איז אויך דא דער ענין וואס נס מאכט איבער טבע (אז טבע גופא זאל ווייזן אויף הנהגה אלקית).\nאון דערפאר איז אין נסים בכלל פאראן אויך דער סוג נסים וואס זיינען מלובש — אנגעטאן אין טבע, וואס אין זיי זיינען פאראן צוויי קצוות⁴⁹:\nדאס איז א נס (וואס איז העכער פון טבע) פונקט ווי די נסים וואס זיינען ניט מלובש אין טבע⁵⁰, און ווי דער פס״ד אז מען מאכט די זעלבע ברכה „שעשה נסים“ סיי בחנוכה (נס שאינו מלובש בטבע), סיי בפורים (נס מלובש בטבע⁵¹)\n(ואדרבה — חז״ל זאגן⁵² אז דוקא אויף די נסים המלובשים בטבע ווערט געזאגט⁵³ „עושה נפלאות לבדו“);\nאבער דער נס גופא (וואס איז אינ־גאנצן העכער פון טבע) קומט אראפ בהתלבשות אין (די דרכי ה)טבע, און טוט אויף אז די הנהגת הטבע גופא זאל זיך פירן „כרצונו דוקא כגרזן ביד החוצב כו׳“⁵⁴.\nד. ה. אין דער הנהגה נסית שלמעלה מן הטבע איז דא אויך די „תכונה“ פון „טבע“ — ווייל ניט נאר איז א נס מושל אויף טבע באופן אז ער איז משדד טבע, נאר דורכן נס ווערט טבע גופא „דער־הויבן“ ביז צו „למעלה מן הטבע“⁵⁵.\nוי״ל אז דאס איז דער טעם וואס ניסן איז ניט נאר „ראש חדשים“ נאר אויך „ראשון גו׳ לחדשי השנה“ — ווייל דער",[["48","48","ואולי י״ל „קבע בו ר״ח ושנים“ — היינו בחי׳ „שנה“ שלמעלה מבחי׳ „חדש“ — ראה ד״ה החודש תרנ״ד פ״ה ואילך (וראה גם אוה״ת שם ע׳ רעז), וש״נ."],["49","49","בהבא לקמן — עיין בארוכה שער האמונה פט״ו."],["50","50","ראה שער האמונה שם (ל, א): נס גמור הוא כו׳. ועיי״ש בסוף הפרק."],["51","51","תו״א מג״א צג, א. שם, סע״ג. ק, א. ובכ״מ. וצע״ק מאבודרהם ברכות הראי׳ [וראה שו״ע או״ח סר״ס ריח. אנציקלופדיא תלמודית ח״ד ע׳ שנה וש״נ]. וי״ל שהטעמים שבאבודרהם שפורים יוצא „ממנהג העולם“ מלובשים הם ואינם גלויים (כ״כ וע״ד מש״כ בתו״א (מג״א צג, רע״ד. ק, א) ש„נראה בחוש שכל הסבות היו רק למעלה מהטבע“."],["52","52","נדה לא, א."],["53","53","תהלים עב, יח."],["54","54","שער האמונה שם ל, סע״א."],["55","55","ולהעיר מסה״מ תרע״ח (ע׳ פט) דגם נסים שאינם מלובשים בטבע שבהם מתבטל הטבע, הנה „מה שמתבטל הוא רק באותו הדבר שבו הוא הנס, אבל כללות העולם הוא בקיומו, א״כ ה״ז שבעולם מאיר גילוי אוא״ס שלמעלה מהעולם“. וראה בארוכה ד״ה נתת ליראיך תשי״ב, שלכן עי״ז נעשה רוממות הטבע גופא (מכיון שגם בעת הנס כללות הטבע הוא בקיומו). וי״ל דזה שהנס („אוא״ס שלמעלה מהעולם“) מאיר בעולם וטבע, הוא [לא רק מפני הבל״ג שבו (שיכול להתפשט עד למטה מטה, גם בטבע ועולם), כ״א גם] מפני שגם בהבל״ג ונס כלול „טבע“ (וגבול *) כבפנים. ולכן המשכתו בעולם היא באופן שאינו משדד כללות הטבע רק „אותו הדבר שבו הוא הנס“, שעי״ז נעשה רוממות הטבע. *) להעיר ממאמרי חגה״ש תרע״ה (בהמשך תער״ב ח״ב ע׳ איד ואילך). חגה״ש תש״ד פ״ט ואילך."]]],[1300171168,"תכלית פון הנהגה נסית פון ניסן איז צו איבערמאכן די הנהגה טבעית (שנה)⁵⁶, אז אויך⁵⁷ אין טבע זאל זיך אנ־הערן אז עס ווערט געפירט פון ניסן — למעלה מן הטבע⁵⁸.\nיב. ע״פ כהנ״ל וועט מען אויך פאר־שטיין דעם קשר צווישן פ׳ החודש און פ׳ תזריע:\nדער חילוק צווישן „החודש“ און „תזריע“ איז ע״ד דער חילוק צווישן נס און טבע: „החודש“ וואס ווייזט אויף גילוי מלמעלה (כנ״ל סעיף א׳) איז העכער פון נבראים⁵⁹ — אזוי ווי ענין ה„נס“; „תזריע“ וואס ווייזט אויף עבודת המטה (כנ״ל שם) איז פארבונדן מיט מציאות האדם⁵⁹ — ע״ד ענין ה„טבע“⁶⁰.\nאון אז פ׳ החודש איז חל אין פ׳ תזריע⁶¹ — איז עס מדגיש און דער־מאנט אז זיי זיינען (בפנימיות) איין ענין;\nאון דאס וועט זיין בגילוי לעתיד לבוא, ווען ס׳וועט מקויים ווערן דער יעוד⁶² „איש ואיש יולד בה“: עס וועט",[["56","56","וחיבור זה ד„נס“ ו„טבע“ (— מה שתכלית הנס הוא להפוך הטבע) י״ל שנרמז בלשון חז״ל „כשבחר ביעקב ובניו קבע בו ר״ח של גאולה“ — שמלשון „כשבחר ביעקב ובניו“ מובן, שיש ב„יעקב ובניו“ ב׳ ענינים: א) כמו״ש מצ״ע, ב) מצד בחירתו ית׳ (ע״ד הנ״ל בפנים סעיף יוד). וי״ל הביאור: „יעקב ובניו“ הם בחי׳ בל״ג שלמעלה מהעולם [וי״ל שזהו הטעם שנקט הלשון „יעקב ובניו“ — ולא כמרוז״ל בבריאת העולם „בשביל ישראל“ — כי בזה („בניו“) מרמז לכח ההולדה שיש בישראל * שהוא כח הא״ס]: „בחר ביעקב ובניו“ הוא מצד עצמותו ית׳, שמצד בחירה זו נמצאים „יעקב ובניו“ למטה בעולם (חיבור דבל״ג וגבול) לעשות לו ית׳ דירה בתחתונים. ולכן „כשבחר ביעקב ובניו קבע בו ר״ח של גאולה“, ש„גאולה“ מורה שיש מצב של גלות שצריכים להיגאל ממנו."],["57","57","להעיר מפרש״י ברכות נז, רע״א ד״ה חנינא „נוניין הרבה נסים רבים“."],["58","58","ראה גם סה״מ קונטרסים ח״א רכה, ריש ע״ב. סד״ה החודש הש״ת."],["59","59","עפ״ז יש לבאר בדרך רמז המשך העניניים ברד״ה החודש תרס״ו — שלאחרי שמביא דברי העקידה ע״ד ב׳ ההנהגות כו׳ ממשיך „ולהבין בתוס׳ ביאור . . למה צריכים עבודה בכח עצמו דוקא ומהו המעלה בזה וכו׳“ — דלכאורה דורש ביאור: הרי מבואר בכו״כ דרושים המעלות בעבודה בכח עצמו, שדוקא היא בת קיימא (כנ״ל בתחילת השיחה) ועוד? — אלא שבדרוש „החודש גו׳“, שבו מודגשת מעלת ענין הנס הבא מלמעלה (אתעדל״ע), יש מקום לשאלה זו. ובזה יומתק מה שבלקו״ת ריש פרשתנו מסיק דפירוש הפילוסופים באשה מזרעת תחלה יולדת זכר — ש„טפת זכר באה באחרונה ועילאה גבר“ — „באמת הוא דוחק“ [אף שפשוט שגם פירוש זה יש לו מקום מכיון שהובא ע״י גדולי ישראל (כמשנ״ת בארוכה — לקו״ש חי״ב ע׳ 70 ואילך)] — — כי בפ׳ תזריע, שבה מודגשת מעלת העבודה (אתעדל״ת), נרגש שהענין ד„יולדת זכר“ הוא (לא מצד האיש — הקב״ה (עילאה גבר) — כ״א) מצד האשה, כנס״י."],["60","60","ולהעיר מלקו״ת ויקרא (ב, ריש ע״ד) שדוקא ע״י עבודה מלמטה נמשך בחי׳ „כי לא אדם הוא“, ונת׳ בארוכה (לקמן ע׳ 335 ואילך) שזהו טעם הפנימי (למ״ש שם לפנ״ז) שדוקא ע״י אתעדל״ת „יהי׳ דבר המתקיים“, כי עי״ז מגיעים לבחי׳ „אני ה׳ לא שניתי“ — ע״ד שנת״ל (הערה 43 ובשוה״ג הב׳) שדוקא בהנהגת הטבע ישנו הענין ד„אני ה׳ לא שניתי“."],["61","61","ולהעיר שברוב השנים קורין פ׳ החודש עוד בחודש אדר — שנקודתו, פורים, שענינו „קיימו מה שקבלו כבר“ (שבת פח, א), אתעדל״ת, דוגמת „אשה מזרעת תחלה“ (תו״א מג״א צט, ג)."],["62","62","תהלים פז, ה. תו״א סד״ה רני ושמחי (הב׳) וביאורו (בסופו). *) עיין לקו״ת שה״ש (לט, ד ואילך) שכח ההולדה שבישראל הוא מצד מעלת נשמתם. ומה שישנו כח זה גם בחי׳ וצומח — ראה לקו״ת שה״ש שם מ, א. בנוגע לאוה״ע — ראה לקו״ש חי״ח ע׳ 155 הערה 45, שי״ל בזה ב׳ טעמים: א) ע״ד המבואר בלקו״ת שם לענין חי וצומח. ב) כדי שיהי׳ ענין הבחירה."]]],[1300171169,"זיין „איש מזריע תחלה“ — די מעלה וואס איז דא אין „החודש“ וואס קומט מלמעלה (נס); און צוזאמען דערמיט וועט זיין „ואיש יולד בה“, „יולדת זכר“ — די מעלה וואס איז דא אין „תזריע“ (טבע) — אתערותא דלתתא.\n(משיחת ש״פ תזריע תשכ״ה, מאמרי ד״ה החודש תשל״א, תשל״ג)\n---"],[1300171170,"<h3>מצורע</h3>\nא. פון פסוק¹ „ולקח הכהן מדם האשם ונתן הכהן על תנוך אוזן המטהר וגו׳״ איז רש״י מעתיק דעם וואָרט „תנוך״ און איז מפרש „גדר אמצעי שבאוזן, ולשון תנוך לא נודע לי והפותרים קורים לו טנדרוס״².\nדאָרף מען פארשטיין: „תנוך״ איז טאקע ניט קיין לשון הרגיל בתורה³, אבער דער וואָרט שטייט שוין דאָך פריער אין חומש — אין פ׳ צו⁴ און פריער נאָך בפ׳ תצוה⁵; און נאכמער: אין פ׳ תצוה איז רש״י מפרש דעם וואָרט „תנוך, הוא הסחוס האמצעי⁶ שבתוך האוזן שקורין טנרוס״⁷ — היינט ויבאלד אז רש״י האט שוין פריער אפגעטייטשט דעם פירוש פון „תנוך״, פארוואס דארף ער עס דא איבער־חזר׳ן?",[["1","1","פרשתנו יד, יד."],["2","2","מפשטות לשון רש״י משמע שכוונתו להגדר שבאמצע האוזן בפני נקב האוזן כמ״ש בפרישה לטור יו״ד סי׳ שט סק״ז. ט״ז שם סק״ז. וכן מוכח מלשון רש״י בפ׳ תצוה (שהובא לקמן בפנים) „שבתוך האוזן״. ולפי״ז הוא דלא • כת״א כאן (יד, יז. כה. כח) „רום אודנא״ (וכן תרגם עה״פ בפ׳ תצוה ופ׳ צו דלקמן בפנים. ועד״ז הוא במכילתא דרשב״י משפטים כא, ו: בגבוה שבאוזן), כ״א כתיב״ע כאן (ופ׳ תצוה וצו שם) ••. ולהעיר משו״ת צ״צ חיו״ד סי׳ רכט (ראה שם מתויו״ט ולחם חמודות רפ״ז דבכורות) דמוכח מפרש״י בש״ס דגובה של אוזן נק׳ סחוס (הל׳ שהובא ברש״י גם בפ׳ תצוה שם), ומשמע גם מפרש״י (בכורות מ, ב) דעליונה של אוזן כולו נק׳ תנוך, ועפ״ז יש לפרש ל׳ „תנוך״ ו„גדר האמצעי שבאוזן״, גם לפי׳ הת״א עיי״ש בארוכה ••• — ולכאורה בפירוש המלה ובמציאות אין לחלק בין פירוש רש״י עה״ת לפרש״י על הש״ס. אבל י״ל דמכיון שמפורש במשנה (שם לז, א) לענין מום „מן החסחוס אבל לא מן העור״ (אלי׳ •) ולא כדעת הגאון (שהובא בראב״ע תצוה כט, כ) „הרך הדבק בעגול האוזן״. וברד״ק (בספר השרשים ע׳ תנך) הרך אשר בקצה האוזן. ועד״ז בש״ך עה״ת בפ׳ צו. וראה פי׳ זי״ר (הובא לקמן הערה 25). ••) עה״פ כאן (וכן בפסוק כה. כח דלקמן) תרגם: על גדירא מיצעא דאודנא. בפסוק יז: על חסחוס דאודנא. וכן תרגם בתצוה כט, כ. בצו ח, כג: על חסחוס אודנא דאהרן דהוא גדירא דמציעאה. ובפסוק כד שם: גדירא מיצעא. •••) ולהעיר ממדרש לקח טוב עה״פ כאן: זה גדר האמצעי הקרוב לגבוה של אוזן. ובמדרש הגדול תצוה שם: זה רום של אוזן שהוא גדר האמצעי. רכה של אוזן — פרש״י שם), משמע שחסחוס — „תנוך האוזן״ (פרש״י שם) כולל כל העליונה כהתויו״ט וכו׳. כי לשון חסחוס ותנוך אפשר לפרש גם על העליונה, אבל פי׳ „תנוך״ ו„סחוס״ מצ״ע לפרש״י הוא גדר האמצעי ממש כפרשה וט״ז שם. אבל לפ״ז צ״ל שמ״ש הט״ז שם הוא רק בפי׳ לשון תנוך (בפרש״י) ולהלכה ס״ל שנפגמה בחסרון מן התנוך (שבשו״ע שם) הוא כל העליונה (הקשה) של האוזן, שהרי מפרש סיום לשון השו״ע ולא העור שבשפת האוזן כפרש״י בכורות באלי׳ רכה — ע״ד מ״ש הרי״א האמליר (נדפס ב„יגדיל תורה״ נ.י. תשרי תשל״ח ע׳ לו. וראה שם ע׳ מב תשובת הרד״ל). אבל בשו״ת הצ״צ שם מוכח לא כן בט״ז. וראה לקמן הערה 13. 37. ואכ״מ."],["3","3","ראה ראב״ע תצוה שם „אין לו ריע״."],["4","4","ח, כג. כד."],["5","5","כט, כ."],["6","6","כ״ה בדפוס א׳ וב׳ ובכו״כ כת״י רש״י. ומזה משמע כנ״ל בתויו״ט וצ״צ שכל העליונה נק׳ „סחוס״. ובדפוסים אחדים „הוא הסחוס גדר האמצעי״."],["7","7","כ״ה ברוב הדפוסים ובדפוס ב׳. וכ״ה בפרשתנו בדפוס ב׳ (טנרוס), ובדפוס ראשון הוא כבפרשתנו „טינדרוס״. ויש גורסים בפרש״י תצוה ופרשתנו „טנדריך״. וכ״ה בפרש״י בכורות לז, א ד״ה הסחוס. וברע״ב שם „טנדריס״. וברגמ״ה בכורות שם כבפרשתנו „טנדרוס״."]]],[1300171171,"וממנ״פ: אויב עס איז דא א טעם פאר־וואס רש״י באנוגנט זיך ניט מיט זיין פירוש אין פ׳ תצוה און דארף עס איבער־חזר׳ן דא, ווען דער פסוק זאגט נאכאמאל דעם לשון „תנוך״, האט עס רש״י געדארפט איבער־חזר׳ן פריער אין פ׳ צו?\nב. לכאורה וואלט מען געקענט פארענטפערן אין פשטות: דארטן (אין פ׳ צו) באווארנט רש״י אין אנהויב⁸, אז „כל הענין הזה דפרשת המילואים פירשתי בואתה תצוה״, ובמילא דארף ער אויך ניט איבער־חזר׳ן דעם טייטש פון „תנוך״, ווייל ער איז שוין מפורש אין פ׳ תצוה וואו ס׳רעדט זיך וועגן זעלבן ענין; משא״כ אין אונזער פרשה וואו דער וואָרט ווערט געבראכט בשייכות צו אינגאנצן אן אנדער ענין.\nאבער עס איז נאָך אלץ ניט פאר־שטאנדיק, וואָרום פון לשון רש״י דא איז קלאר, אז ער איז ניט בלויז אויסן צו איבער־חזר׳ן דעם זעלבן פירוש פון „תנוך״ ווי אין פ׳ תצוה — ווייל\n[נוסף אויף די שוועריקייטן: א) פאר־וואס דארף רש״י איבערהויפט איבער־חזר׳ן דעם טייטש פון א וואָרט וואס ער האט שוין פריער אפגעטייטשט; ב) אפילו אויב יע איבער־חזר׳ן⁹ — וואלט געווען גענוג צו מפרש זיין בקיצור¹⁰ „גדר אמצעי שבאוזן״ (ע״ד ווי ביים וואָרט „בוהן״ שלאח״ז אין פסוק, וואס אין פ׳ תצוה איז ער מפרש „הגודל בפרק האמצעי״, משא״כ בפרשתנו זאגט ער בלויז „גודל״) — איז]\nאין זיין פירוש דא איז רש״י מוסיף און משנה לגבי זיין פירוש אין פ׳ תצוה, ער לייגט צו (א) „ולשון תנוך לא נודע לי״. (ב) „והפותרים קורים לו כו׳״ — מוז מען זאגן, אז רש״י מיינט דא צו מפרש זיין א נייעם ענין אין „תנוך״ וואס איז נוגע צו וויסן דוקא אין אונזער פרשה.\nג. אויך דארף מען פארשטיין:\nא) וואס מיינט רש״י מיט „לשון תנוך לא נודע לי״: אויב עס באציט זיך צו דעם וואס אינעם לשון „תנוך״ איז ניטא קיין משמעות אז דאס איז דער „גדר אמצעי שבאוזן״ — זיינען דאָך דא א סך נעמען אין חומש וואו ס׳איז ניטא קיין שייכות צווישן דעם וואָרט מיטן תוכן וואס דער וואָרט איז מתאר [און ווי מ׳זעט אין דעם פסוק גופא: ביים וואָרט „בוהן״, וואס רש״י טייטשט אז דאס מיינט „גודל״, און זאגט ניט „לשון בוהן לא נודע לי״, כאטש ער בריינגט ניט א שייכות צווישן „בוהן״ און „גודל״].\nב) פארוואס זאגט ער „לא נודע לי״ — א ביטוי בלתי רגיל אין רש״י — און ניט (ווי ער זאגט אין אנדערע ערטער) „לא ידעתי״ וכיו״ב?\nג) מיט „והפותרים קורים לו טנדרוס״ מיינט רש״י בפשטות¹¹ אז דאס איז דער „לעז״¹² פון „תנוך״ — האט דאָך רש״י",[["8","8","ח, ה."],["9","9","כיון שהוא לשון בלתי רגיל ויתכן ש(הבן חמש למקרא) לא יזכור מה שפירש בספר חומש שלפנ״ז."],["10","10","וכמו שמצינו כמ״פ בפירוש רש״י שחוזר ומפרש פירושו בקיצור פעם ב׳ מה שכבר פירש לפנ״ז (בחומש) באריכות יותר. וכ״ה בנדו״ד שבתחלת פירושו מקצר לגבי פי׳ בפ׳ תצוה שכתב שם „הוא הסחוס האמצעי שבתוך האוזן״. ובפרשתנו רק „גדר אמצעי שבאוזן״. אבל כאן בהמשך פירושו מוסיף ומשנה כדלקמן בפנים."],["11","11","בספר זכרון בפרש״י כאן „אומרו והפותרים קורין לו טינדרוס לא ידעתי אם היא ארמית או עברית ולכן לא נודע לי לשון תנוך לדעת הפותרים״."],["12","12","ברע״ב בכורות שם „בלעז״. וברגמ״ה שם „שלועזים טנדרוס״. וראה ס׳ השרשים לרד״ק שם."]]],[1300171172,"געדארפט זאגן (כדרכו בפירושו) „ובלעז קורין לו טנדרוס״ (אדער: טנדרוס בלעז)¹³.\n[וואָרום ס׳איז שווער צו זאגן, אז פונקט דער לעז פון דעם וואָרט האט רש״י בעצמו ניט געוואוסט און געמוזט אנקומען צו „פותרים״ אז זיי זאלן אפ־טייטשן דעם וואָרט אויף „לעז״].\nד) אפילו אויב מ׳זאל געפינען א הסברה פארוואס רש״י זאגט ניט דעם לשון „בלעז״¹⁴, איז נאָך אלץ ניט מובן וואס ער נוצט דוקא אזא ניט געוויינ־לעכן תואר — „והפותרים״¹⁵ — און ניט (א לשון הרגיל) „והמפרשים״, „והמחב־רים״ וכיו״ב (ע״ד •¹⁵ לשון רש״י: מנחם בן סרוק פרשו, חברו כו׳).\nד. דער ביאור בכל זה:\nדאס וואס רש״י זאגט דא „ולשון תנוך לא נודע לי״ מיינט ער דערמיט (אז ע״פ פשוטו של מקרא — וואס דאס איז דרכו פון פרש״י בתורה, דארף מען) שולל זיין דעם פירוש פון תו״כ דא אויפן אָרט, לויט וועלכן ס׳איז מובן די שייכות צווישן „תנוך״ און „גדר אמצעי״ (כדלקמן סעיף ה׳); וויבאלד אז דער ביאור פון תו״כ איז ניט ע״פ פשוטו של מקרא, דעריבער איז עס רש״י שולל דורכן זאגן „ולשון תנוך לא נודע לי״.\nאון דאס וואס רש״י דארף שולל זיין דעם פירוש פון תו״כ (הגם אז בכלל איז ער ניט שולל פירושים, נאר גלייך מפרש לפי פשש״מ, ניט קוקנדיק ווי דער פירוש איז אין חלק ההלכה וכו׳ פון תורה) — וואָרום היות אז כמה וכמה פירושי רש״י אין אונזער פרשה (און אין ספר ויקרא בכלל) זיינען גענומען פון תורת כהנים, ווי רש״י אליין צייכנט אן ביי א צאל פון זיי; און נאכמער — אין פריערדיקן פסוק ברענגט רש״י די התחלה פון א פירוש פון תו״כ און זאגט „וכו׳ בתורת כהנים״¹⁶, אז מ׳זאל מעיין זיין אין תו״כ דעם המשך הפירוש —",[["13","13","זה שכתב רש״י „קורין לו״ (וכן בפ׳ תצוה: שקורין טנרוס) ולא כתב טנדרוס בלעז, כדרכו בכ״מ — לכאורה אפשר לומר שהוא בכדי שנדע בדיוק מקומו באוזן כי בלשון „הסחוס״ מצ״ע וגם בלשון „(גדר) אמצעי שבאוזן״ אפשר לפרש שכולל כל חלק הקשה שבאוזן • כפי התויו״ט והצ״צ בפירוש רש״י על הש״ס (כנ״ל הערה 2, 6). אבל (נוסף על הנ״ל בהערה 2 הרי): א) גם במשנה בש״ס בכורות לז, א ד״ה הסחוס (שבו מפרשים דעת רש״י כנ״ל) כתב „שקורין טנדריך״. ב) בפרש״י תצוה מפורש (לכל הדפוסים) „שבתוך האוזן״ ואין מקום לטעות. ולהעיר מלשון אדה״ז בשו״ע סוף הל׳ מכירת חמץ שלאחרי הל׳ פסח. ואכ״מ. וראה לקמן הערה 37."],["14","14","ראה גם פרש״י בראשית א, כז. נח יא, ג. ויצא ל, לז. ועוד. וראה הערה 11. ובתחלת הערה שלפנ״ז. •) לכאורה משמע כן גם בפיה״מ להרמב״ם נגעים פי״ד מ״ט (וראה פיה״מ הוצאת הרב קאפאח). ועמ״ש בצ״צ פי׳ „גדר אמצעי שבאוזן״ י״ל שכן ס״ל להרמב״ם גם בפי״ז מהל׳ ביאת המקדש ה״ב, ובריש פ״ה מהל׳ מחוסרי כפרה. ולא כמש״כ בתויו״ט בכורות שם. ועפ״ז מתורצת קושייתו על הכס״מ בהל׳ ביאת מקדש שם (ועד״ז כתב בשו״ת מלבושי יו״ט יו״ד, סי׳ יד). אבל כנראה שהצ״צ ס״ל כדעת התויו״ט בהרמב״ם. וכדמוכח גם מזה שהשואל להצ״צ (נדפס ב„יגדיל תורה״ (הנ״ל הערה 2) ע׳ כו ואילך. וראה שם ע׳ מב) כתב ע״ד הנ״ל בדברי הרמב״ם, והצ״צ תפס דברי התויו״ט ולחם חמודות."],["15","15","הלשון „פתרון״ וכיו״ב נמצא כבר בפרש״י לפנ״ז, ראה לדוגמא: בא יוד, כא. יתרו כ, ח. משפטים כא, יג. שם כג, ב. תרומה כה, יב. שם, מ. שם כז, ד. אבל ברוב מהנ״ל פי׳ „פתרון״ היינו פירוש וביאור המקרא או התיבה שאינו מפורש בכתוב, משא״כ בנדו״ד. •15) לך טו, ב. ויצא ל, ח. שם, מא. ובכ״מ."],["16","16","ובדפוס ב׳ „כדאיתא בתו״כ״."]]],[1300171173,"קען דאָך זיין אז ווען מ׳וועט זען אז רש״י׳ס פירוש דא „גדר אמצעי שבאוזן״ איז פון תו״כ וועט מען דעריבער מיינען אז רש״י נעמט אויך אן דעם הסבר פון תו״כ (אין דער שייכות צווישן „תנוך״ און „גדר אמצעי״) — דעריבער באר־וואָרנט גלייך רש״י אז „ולשון תנוך לא נודע לי״.\nועפ״ז פאלן אַפ בדרך ממילא די צוויי קושיות [(א) דער סגנון פון רש״י „ולשון תנוך לא נודע לי״, (ב) וואס רש״י זאגט עס ניט אין פ׳ תצוה]:\nרש״י קען ניט זאגן „ולשון תנוך לא ידעתי״ — ווייל ער ווייס דאָך יא פון א פירוש אין „לשון תנוך״ (דער פירוש פון תו״כ); נאר דער פירוש איז „לא נודע״: ער איז ניט אנערקענט¹⁷ — ניט אויסגעהאלטן „לי״ — וואס לא באתי לפרש אלא פשוטו של מקרא¹⁸.\nאון דעריבער ברענגט עס אראפ רש״י נאר דא אין אונזער פרשה און ניט אין פ׳ תצוה, ווייל (נוסף אויף דעם וואס בכלל איז ניט ענינו של רש״י צו שולל זיין פירושים, כולל אויך פירושי רז״ל פון חלק ההלכה שבתורה (משא״כ אין אונזער פרשה כנ״ל) — איז) אין דברי רז״ל אויפן פסוק אין פ׳ תצוה געפינט מען ניט קיין ביאור אין מכילתא וכו׳ פון „לשון תנוך״¹⁹.\nה. אין תו״כ שטייט דאָ: „יכול על תוך ודאי ת״ל על נוך אי על נוך יכול על גובה של אוזן²⁰ ת״ל תוך נוך הא כיצד זה גדר האמצעי״.\nטייטשן מפרשים²¹, אז דער תו״כ מיינט צו זאגן, אז „תנוך״ איז ניט סתם א נאמען פונעם „גדר האמצעי״ — נאר עס איז: א) פון לשון „תוך״ — אינע־ווייניק; און דאס וואס עס שטייט אויך א „נון״, איז עס ווי א סך אנדערע ווערטער אין לשון הקודש, וואס שטייען אמאל מיט א נון און אמאל אן א נון²². ב) פון לשון „נך״ — „חומת אנך״²³ — וואס האט דעם באדייט פון רום²⁴ וגובה²⁵;\nאון דאס וואס דא שטייט ניט דער אל״ף, און דארט שטייט ניט דער תי״ו, געפינט מען, כנ״ל, עד״ז אין אנדערע ווערטער בלשון קודש.",[["17","17","ע״ד ולא נודע כי באו אל קרבנה (מקץ מא, כא)."],["18","18","והא דבכמה מקומות כותב רש״י „לא ידעתי״ וכיו״ב. אף שגם שם יש מדרשי רז״ל — ראה לקו״ש ח״ה ע׳ 1 הערה 2 וש״נ — הוא לפי: א) שבכלל אין דרך פרש״י לשלול דרז״ל, כדלקמן בפנים. ב) גם בדרז״ל על אתר כתו״כ וכיו״ב אינו צריך לשלול באם מובנת השלילה בפשטות (כי אינו ע״ד הפשט כלל)."],["19","19","וגם בפ׳ צו (שם ח, כג־כד) אף שמפרש בתו״כ שם „זה גדר האמצעי״ אינו מפרש השייכות לתיבת „תנוך״ כבפרשתנו."],["20","20","כ״ה בתו״כ הנדפסים עם פי׳ הקרבן אהרן; עם פי׳ רבינו הלל; עם פי׳ המלבי״ם. וכן הובא בר״ש ותויו״ט נגעים פי״ד מ״ט. וכ״ה בתו״כ ע״פ כת״י רומי מנוקד (יכול על תוך ודאי). אבל בתו״כ הנדפס עם פי׳ הראב״ד: ת״ל על תנוך אי על תנוך יכול על גובה. ובזית רענן גרס (בילקוט): על תנוך ודאי כו׳ ת״ל אוזן אי על אוזן וכו׳. וכן הועתק בפי׳ רבינו הלל: יכול על תנוך ודאי. וראה שם בחילופי נוסחאות בפי׳ ר״ה."],["21","21","ראה מלבי״ם כאן. וראה ראב״ד וקרבן אהרן בפירושם לתו״כ. תויו״ט נגעים פי״ד מ״ט."],["22","22","כמו האנפה — ראה לקמן בפנים."],["23","23","עמוס ז, ז."],["24","24","ראה לעיל הערה 2 שכן תרגם אונקלוס תיבת תנוך „רום אודנא״."],["25","25","וצ״ע במ״ש בקרבן אהרן כאן „לא ידעתי פי׳ מלת נוך האיך מורה על החצוף״. ובראב״ד לתו״כ כאן „ושמא מוציא אותו מלשון נאספו עלי נכים שפירושו אנשים קשים מאד וכן הגבוה של האוזן הוא הקשה שבאוזן״. ובפי׳ זית רענן לילקוט שם פי׳ „על תנוך ודאי״: פי׳ הרכה שהוא למטה באוזן. ובפי׳ רבינו הלל: דהיינו מקום תחתון שבאוזן דמשמע תחת נוך. וראה שם בחילופי נוסחאות."]]],[1300171174,"— מען געפינט בא מערערע ווערטער בתנ״ך, אז מען שטעלט צו צום שרש אן אל״ף אדער א תי״ו און עס איז א נאמען פון א זאך, ווי צום ביישפיל טאקע בא אנך (לויט פרש״י²⁶), „ובתבונה״ ופרש״י „מבין דבר כו׳״²⁷ ועוד ועוד.\nאון וויבאלד אז „תנוך״ האט ביידע טייטשן — „תוך״ און „נוך״ — קומט אויס, אז מיט דעם איז דער פסוק מכוון צום „גדר אמצעי״²⁸.\nאון כדי מען זאל ניט אננעמען אז דער פירוש איז אויך אויסגעהאלטן אין דרך הפשט\n— ובפרט אז מען האט שוין פריער געלערנט אין פירוש רש״י²⁹ אז „האנפה, היא די׳ רגזנית״, ד.ה. אז „אנפה״ (מיט א נון) איז לשון כעס ורוגז, אזוי ווי „אף״ לשון רוגז\nדאס הייסט, אז אויך לויט הפי׳ ע״פ פשש״מ פון רש״י איז דא ווערטער וואס שטייען אמאל מיט און אמאל א געוויסן אות (נון) —\nדעריבער זאגט רש״י „ולשון תנוך לא נודע לי״, שולל זיין דעם פירוש, כנ״ל.\nו. דער טעם וואס רש״י נעמט ניט אן דעם פירוש: רש״י האלט אז א וואָרט וואס שטייט מיט א נון און אן א נון האט יעדער פון זיי, ע״פ פשש״מ, אן אנדער טייטש³⁰.\nדער הכרח אויף דעם: אויף „וברוח אפיך״³¹ איז רש״י מפרש „היוצא משני נחירים של אף דבר הכתוב כביכול בשכינה דוגמת מלך ב״ו כדי להשמיע אוזן הבריות כפי ההוה שיוכלו להבין דבר כשאדם כועס יוצא רוח מנחיריו וכן עלה עשן באפו וכן ומרוח אפו יכלו וזהו שאמר למען שמי אאריך אפי כשזעפו נחה נשימתו ארוכה וכשהוא כועס נשימתו קצרה וכו׳ וכל אף וחרון שבמקרא אני אומר כן כו׳״³².",[["","","ו״נוך״. ולפי״ז לפי׳ „תוך״ אינם משתמשים בהנון •. ולהעיר שכמה סוגים בפי׳ כאלה: א) בנדו״ד שתיבה אחת מורכבת מב׳ תיבות ופי׳ תיבה זו יוצא מב׳ התיבות: ב) „אפאיהם״ (האזינו לב, כו) וכיו״ב שרש״י כותב: ואונקלוס תרגם כו׳ תיבה זו לג׳ תיבות אמרתי אף אי הם — שכל האותיות ישנם בהתיבה והפי׳ רק מפרידם לג׳ תיבות, משא״כ בנדו״ד שה„וך״ משמש לב׳ התיבות (תוך נוך). ג) „שמים״ שפרש״י (בראשית א, ח) „שא מים . . אש ומים שערבן כו׳״ — שעיקר ההוספה היא אות אל״ף, „שא מים אש ומים״, ש„יש לנו תיבות הרבה חסרות אל״ף לפי שאין הברת האל״ף נכרת״ (פרש״י בא י, כא). וראה מפרשי רש״י שם (רא״ם, לבוש, דקדוקי רש״י, משכיל לדוד. ועוד). ד) פרש״י שם „שם מים״ — דמפרשים המ׳ לפניו וגם לאחריו (וראה משכיל לדוד שם) ••, משא״כ בנדו״ד שמפרשים התיבות „וך״ ששייכות (גם) לה„תיו״ אף שהנון מפסיק. ועוד."],["31","31","בשלח טו, ח."],["32","32","וראה פרש״י וירא יח, כג."],["26","26","ח״ש כה, ג."],["27","27","תשא לא, ג."],["28","28","וכ״ה בת״י דלעיל הערה 2."],["29","29","שמיני יא, יט."],["30","30","מפירוש הראב״ד וקרבן אהרן ותויו״ט ועוד (וכ״ה במלבי״ם) שם משמע שמפרשים שלדעת התו״כ תיבת „תנוך״ היא מלה מורכבת מ„תוך״ •) ועפ״ז צ״ע במלבי״ם שם שמפרש שבהוראה זו „תוך״. הנון שבאמצע להקטין התוך כו׳ — דלכאורה לפי׳ תיבת „תוך״ שבהתיבה, הוא רק „תוך״, אשר לכן הוצרך לצרף ב׳ התיבות בתו״כ. ••) בספר זכרון לרש״י שם כתב דהנוסחאות שכתוב בהם שם מים במ״ם נ״ל שאינן נכונות (כי הוא דעת ר״י ב״ח כו׳). וליתא ברש״י כת״י ה״א קלא. קמה (הר טולוז). ובדפוס שני איתא רק „שמים אש ומים שערבן כו׳״. אבל ברוב הדפוסים ומפרשי רש״י איתא. וכן משמע ברמב״ן כאן."]]],[1300171175,"מזה משמע, אז כאטש „אף״ קען האבן דעם טייטש פון רוגז וכעס, ווי אנפה, איז דאס גלאטיק דאן ווען עס שטייט דערביי „רוח״, „עשן״, „אאריך״ (נשימותי³²•) וכיו״ב, אבער דער וואָרט „אף״ פאר זיך מיינט (ניט כעס ורוגז, נאר) דער אבר האף כפשוטו (נאז)³³.\nאון דערפאר איז ניט גלאטיק אנ־נעמען אין פשש״מ אז „תנוך״ איז לשון „תוך״.\nרש״י קען ניט אננעמען אז „תנוך״ איז פון לשון „נוך״ — רום וגובה ווי „חומת אנך״ (נוסף אויף דעם שינוי פון א ת, כנ״ל) — ווייל דער לשון „אנך״ גופא מיינט ניט לשון „רום״, נאר דאס איז א „בדיל״ צו מעסטן די גלייכקייט פון א חומה³⁴, און די שייכות פון דעם „בדיל״ צו „גובה״ ו„רום״ איז בלויז אין דעם וואס מען לייגט דעם „בדיל״ אויף דעם גובה החומה³⁵;\nאון דעריבער איז ניט גלאטיק צו זאגן אז דער טייטש פון „על תנוך״ איז „על גובה״ — דערפאר וואס דער וואָרט „תנוך״ איז ענלעך צו תיבת „אנך״ —\nווייל „אנך״ גופא מיינט ניט „גובה״ [ובפרט נאך אז אותיות „תנוך״ איז ניט בדומה³⁶ צו אותיות „אנך״ כנ״ל]³⁷.\nז. ע״פ כהנ״ל איז אויך פארשטאנ־דיק וואס רש״י זאגט דא „והפותרים קורים לו טנדרוס״ (ניט ווי אין פ׳ תצוה וואו ער זאגט „שקורין טנרוס״):\nדער ענין פון „פותרים״ איז ע״ד ווי דער ענין פון פתרון החלום — ווי מען האט געלערנט פריער (אין חומש בראשית) אז דער שר המשקים, האט",[["","","32•) שהרי אי אפשר להאריך האף עצמו."],["33","33","בפרש״י לך (יז, יא) „ונמלתם כמו ומלתם והנון בו יתירה ליסוד הנופל בו לפרקים כגון נ׳ של נושך ונ׳ של נושא כו׳״ — ה״ז נון יתירה כיסוד נופל בתחלת התיבה, ולא באמצע התיבה. ומזה שלא פירש רש״י בבשלח שם שאף הוא משרש אנף (כהרד״ק בספר השרשים שלו) מוכח שלא ס״ל כן. ועד״ז מובן בנדו״ד."],["34","34","ראה פרש״י ומצודות (ועוד) עמוס שם."],["35","35","ובפרט לפרש״י ח״ש (שם) (אבל הוא בחצאי רבוע) שכתב „חומת אנך שהוא מן נכה רגלים״. וראה ראב״ד לתו״כ פ׳ צו שם. •) וגם שם י״ל שהכרחו הוא כיון שהוא לשון ציווי ונפעל לא יבוא בציווי (וראה דקדוקי רש״י (מירא דכיא) שם)."],["36","36","בפרש״י ח״ש שם שבתיבת אנך האל״ף היא הוספה, ובפרש״י שמות ג, ב שלפעמים מוסיפים תי״ו. ועפ״ז י״ל לכאורה בתיבת „תנוך״ שיש בזה השורש „נכה״ שבאנך. אבל (נוסף ע״ז שמצד פרש״י ח״ש שם אין לפרש כבתו״כ — נוך, גובה •, כבהערה שלפנ״ז, הרי) הוספת התי״ו המבואר ברש״י שמות שם היא להורות על ענין הדביקות — ראה דקדוקי רש״י (באר רחובות) — שאינו שייך בנדו״ד."],["37","37","ע״פ פי׳ הצ״צ (הנ״ל הערה 2) בגדר האמצעי שבאוזן — אולי י״ל מענינים מופלאים ע״ד ההלכה בפרש״י עה״ת: שזה שמוסיף „ולשון תנוך לא נודע לי״ כוונתו לא רק לשלול הפי׳ שבתו״כ, בפי׳ לשון „תנוך״ כ״א שנפק״מ גם להלכה: הלשון „גדר אמצעי שבאוזן״ מצ״ע יש לפרש שקאי על כל העליונה של אוזן שקשה כ„סחוס״ ו„נק׳ גדר האמצעי כיון שיש לו דבר מקיף למטה בחלק גדול מן האוזן ועוד דגם שם בעליונית האוזן יש קצת עור רך קצת ע״ג הקשה״ (צ״צ שם. וראה לעיל שוה״ג בהערה 13 שגם ברמב״ם בפיה״מ משמע כן וגם שם מפרש „והוא אמרם תנוך אוזן זה גדר האמצעי״), משא״כ לפי׳ התו״כ בתיבת „תנוך״ — „תוך״, „נוך״ — מוכרח לומר שהוא גדר האמצעי בפני נקב האוזן כפי׳ הראב״ד לתו״כ. וק״א שם •. •) אלא שי״ל שע״פ פרש״י נוך הוא כמו נכה, וגם מצד זה שייך לגדר האמצעי שבאוזן, ע״ד פי׳ הב׳ בראב״ד לתו״כ צו שם. •) כ״כ בצ״צ שם בפי׳ הק״א. ובשו״ת מלבושי יו״ט שם תפס באו״א בק״א ומפרש דברי התו״כ ע״ד הנ״ל ברש״י. וצע״ג."]]],[1300171176,"געזען אין חלום „שלשה שריגים״ און יוסף האט אים פותר געווען אז דאס מיינט „שלשת ימים״³⁸. און עד״ז ביי חלום פרעה וועגן די „שבע פרות גו׳״ וואס יוסף האט פותר געווען אז דאס מיינט „שבע שנים״³⁹. ד.ה. אז פתרון באשטייט אין דעם, אז כאטש אין חלום האבן זיי ניט געזען קיין „ימים״ אדער „שנים״, האט יוסף זיי פותר געווען — אויפגעדעקט און אנגעוויזן אויף דעם מכוון פון דעם חלום — די ג׳ ימים און ז׳ שנים. ד.ה. אז „פותרים״ געפינען דעם צד השווה פון צוויי זאכן וואס זיינען ניט גלייך.\nאון דעריבער, נאך דעם וואס רש״י זאגט „ולשון תנוך לא נודע לי״ — אז אין פשוטו של מקרא איז ניט מתאים דער פארגלייך פון „תנוך״ צו „תוך״ און „נוך״ — איז ער אבער ממשיך, אז „והפותרים קורים לו טנדרוס״:\nדי וואס זיינען „פותר״ און גלייכן צו לשונות⁴⁰ (וואס לויט זייער דרך הפירוש איז דא א הסברה אויף „לשון תנוך״, מצד דעם דמיון פון „תנוך״ צו „תוך״ און „נוך״), זאגן זיי, אז דאס איז אויך דער טעם וואס דער „לעז״ פון „תנוך״ איז „טנדרוס״, ווייל ביידע ווערטער האבן א „דמיון״ אין הברה — „טנדרוס״ האט (די הברה פון) א תיו, נון און ואו (עד״ז ווי אין „תנוך״) — און דעריבער איז דער „פתרון״ פון וואָרט „תנוך״ אין „לעז״ — „טנדרוס״.\nח. לכאורה: ווי קען זיין אין פשוטו של מקרא אזא זאך, אז א וואָרט אויף „לעז״ אין די צייטן פון רש״י זאל זיין פון דעם זעלבן שורש פון א לשון־קודש וואָרט אין חומש?!\nאיז יתירה מזו געפינט מען אין פירוש רש״י (אין פרשת דברים⁴¹): אויף „צידונים יקראו לחרמון שריון והאמורי יקראו לו שניר״ זאגט רש״י „הוא שלג בלשון אשכנז ובלשון כנען״. ד.ה. אז דער נאמען פון „שלג״ אין לשון אשכנז און אין לשון כנען בזמן רש״י איז פון זעלבן אויסשפראך ווי די „אמוריים״ וואס „יקראו לו שניר״ — א לשון אין חומש.\n[ולהעיר: אויך איצט ווערט „שלג״ אנגערופן אין לשון אשכנז (און אזוי אויך אין ענגליש) בדומה צו „שניר״ — „שניי״, „סנאו״]⁴².\nועד״ז איז דער וואָרט „טנדרוס״ בימי רש״י פון שורש „תנוך״ וואס שטייט אין חומש.\nט. מיינה של תורה שבפרש״י:\nס׳איז מבואר אין קבלה⁴³ אז די סיבה פון נגעים איז מצד „הסתלקות אור החכמה, כי מצורע חשוב כמת וכתיב ימותו ולא בחכמה״. און חסידות⁴⁴ איז דאס מבאר בארוכה ווי דאס איז אין עבודת האדם: מוחין דאימא — בחי׳ בינה, התבוננות אין גדלות הבורא, איז מעורר בא דעם מענטשן אן אהבה בבחי׳",[["38","38","וישב מ, יב."],["39","39","מקץ מא, כו."],["40","40","עפ״ז יובן גם ל׳ רש״י בתצוה כח, כב: ואף שרשרות פתר מנחם כו׳ לשון שרשים ואמר שהרי״ש כו׳."],["41","41","ג, ט."],["42","42","ויתירה מזו י״ל, שכולם באים משורש „שלג״ שבלה״ק, ואי״כ הרי״ז כנדו״ד."],["43","43","ע״ח שלי״ח פ״ז. הובא בלקו״ת ריש פרשתנו •. ועוד."],["44","44","לקו״ת פרשתנו שם. סהמ״צ להצ״צ מצות טומאת המצורע. ובכ״מ. •) בלקו״ת שם: שלי״ז (ע״פ דפוס שקלאב, תקס)."]]],[1300171177,"רצוא, ארויסצוגיין פון זיין מציאות און (וועלן) נכלל ווערן אין אלקות.\nמוחין דאבא, פון חכמה, וואס איז העכער פון בינה, בריינגט ביטול לאלקות בתכלית, און דאס קומט אין דער תנועה פון „שוב״, ניט אין כלות הנפש, נאר אין דעם ביטול אין עסק התורה און מעשה המצות למטה.\n„נגעים״ ווערן מצד „הסתלקות אור החכמה״: בשעת עס פעלט דער תכלית שלימות הביטול פון חכמה (און דורך־דעם פעלט דער אראפטראגן זיין רצוא און כלות הנפש אין „שוב״ — לימוד התורה און קיום המצות), דעמאלט (ווען ס׳איז דא נאר די התבוננות מצד מוחין דאימא) קען דער רצוא געבן אן ארט פאר א יניקה לחיצונים (ע״ד ווי פון דער התלהבות אין תפלה אליין קען נאכדעם ארויסקומען א הרגש פון ישות וכו׳ ביז א התלהבות בלתי רצוי׳⁴⁵).\nדעריבער איז דער תיקון פון די נגעים און זייער רפואה דורך א כהן, וואס כהן איז ממשיך דעם אור החכמה, און מצד דעם ווערט די טהרה פון די נגעים — עס איז דוחה די יניקת החיצונים (ווי ס׳איז מבואר בארוכה אין חסידות).\nיוד. אין דער טהרה דורך דעם כהן זיינען פאראן צוויי פרטים⁴⁶: „והובא אל הכהן״ און „ויצא הכהן אל מחוץ למחנה״. כדי צו מתקן זיין ענין הנגעים איז ניט גענוג די המשכת אור החכמה כשלעצמה („ויצא הכהן גו׳״), נאר עס מוז (פריער) זיין דער „והובא אל הכהן״ — דער תיקון אין דעם (ארט⁴⁷ פון די\nנגעים — אין דעם) רצוא און כלות הנפש וואס ווערט מצד מוחין דאימא (בינה), אז עס זאל זיין מתאים צום ענין ה„שוב״ (וואס קומט מצד בחי׳ כהן — חכמה); און צוזאמען מיט (— נאכן אויפטאן) דעם תיקון אין דעם „רצוא״, קען (דערנאך) זיין „ויצא הכהן גו׳״ — די המשכת אור החכמה אין „מוחין דאימא״, וואס איז מבטל די אפשריות פון נגעים.\nאון די צוויי פרטים אין דער טהרה זיינען מרומז אין דעם פסוק און אין פרש״י: „ונתן הכהן על תנוך אוזן המטהר הימנית גו׳״ ווייזט אויף דער המשכת אור החכמה („ונתן הכהן״) אין מוחין דאימא — „אוזן״ — „שמיעה״ והתבוננות⁴⁸.\nאון אויף דעם זאגט רש״י „ולשון תנוך לא נודע לי״ — די טהרה און תיקון אין „תנוך אוזן״, אין מוחין דאימא, איז „לא נודע״⁴⁹, קומט ניט פון זיך אליין דורך דער המשכה פון מוחין דאבא (דורכן כהן)\n[רש״י זאגט דעם לשון „לא נודע״ — לשון נפעל „ידיעה״ ופעולה וואס איז מאליו וממילא — און ניט „לא ידעתי״ וכיו״ב]",[["45","45","לקו״ת שם. ע״ד פלשתים דקדושה וכו׳ (תו״א סא, ג ואילך. תו״ח ר״פ תולדות פ״ז)."],["46","46","לקו״ת פרשתנו כה, א ואילך."],["47","47","להעיר ש„והובא״ צ״ל למקום שמותר לבוא לשם (מקומו — אלא שבמקומו גופא הקרוב למקום הכהן — ספורנו עה״פ), או שההבאה היא בנפשו שלא להשהות (תו״כ עה״פ)."],["48","48","ראה מאו״א בערכו (וש״נ): אוזן נק׳ בינה כו׳. וראה סהמ״צ שם (ק, סע״ב) במוחין דאימא-בינה הוא השגה והתבוננות והיא כמו בחי׳ שמיעה שמשיג הדבר. ולהעיר ע״ד הנ״ל (בפנים) מתורת לוי״צ הערות למס׳ נגעים ע׳ שנט ואילך."],["49","49","ע״ד הפי׳ לא ידעתי נפשי (ראה מק״מ ר״פ צו) ע״ס כו׳ לא ידענו (לקו״ת חקת סד, א) איני יודע באיזו דרך כו׳ (ברכות כה, ב) מצד פנימיות הנפש שלמעלה מידיעה (אוה״ת פנחס ע׳ א׳נט ואילך. ד״ה אך בגורל תרכ״ו. ד״ה אשרינו תרפ״ח, תרצ״ו. וראה לקו״ת ויקרא ג, סע״ד)."]]],[1300171178,"נאָר עס דארף זיין (פריער) דער תיקון אין דעם פגם פון מוחין דאימא — אין בינה עצמה (ע״ד ווי תשובה דארף זיין באותו מקום⁵⁰).\nאון דער תיקון אין מוחין דאימא איז נרמז אין לשון „והפותרים״ וואס מיינט — ע״ד הנ״ל בפתרון חלומות — אז ס׳זיינען דא צוויי זאכן וואס אויס־ערלעך זעען זיי אויס צו זיין ענינים שונים, און דער פתרון איז וואס מ׳איז מגלה און מפרש דעם תוכן פנימי וואס איז זיי מקשר ומאחד.\nאין עבודת האדם בנדו״ד מיינט עס: מ׳איז פותר די מוחין דאימא, די\nהתלהבות און רצוא וואס קומט ארויס פון בינה, אז עס זאל זיין ווי עס מאנט זיך לויט דער כוונה פנימית.\nאון דערנאך ווערט נמשך דער אור החכמה אין דעם תנוך, ביז אויך „על בוהן ידו גו׳ ועל בוהן רגלו״ — אין קיום המצות במעשה, ביד ורגל⁵¹,\nוואס דעמאלט ווערט בטל דער ענין פון נגעים און „וכפר עליו הכהן וטהר״⁵².\n(משיחת ש״פ מצורע תש״ל)",[["50","50","לקו״ת פרשתנו שם לענין זה שצריך לתקן תחלה המעוות במוחין דאימא."],["51","51","ראה תורת לוי״צ שם."],["52","52","פרשתנו יד, כ."]]],[1300171179,"<h3>מצורע ב</h3>\nא. אין פסוק<sup data-n=\"1\">1</sup> „וכלי חרש אשר יגע בו הזב ישבר וכל כלי עץ ישטף במים״, שטעלט זיך רש״י אויף די ווערטער „וכלי חרש אשר יגע בו הזב״, און איז מפרש: „יכול אפילו נגע בו מאחוריו וכו' כדאיתא בתו״כ *1 עד איזהו מגעו שהוא ככולו<sup data-n=\"2\">2</sup> הוי אומר זה היסטו״.\nדארף מען פארשטיין: וואס איז דא שווער אין פשש״מ וואס צוליב דעם איז רש״י מפרש די ווערטער „יגע בו״ לויט דרשת חז״ל אין תו״כ — און ניט אז „יגע בו״ איז כפשוטו, אז דאס מיינט נגיעה און יעדע נגיעה, אפילו מאחוריו ?\nאיז די הסברה אין דעם: מ'קען דא ניט טייטשן אז „יגע בו״ מיינט נגיעה ממש, וויבאלד אז מ'האט שוין פריער (אין פ' שמיני<sup data-n=\"3\">3</sup> ביי טומאת שרץ) ארויס־געלערנט — ווי רש״י זאגט דארט — אז „אין כלי חרס מיטמא אלא מאוירו״, און דעריבער קען מען שוין דא ניט טייטשן אז „וכלי חרש אשר יגע בו״ זאל טמא ווערן דורך א נגיעה „מאחוריו״; היות אבער אז מ'קען מחלק זיין: דוקא דארטן ביי טומאת שרץ, וואס איז א טומאה קלה, איז „אין כלי חרס מיטמא אלא מאוירו״, משא״כ ביי טומאת זב וואס איז א טומאה חמורה (ס'איז מטמא במשכב ובמושב) קען א כלי חרש יע טמא ווערן דורך נגיעה „מאחוריו״, און יגע בו מיינט דא כפשוטו —\nאיז דעריבער, כדי צו באווארענען מ'זאל ניט אננעמען דעם חילוק (בפרט אז דאס איז מער מתאים לפשש״מ) איז רש״י מעתיק פון פסוק [ניט נאר די ווערטער (וועלכע ער איז מפרש) „יגע בו״, נאר אויך די ווערטער וואס זיינען מבליט דעם חילוק הנ״ל] „וכלי חרש אשר יגע בו הזב״, און זאגט: „יכול אפילו נגע בו מאחוריו (וויבאלד דא רעדט זיך וועגן טומאת זב) וכו' כדאיתא בתו״כ״ — [דער המשך אין תו״כ איז: „ודין הוא ומה אם מת החמור לא טימא כלי חרס מאחוריו, הזב הקל אינו דין שלא יטמא כלי חרס מאחוריו. לא אם אמרת במת שאינו עושה משכב ומושב וכו' ת״ל אשר יגע בו ולהלן<sup data-n=\"4\">4</sup> הוא אומר אשר תבושל בו מה בו האמור להלן מאוירו אף כאן מאוירו״],\nלפי״ז ווערט דאך די שאלה: אויב נגיעה „מאחוריו״ איז ניט מטמא, איז וואס מיינט „יגע בו״<sup data-n=\"5\">5</sup> ? — אויף דעם בריינגט רש״י דעם סיום פון תו״כ: „איזהו מגעו שהוא ככולו הוי אומר זה היסטו״.\nב. מ'דארף אבער פארשטיין — ממנ״פ: אדער רש״י האט געדארפט מעתיק זיין דעם תו״כ אינגאנצן (אויך די ראי' אז „יגע בו״ קען ניט מיינען „מאחוריו״): און אויב רש״י פארלאזט זיך אז מ'וועט אליין נאכקוקן אין תו״כ — האט ער אויך ניט געדארפט מעתיק",[["1","1","פרשתנו טו, יב. *1) עה״פ."],["2","2","בפי' רבינו הלל ובקרבן אהרן גרסי בתו״כ שם: „בכולו״. וכ״ה בדפוס ראשון דרש״י. ובס' זכרון לרש״י כאן: בכולו בבי״ת גרסינן."],["3","3","יא, לג."],["4","4","צו ו, כא."],["5","5","כי אין לומר ד„יגע בו״ פירושו שיגע בתוכו, שהרי אין צריך שיגע, כי מטמא מאוירו — ראה גו״א כאן."]]],[1300171180,"זיין דעם סיום („איזהו מגעו וכו'״), נאר ענדיקן זיין פירוש מיט די ווערטער „כדאיתא בתו״כ״ [ועד״ז פירושו אין פ' ויקרא<sup data-n=\"6\">6</sup>: „וא״ת מקרא שלא לצורך הוא כבר נדרש הוא בתו״כ״] ?\nבפשטות וואלט מען געקענט פאר־ענטפערן: דאס וואס רש״י בריינגט דעם סיום „איזהו מגעו וכו'״ איז ווייל דער־מיט איז געגעבן דער טייטש פון „יגע בו״ (— היסט): משא״כ דער פריער־דיקער המשך פון תו״כ, וואס זיין תוכן איז בלויז א לימוד וראי' אז כלי חרש „אינו מיטמא מאחוריו״, דעריבער בריינגט ער עס ניט און פארלאזט זיך אז מ'וועט אליין מעיין זיין אין תו״כ.\nס'איז אבער שווער אזוי צו זאגן — ווארום (ווי גערעדט כמה פעמים) אלץ וואס איז מוכרח צו הבנת פשוטו של מקרא בריינגט רש״י ארויס קלאר פאר א בן חמש און מפורש; און וויבאלד אז דער פירוש פון „יגע בו״ קען מיינען אויך נגיעה „מאחוריו״, האט דאך רש״י געדארפט שרייבן בפירוש דעם ענין וואס איז מכריח צו מפרש זיין ניט אזוי — און ניט פארלאזן זיך אויפן ציין צום תו״כ [ובפרט, אז דער תו״כ לערנט עס אפ פון א גז״ש — און ניט פון פשטות הכתובים<sup data-n=\"7\">7</sup>].\nמוז מען זאגן, אז לויט פשוטו של מקרא איז די ראי' (ניט פון דער גז״ש „בו — בו״ וואס ווערט ניט געבראכט\nאין פרש״י, נאר) פון די ווערטער וואס רש״י איז מעתיק בפירוש פון תו״כ [און דאס וואס ער זאגט „וכו' כדאיתא בתו״כ״ איז נאר לתוס' ראי' וביאור (כדלקמן), און דערפאר איז ער זיך מסתפק מיט'ן רמז „וכו' כדאיתא בתו״כ״].\nג. לכאורה וואלט מען געקענט זאגן, אז מ'לערנט עס אפ פון טומאת מת — וואס איז אויך א טומאה חמורה ביותר, און פונדעסטוועגן איז עס ניט מטמא א כלי חרס מאחוריו — ווי מ'וועט ווייטער לערנען אין פ' חוקת<sup data-n=\"8\">8</sup> — פארשטייט מען דערפון אז אויך א זב (וואס איז ניט אזוי חמור ווי מת) איז ניט מטמא א כלי חרש מאחוריו.\nאון דאס איז כוונת רש״י אינעם מציין זיין צום תו״כ: ער מיינט ניט די גז״ש „בו — בו״, נאר דעם ק״ו וואס בריינגט זיך דארטן — „ומה אם מת החמור לא טימא כלי חרס מאחוריו הזב הקל אינו דין שלא יטמא כלי חרס מאחוריו״ (וואס ק״ו — איז א סברה פשוטה, פשש״מ *<sup data-n=\"8\">8</sup>. און הגם אז דער תו״כ פרעגט אפ דעם ק״ו, ווייל אויך ביי זב איז דא א חומרא („עושה משכב ומושב״) וואס איז ניטא ביי מת — מיינט עס נאר אז „שקולים הם״ (אז יעדער האט א חומרא לגבי דעם צווייטן), און לויט פשוטו של מקרא<sup data-n=\"9\">9</sup> איז דאס א טעם אז זיי זאלן זיין „שקולים״ אויך אין דעם דין פון ניט מטמא זיין א כלי חרס מאחוריו.\n[און דאס וואס רש״י איז מציין צו תו״כ — און ניט צום פסוק (פשש״מ) אין",[["6","6","ה, יט. וראה פרש״י שם ג, יז [וברא״ם שם: ולא ידעתי למה לא הביא הרב כל המדרש שבפסוק הזה כו'. וראה משכיל לדוד שם]. ועד״ז בכ״מ."],["7","7","אף שגם גז״ש הוא לימוד בפשש״מ, כדמוכח מזה שהובאו בפרש״י עה״ת (לדוגמא: משפטים כא, ו. ועוד) — מ״מ מובן, שאי״ז לימוד פשוט כ״כ כפירוש הפשוט של הכתוב, גם לא כלימוד בק״ו. גם יש בלימוד בגז״ש ע״ד הפשט תנאים ע״ד שישנם בלימוד ע״ד ההלכה. ואכ״מ."],["8","8","יט, טו וברש״י. *8) ראה פרש״י בראשית א, יב. שם ו, ג. ובכ״מ."],["9","9","משא״כ ע״ד ההלכה, שי״ל שהחומרא ד„עושה משכב ומושב״ היא מכריעה וגורמת שכלי חרס יטמא ממנו גם מאחוריו."]]],[1300171181,"פ' חוקת, ווייל די הוכחה פון פסוק (א) איז פארבונדן מיט אן אריכות און וואס (ב) אויך נאכדעם איז ניט זיכער אז דער בן חמש וועט פארשטיין כדבעי דעם לימוד: אין תו״כ אבער איז דער לימוד בפירוש ובפירוט].\nעס איז אבער ניט אויסגעהאלטן — ווייל [לבד זאת וואס עס בלייבט ניט גלאטיק: פארוואס שרייבט רש״י ניט דעם הכרח בפירוש, כנ״ל — איז נוסף לזה]:\nא טמא מת איז דאך ניט מטמא בהיסט<sup data-n=\"10\">10</sup> — איז אויב מ'קען זאגן אז דער פסוק „אשר יגע בו״ קומט מחדש זיין אז א זב איז מטמא בהיסט (וואס איז ניטא ביי טומאת מת), פארוואס זאל מען ניט זאגן, אז דער חידוש אין „יגע בו״ באשטייט אין דעם וואס א זב איז מטמא א כלי חרס מאחוריו, כאטש אז א מת קען עס ניט מטמא זיין (און דער פירוש דארף זיין עדיף, ווייל לויט עס דוקא וועט מען טייטשן „יגע בו״ כפשוטו) ?\nד. לכאורה וואלט מען געקענט ענטפערן, אז רש״י״ס הכרח איז פון סיום הפסוק — „וכל כלי עץ ישטף במים״:\nבשלמא אויב „יגע בו״ מיינט היסט, איז מובן דער חידוש אין „וכל כלי עץ״ — אז ביי זב איז אויך כלי עץ טמא בהיסט; אויב אבער „יגע בו״ מיינט כפשוטו — אפילו „נגיעה מאחוריו״, און דער פסוק איז דא מחדש אז זב איז מטמא א כלי חרש דורך נגיעה מאחוריו — ווערט דאך לפי״ז קשה: וואס איז דער חידוש אין „וכל כלי עץ״ ? אז א כלי עץ ווערט טמא בנגיעה מאחוריו איז דאך ניט קיין חידוש.\nאבער אויך די הסברה איז שווער איינצולערנען אין פרש״י — ווייל אויב אזוי, וואלט דאך רש״י מעתיק געווען אין דעם דיבור־המתחיל אויך די ווערטער „וכל כלי עץ״, אדער לכה״פ מרמז זיין זיי מיט'ן ווארט „וגו'״; און וויבאלד אז רש״י טוט עס ניט, איז א ראי' אז ער האלט עס ניט פאר א הוכחה אז „יגע בו״ מיינט היסט, וכדלקמן, (אדער אז די ראי' וואס ער בריינגט איז א בעסערע).\nה. וועט מען דאס פארשטיין בהקדים התמי': לכאורה וואס לערנט אונז דער פריערדיקער פסוק „וכל אשר יגע בו הזב וידיו לא שטף במים וכבס בגדיו ורחץ במים וטמא עד הערב״ — עס שטייט דאך שוין פריער<sup data-n=\"11\">11</sup> „והנוגע בבשר הזב יכבס בגדיו ורחץ במים וטמא עד הערב״ ?\n[און דער דין (ווי רש״י איז מפרש) אז כל זמן וואס „לא טבל מטומאתו ואפילו פסק מזובו וספר שבעה.. מטמא כו'״ — איז: (א) קען מען עס אפלערנען מיט א כל שכן פון דעם דין ביי יולדת<sup data-n=\"12\">12</sup>, וואס מוז האבן טבילה (און אפילו נאך טבילה — „בכל קודש לא תגע״, „ואין שמשה מעריב לטהרה עד שקיעת החמה של יום ארבעים שלמחר תביא את כפרת טהרתה״); (ב) ועיקר: צוליב דעם דארף די תורה ניט איבער'חזר'ן דעם גאנצן פסוק, עס וואלט געווען גענוג צו אריינ־שטעלן די ווערטער „וידיו לא שטף במים״ אין פריערדיקן פסוק „והנוגע בבשר הזב״].\nאון צוליב דער תמי' לערנט טאקע די",[["10","10","ראה שבת פג, רע״ב (וש״נ): שלא מצינו לו חבר בכה״ת."],["11","11","פסוק ז'."],["12","12","לעיל — תזריע יב, ד. פרש״י שם. ובפרש״י שם, ז: מכלל שעד כאן קרוי' טמאה."]]],[1300171182,"גמרא<sup data-n=\"13\">13</sup>, אז דאס וואס עס שטייט „וכל אשר יגע בו הזב גו'״ מיינט ניט נגיעה, נאר — היסט. רש״י אבער לערנט ווי דער תו״כ, אז ערשט דער „יגע״ פון אונזער (שפעטערדיקן) פסוק מיינט „היסט״ — בלייבט דאך קשה לויט פרש״י: צוליב וואס שטייט דער פסוק „וכל אשר יגע בו הזב גו'״ (און מ'זעט ניט אז רש״י זאל עס באווארענען) ?\nנאר דער ביאור אין דעם: (אויך) לויט פשוטו של מקרא קען שטיין א גאנצער פסוק צוליב איין פרט וואס ווערט נתחדש אין אים, ובמכש״כ פון דעם וואס אמאל חזר׳ט איבער די תורה א גאנצע פרשה „בשביל דבר שנתחדש בה״<sup data-n=\"14\">14</sup> [און ווי מיר זעהן גלייך אין פ' בראשית<sup data-n=\"15\">15</sup>: די תורה חזר׳ט איבער נאכ־אמאל דעם סיפור פון בריאת אדם וחוה צוליב די פרטים וואס קומען צו אינעם צווייטן סיפור. ועוד<sup data-n=\"16\">16</sup>].\nאון דערפאר איז (בפשש״מ) קיין קשיא ניט, צוליב וואס דארף שטיין דער פסוק „וכל אשר יגע בו הזב״ — ווייל דאס שטייט צוליב דעם חידוש פון די צוגעגעבענע ווערטער „וידיו לא שטף במים״, וואס לערנט אונז (ווי רש״י<sup data-n=\"17\">17</sup> איז מסיים בפירושו — נאכדעם\nווי ער איז מפרש דעם פשט) „שאין בית הסתרים טעון ביאת מים אלא אבר הגלוי כמו הידים״.\nו. ווען רש״י קומט אבער צו אונזער פסוק — וואס אויך דא ווערט שווער: וואס איז דער חידוש אין פסוק ? אז א כלי ווערט טמא דורך נגיעת הזב קען מען וויסן במכש״כ וק״ו פון די פריער־דיקע דינים (אז אן אדם ווערט טמא בנגיעת הזב; אז א זב איז מטמא אפילו במשכב ומושב וכו') —\nדארף דא רש״י באווארענען: „יכול אפילו נגע בו מאחוריו״ — וויבאלד אז דער פירוש הפשוט פון „יגע בו״ איז אפילו „מאחוריו״, קען מען דאך מפרש זיין, אז דער חידוש באשטייט אין דעם וואס א „זב״ איז מטמא בנגיעה א „כלי חרש״ אויך „מאחוריו״ (וכנ״ל בארוכה):\n— און ס'איז קיין קושיא ניט וואס אינעם סיום הכתוב „וכל כלי עץ וגו'״ איז ניטא קיין חידוש, ווייל, ווי געזאגט, איז גענוג וואס דער פסוק טוט אויף א חידוש דין נאר אין איין פרט, אז (אויך) ביי כלי חרש איז א זב מטמא בנגיעה „מאחוריו״ —\nאון לתוס' ראי' צום „יכול וכו'״ איז רש״י מוסיף „וכו' כדאיתא בתו״כ״ — וואס דארט זעט מען טאקע, אז מצד דער חומרא פון טומאת זב איז יש מקום לומר אז ער איז מטמא א כלי חרס מאחוריו (כאטש א מת קען עס ניט מטמא זיין). ד.ה. דאס וואס רש״י איז מציין צום תו״כ איז עס (ניט צו דער התחלת ההמשך, צום לימוד אז א זב איז ניט מטמא כלי חרס מאחוריו, נאר פאר־קערט:) צו דעם סיום (— צווייטער סברא אין) המשך התו״כ („עד *17",[["13","13","נדה מג, רע״א. פרש״י שם ד״ה דכתיב."],["14","14","סוטה ג, סע״א. וש״נ. פרש״י נשא ה, ו. וראה פרשתנו יד, כא ואילך. מנחות י, א."],["15","15","ב, ז. שם, כא ואילך."],["16","16","ראה לדוגמא פרש״י בראשית שם, יט."],["17","17","ועפ״ז יומתק דמציין רש״י (בפרש״י דילן) לתו״כ דשולל דרז״ל דנדה (כנ״ל בפנים) — כי לשיטת הש״ס (קידושין כה, א) למדין „שאין בית הסתרים טעון ביאת מים״ מפסוק שלאחריו (פסוק יג *). אבל להעיר מתוס' קידושין שם סד״ה כל הראוי. מעדני יו״ט לרא״ש הל' מקואות (בסוף מס' נדה) סכ״ה סק״ג. וראה המקנה קידושין שם. *) או — פסוק טז. ראה תוס' (ומעדני יו״ט) שבפנים ההערה. *17) וי״ל שזהו הדיוק „עד״ (ולא „ומסיים״ או כיו״ב)."]]],[1300171183,"(ובסמיכות צו<sup data-n=\"18\">18</sup> איזהו מגעו״) אז עס איז יע דא א סברא („יכול״) אז „אפילו נגע בו מאחוריו״ *18 זאל עס ווערן טמא (און מהאי טעמא איז ער דערויף נאר מרמז דורך „וכו'״ און בריינגט עס ניט בפירוש).\nאון דער הכרח אז מ'קען אזוי ניט לערנען, איז פון דעם סיום התו״כ — „איזהו מגעו שהוא ככולו הוי אומר זה היסטו״, כדלקמן.\nז. די הסברה אין דעם: נוסף אויף דעם וואס לכאורה איז דער גאנצער פסוק איבעריק — זיינען די ווערטער בהתחלת הכתוב „(וכלי חרש) אשר יגע בו הזב״ א יתור לשון לגמרי: דער פסוק קומט בהמשך צום פריערדיקן פסוק וואס זאגט „וכל אשר יגע בו הזב״ — וואלט דאך געווען גענוג עס זאל שטיין בקיצור „וכלי חרש ישבר״ [ע״ד ווי אין סיום הפסוק „וכל כלי עץ ישטף במים״, און עס שטייט ניט (נאכאמאל) „וכל כלי עץ אשר יגע בו הזב ישטף במים״].\nאיז דעריבער מסתבר צו זאגן, אז דער חידוש אין דעם פסוק ליגט אין די ווערטער, אין „יגע בו״: „יגע בו״ מיינט דא א נייער אופן אין נגיעה (ניט ווי די נגיעות וואס שטייען פריער). דער „יגע״ איז „בו״<sup data-n=\"19\">19</sup> — א נגיעה אין דער גאנצער (כללות ה)כלי, און ניט ווי א געווינלעכע נגיעה וואס איז אין א שטח מצומצם פון דער זאך; ובלשון רש״י: „איזהו מגעו שהוא ככולו הוי אומר זה\nהיסטו״, וואס דורך דעם ווערט „נת־נדנד״ די גאנצע כלי.\n[משא״כ אויב מ'וועט לערנען אז דער חידוש פון פסוק איז אין דעם וואס א כלי חרש איז מיטמא מאחוריו — איז דער חידוש נאר אין די ווערטער „וכלי חרש״, אדער אויך אין דעם ווארט „בו״ — אבער ניט אין „יגע בו״ צוזאמען].\nח. די הוראה אין עבודת ה':\nא כלי חרס, וואס ווערט געמאכט פון עפר, איז מרמז אויפן מענטשן וואס „יסודו מעפר״<sup data-n=\"20\">20</sup> [וכמש״נ<sup data-n=\"21\">21</sup> „ויצר ה״א את האדם עפר מן האדמה גו'״, „כי עפר אתה גו'״<sup data-n=\"22\">22</sup>]. און אויף דעם זאגט מען, אז א כלי חרס ווערט ניט טמא מאחוריו: די ענינים פון עוה״ז וואס ווערן צוגע־קלעפט צום גוף האדם (וואס דער גוף זיינער ווערט אנגערופן „אחוריו״) קענען ניט מטמא זיין דעם עצם פון א אידן:\nווארום וויבאלד אז דער אויבער־שטער האט אים באשאפן אזוי, אז זיין גוף מוז אנקומען צו אכילה ושתי' ושאר עניני עוה״ז<sup data-n=\"23\">23</sup>, וואס עפ״י טבע<sup data-n=\"24\">24</sup> האט ער הנאה פון זיי<sup data-n=\"25\">25</sup> — און די עבודה איז דאך ניט צו ברעכן דעם גוף, נאר (כתורת הבעש״ט<sup data-n=\"26\">26</sup> עס דארף זיין „עזוב",[["18","18","כי מ״ת״ל אשר כו' מתחילה המסקנא של תו״כ זה שסיומה „איזהו מגעו״. *18) אלא שצע״ק לשון רש״י „עד איזהו כו'״. שמהוספה זו משמע שכוונתו שגם מה שלא העתיק בפירוש מהתו״כ שייך לפשוטו של מקרא. ואולי כוונתו גם להגז״ש „בו, בו״ (לתוספת ראי', שגם ע״ד ההלכה כ״ה דאינו מטמא כלי חרס מאחוריו)."],["19","19","ראה גם באר מים חיים (לאחי המהר״ל) כאן."],["20","20","פיוט ונתנה תוקף."],["21","21","בראשית ב, ז."],["22","22","שם ג, יט."],["23","23","ראה תניא (פי״ג) בנוגע לבינוני — „נתחזק יותר בהמשך הזמן שנשתמש בו הרבה באכילה ושתי' ושאר עניני עוה״ז״. והרי „מדת הבינוני היא מדת כל אדם ואחרי' כל אדם ימשוך״ (שם רפי״ד)."],["24","24","ראה תניא פ״ח."],["25","25","להעיר מד״ה ואתם הדבקים תרפ״ה (סה״מ תיש״א ע' 208), דגם הגופים דימות המשיח, מכיון שיולדו ע״י או״א גשמי' בתאוה גשמי' יצטרכו לזיכוך כו', עיי״ש."],["26","26","היום יום ע' כג. הוספות לכתר שם טוב סט״ז. וש״נ."]]],[1300171184,"תעזוב עמו״<sup data-n=\"27\">27</sup>, מאכן פון זיין גוף וחלקו בעולם א דירה לו ית' (בתחתונים) — איז ער ניט שולדיק אין דעם וואס עס האבן זיך צו אים צוגעקלעפט ענינים פון עוה״ז, חאטש אז סוף סוף דארף ער ריין ווערן פון זיי *27.\n[במה דברים אמורים — אויב ער האלט זיך ווי דער אויברשטער האט אים באשאפן — א כלי חרס (וואס ווייזט אויף ביטול); אבער אויב ער האלט זיך ווי א כלי עץ — ער איז ביי זיך א צוואקסענע מציאות (ווי אן עץ וואס וואקסט), אדער ווי א כלי מתכת — ער איז הארט אין זיין ישות ווי א מתכת, איז וויבאלד אז ער איז שוין ניט אין דעם ציור ווי ער איז באשאפן געווארן, ווערט ער דעמאלט טמא אויך „מאחוריו״].\nאון אויף דעם זאגט רש״י „יכול אפילו נגע בו מאחוריו״: מ'וואלט געקענט מיינען, אז א טומאה חמורה ווי זב איז מטמא אידן, ח״ו, אפילו „מאחוריו״ — ווארום דער ענין הזיבה איז ניט אן ענין טבעי ווי דם נדה<sup data-n=\"28\">28</sup>, נאר א חולי הגוף — דם מערער ווי עס דארף זיין מצד טבע העולם. ובעבודת האדם: דם נדה איז דער רע וואס איז דא מצד טבע ביי א אידן, „כי יצר לב האדם רע מנעוריו״<sup data-n=\"29\">29</sup>; דם זיבה איז דאס וואס מגרה יצרו עליו נאכמער ווי דער יצה״ר איז אים מבלבל מצ״ע<sup data-n=\"30\">30</sup>, ובלשון החינוך<sup data-n=\"31\">31</sup>: „ענין הזיבה\nיקרה באדם בצאתו מדרך היושר בהתמדה במאכליו וכו'״.\nאון דעריבער וואלט מען געקענט מיינען אז אין דעם פאל ווערט דער מענטש („כלי חרס״) טמא אפילו „מאחוריו״ — וויבאלד אז ער פאלט דורך אין אזא רע וואס איז ניט מוכרח מצד טבע האדם.\nאויף דעם זאגט (דער תו״כ ו)רש״י אז עס איז ניט אזוי: ווען די נגיעת הזב איז „מגעו שהוא ככולו״, עס רירט אן אין כללות האדם, קען דער „כלי חרס״ טמא ווערן (אפילו „מאחוריו״): אבער סתם א נגיעה, אפילו פון א זב, קען ניט אנרירן דעם עצם פון א אידן, וכפסק דין הרמב״ם<sup data-n=\"32\">32</sup>, אז אפילו א איד וואס מ'דארף אים כופה זיין צו טאן א מצוה, איז עס (די כפי') נאר מצד זיין חיצוניות — „יצרו הוא שתקפו״: אבער אויך דאן, איז בפנימיותו „רוצה להיות מישראל ורוצה הוא לעשות כל המצות״,\nאון דורך דער כפי' ווערט אראפ־גענומען דעם אבק וואס איז מכסה ומעלים אויף דעם רצון האמיתי פון דעם אידן, עס ווערט נתגלה דער „אמת ה'״ (אויך „לעולם״<sup data-n=\"33\">33</sup>, אז א איד זאגט „רוצה אני״ — „להיות מישראל״ און „לעשות כל המצות״.\n(משיחת ש״פ מצורע תשל״ו)",[["27","27","משפטים כג, ה. *27) ראה תניא פ״ח."],["28","28","לאחרי חטא עה״ד — עירובין ק, ב."],["29","29","נח ח, כא."],["30","30","ראה בכ״ז לקו״ש ח״ז ע' 317 ואילך. לקו״ש חי״ד ע' 26־8. וש״נ."],["31","31","מצוה קעח."],["32","32","הל' גירושין ספ״ב."],["33","33","תהלים קיז, ב. וראה לקו״ת דרושים לשמע״צ ד״ה ביום השמע״צ (הא') פ״א."]]],[1300171185,"<h3>אחרי *</h3>\nא. אין דער היינטיקער פרשה¹, ביי דער עבודה פון כהן גדול ביום הכיפורים, שטייט: „וכפר בעדו ובעד ביתו“ — דרש׳נען חז״ל²: „ביתו זו אשתו“, און מ׳לערנט דערפון אפ דעם דין אז דער כהן גדול ביום הכיפורים מוז זיין א נשוי³.\nאון דער חיוב אז דער כה״ג זאל זיין א נשוי, איז א דין מיוחד וואס איז געזאגט געווארן נאר בנוגע יום הכיפורים, און ניט בנוגע א גאנץ יאר:\nאין אלע אנדערע טעג קען א כהן גדול זיך משתתף זיין אין דער עבודה, ואדרבה: אין וועלכן משמר עס זאל ניט זיין איז ער „מקריב חלק בראש“⁴ — אבער דערביי איז ניטא קיין תנאי אז ער דארף זיין א נשוי, ווי ביי יוהכ״פ⁵.\nלכאורה דארף דאס האבן א ביאור והסברה: די עבודה פון יום הכיפורים איז דאך בתכלית העילוי, ס׳קומען זיך צוזאמען די העכסטע דרגות פון קדושה הן אין מקום, הן אין זמן און הן אין דרגות פון נש״י (בסגנון הידוע: עולם שנה נפש⁶): די עבודה ווערט געטאן אין קדש הקדשים — מקום הכי מקודש בעולם; אין יום הקדוש (ווי ער ווערט אנגערופן בפי כל), דער הייליקסטער זמן פון יאר; און דאס ווערט געטאן דורכן כהן גדול דער גדול פון כל הכהנים אויף וועמען עס שטייט⁷: „ויבדל גו׳ להקדישו קדש קדשים“, גדול מהם אויך בקדושה וכמש״נ: והכהן הגדול מאחיו גו׳ כי אני הוי׳ מקדשו⁸.\nהיינט ווי קומט עס אז דוקא (ביי דער עבודה) ביום הכיפורים מאנט זיך אז דער כהן גדול זאל מוזן זיין נשוי?\nדי תמי׳ ווערט נאך גרעסער: איינע פון די הכנות צו דער עבודה פון יום הכיפורים איז (ווי געזאגט אין דער זעל־בער משנה): „ז׳ ימים .. מפרישין כה״ג מביתו“ — און צוזאמען דערמיט איז „ביתו (זו אשתו)“ ביים כה״ג א תנאי לעיכובא דוקא ביום הכיפורים!\nדערפון גופא איז א הוכחה, אז דאס וואס כה״ג (ביוה״כ) מוז זיין א נשוי,",[["","","*) וסיום מסכת יומא ס״י ואילך."],["1","1","טז, ו. וראה לקמן הערה 14."],["2","2","יומא בתחלתה (במשנה)."],["3","3","כי פלוגתת ר״י וחכמים (במשנה שם) הוא רק אם מתקינין לו אשה אחרת שמא תמות אשתו, אבל לכו״ע צ״ל נשוי (אלא שבתוי״ט יומא שם (ד״ה שמא) מסתפק אם הוא דין לעיכובא, או שבדיעבד לא מיפסל בכך לעבודה)."],["4","4","יומא יד, א (במשנה). יז, ב. וראה צפע״נ הל׳ מתנ״ע נח, א."],["5","5","אף דמ״ע על כה״ג שישא נערה בתולה כו׳ (רמב״ם הל׳ איסו״ב פי״ז הי״ג. ספר המצות מ״ע לח) הרי: א) לכמה דעות (ראה תוי״ט יומא עג, א. תוס׳ הרא״ש הוריות יב, א) הרי זה לאו הבא מכלל עשה. וכ״מ ל׳ הרמב״ם בסהמ״צ שם (מדלא כתב שאם לא נשא בתולה עובר בעשה). ב) גם לפי המשמע מדבריו (בהל׳ איסו״ב שם. ובהל׳ כלי המקדש פ״ה ה״י) דהוי קום ועשה [וכדעת הרמב״ן אמור (כא, יג) — ראה קנאת סופרים לסהמ״צ שם, חמדי״ש שם. ולהעיר מצפע״נ על הרמב״ם איסו״ב שם ה״י״ד. וראה לשון החינוך מצוה ערב בתחלתה ובסופה] הרי פשוט שזה מ״ע צדדית המוטלת על כה״ג ואי״ז שייכת לעבודה. ולא מצינו שיתחייב להיות „נשוי“ אלא ביוהכ״פ. ובחינוך שם: כ״ג שמינוהו ועבד .. כולן מצווין על הבתולה ואסורין באלמנה. וראה לקו״ש ח״ז ע׳ 319 בדעת הזהר. עיי״ש."],["6","6","אשר על ענין ג׳ בחי׳ אלו הוא היסוד של ספר יצירה (אוה״ת יתרו ע׳ תתטז ואילך)."],["7","7","דה״א כג, יג."],["8","8","אמור כא, י־טו. ובתו״כ עה״פ: להגיד מה גרם (לכל דיני כה״ג שבפרשה שם)."]]],[1300171186,"ליגט דערין אן ענין מיוחד וואס גיט צו אין דער שלימות פון כה״ג — און דער־פאר פאדערט זיך עס פון כה״ג ביום הכיפורים.\nב. די הסברה פון דעם אויבען־געזאגטן דין — אז דער כה״ג ביוהכ״פ דארף זיין א נשוי — קען מען לערנען אויף צווי אופנים:\nא) דאס איז א דין אין דער עבודה פון יוהכ״פ: מצד דער חשיבות און עילוי פון דער עבודה, דארף זי געטאן ווערן ניט דורך א כהן סתם נאר דורך א כה״ג, און ניט דורך א כה״ג סתם נאר דוקא דורך א כהן גדול וואס האט אין זיך די מעלה פון „ביתו זו אשתו“;\nב) דאס איז א דין אין דעם כה״ג: אין דעם טאג פון יוהכ״פ מוז דער כה״ג זיין אין א העכערער מעלה און שלימות; און ע״ד ווי מיר געפינען כו״כ דרגות אין א כה״ג בכלל (אויך בכל השנה): משוח בשמן המשחה, מרובה בגדים, וכיו״ב⁹, אזוי איז ביוהכ״פ דארף ביי אים צוקו־מען אויך אט די מעלה און שלימות נוספת פון „ביתו זו אשתו“.\nדי נפק״מ צווישן די צווי סברות להלכה: אין יוהכ״פ זיינען דאך פאראן אויך די עבודות וואס מ׳טוט זיי יעדן טאג, וועלכע זיינען ניט געבונדן דוקא מיט יום־כיפור — ווי הקרבת התמי־דים, הקטרת קטורת, הטבת הנרות וכו׳ — וואס אויך זיי ווערן ביוהכ״פ געטאן דורכן כה״ג¹⁰. איז הגם אז די קדושה פון יוהכ״פ איז פועל אויך אויף די עבודות וואס זיינען ניט יוהכ״פ׳דיגע במיוחד, וכלשון הגמרא¹¹ „אהנאי“, פונ־דעסטוועגן זיינען זיי ניט בדומה צו די עבודות וועלכע זיינען נאר ביוהכ״פ — און דעריבער קען מען זאגן:\nאויב מ׳זאל אננעמען, אז דאס וואס דער כה״ג דארף זיין א „נשוי“ איז א חיוב אין דער עבודה פון יוהכ״פ, איז דא אן ארט צו זאגן אז לגבי די עבודות, וואס זיינען ניט געבונדן מיט יום־כיפור, איז ביים כה״ג ניטא דער חיוב צו זיין א נשוי¹²;\nאבער לויט דער צווייטער סברא, אז דאס איז מצד דער שלימות פון כה״ג וואס דארף זיין ביוהכ״פ, דארף דע־מאלט אויסקומען, אז דער חיוב פון „נשוי“ איז חל אויך לגבי אנדערע עבודות; וויבאלד דאס איז ניט פאר־בונדן מיט דער עבודה נאר מיט׳ן כה״ג — און ער איז דאך דער וואס טוט אלע עבודות פון יוהכ״פ.\nעפ״ז קומט אויס אז דער רמב״ם נעמט אן די צווייטע סברא, ווי ער זאגט¹³: וכן שאר העבודות של יום זה כגון הקטרת הקטורת של כל יום והטבת הנרות הכל עשוי בכה״ג נשוי.\nג. וועט עס זיין מובן בהקדים הביאור אין דער משנה: „וכפר בעדו ובעד ביתו — ביתו זו אשתו“, ולכאורה: וויבאלד דער טייטש פון ביתו (דא) איז „אשתו“, פארוואס זאגט די תורה ניט בפירוש „(וכפר בעדו ובעד) אשתו“¹⁴?",[["9","9","רמב״ם הל׳ כלי המקדש פ״ד הי״ב."],["10","10","רמב״ם הל׳ עבודת יוהכ״פ פ״א ה״ב. וראה נו״כ שם. ומה שהובא בכס״מ דהריטב״א בשם הרמב״ם כ׳ שאין חובה בכ״ג, כבר כתבו שט״ס וצ״ל הרמב״ן. וראה גם תוד״ה משום יומא כ, סע״ב. אבל „תרומת הדשן סדור המערכה ודשן המזבח“ משמע מדברי הרמב״ם (רפ״ד שם) שלא הי׳ ע״י הכה״ג. ואכ״מ."],["11","11","זבחים צא, א. וראה צפע״נ עה״ת ר״פ קרח."],["12","12","ראה גבורת ארי שם ששקו״ט ביתירה מזו, דאולי קפיד רחמנא שיהי׳ לו בית בשעת כפרת ביתו דוקא ולא בשעת כפרת שתי שעירים."],["13","13","פ״א שם. ועד״ז בחינוך מצוה קפה."],["14","14","שהרי ב„ביתו“ הנאמר כאן [משא״כ דלקמן"]]],[1300171187,"ברובא דרובא איז תושבע״פ מפרש באריכות און ענין וואס שטייט אין תושב״כ בקיצור („ליכא מידי דלא רמיזי באורייתא“¹⁵), בנדו״ד אבער באשטייט אויך דער אויסטייטש פון תושבע״פ אין איין ווארט „אשתו“ — איז אנשטאט דעם ווארט „ביתו“ האט דאך די תורה גופא געקענט שטעלן „אשתו“?\nמוז מען זאגן אז מיט׳ן ווארט „ביתו“ איז די תורה אויסן צו זאגן א ענין אין „אשתו“, וואס איז אנגעדייט מיט׳ן ווארט „ביתו“, ד.ה. אז תורה זאגט דא ניט נאר דעם עצם דין אז דער כה״ג דארף זיין א נשוי, נאר זאגט אויך אז דאס איז מצד דעם וואס דאמאלס דוקא האט ער „ביתו“ — די מעלה מיוחדת פון אשתו ווי זי איז „ביתו“.\nצו פארשטיין אט די מעלה פון „ביתו זו אשתו“, דארף מען מקדים זיין וואס מען געפינט אין מס׳ שבת¹⁶: אמר ר׳ יוסי מימי לא קריתי לאשתי אשתי ולשורי שורי אלא לאשתי ביתי ולשורי שדי, ופירש רש״י: אשתי ביתי, שהיא עיקר של בית. ולשורי שדי, שהוא עיקר של שדה דכתיב¹⁷ ורב תבואות בכח שור.\nאין פלוג איז שווער צו פארשטיין: דער מאמר פון ר״י קומט בסוגיא שם אין איין המשך (ובמילא — אין איין תוכן משותף) מיט נאך מאמרים פון ר׳ יוסי וועגן הנהגות טובות און זהירות והידורים¹⁸ — אין וואס באשטייט די מעלה והידור פון אט דער הנהגה צו אנרופן „לאשתי ביתי (ולשורי שדי)“?\nד. דער ביאור אין דעם:\nאין אט דער הנהגה פון ר׳ יוסי דריקט זיך אויס זיין דרך אין עבודה; ווי ער זעט די גאנצע בריאה: ניט נאר זעט ער אז יש בעה״ב לבירה זו¹⁸*, ניט נאר זעט ער אז כל מה שברא הקב״ה בעולמו לא בראו אלא לכבודו¹⁹ — נאר אין יעדער ענין האט ער געזען (נאר) דעם עיקר ותכלית דערפון, און ניט די זאך כשלעצמה, ועד כדי כך — אז באם אנרופן די זאך ווי ער האט עס געמוזט רופן ווי די זאך איז בעולמו — האט בא עם ניט געקענט זיין „קריתי לאשתי אשתי“ ווארום ער זעט ניט „אשתי“, נאר ער זעט „ביתי“¹⁹*: וויבאלד די זאך פון נישואין („אשתו“) איז א הקדמה און הכנה צום עיקר ותכלית דערפון, וואס דאס איז דער קיום פון מצות פו״ר — אויפשטעלן א בית בישראל, וואס קומט ווי א תוצאה פון די נישואין — האט ער דעריבער „אשתי“ געזען נאר אלס „ביתי“.\n[על דרך ווי מיר געפינען דעם הסבר פון ראשונים²⁰ אויף דער שאלה פאר־וואס מ׳האט ניט מתקן געווען קיין ברכה",[["","","(פסוק יא) שכולל „אחיו הכהנים“ — פרש״י שם ע״פ תו״כ עה״פ. שבועות יג, ב ואילך] אין נכללים בני ביתו של הכה״ג, שהרי לא מצינו תנאי בכה״ג ביוהכ״פ שצריך שיהיו לו בנים כו׳. וראה בארוכה גבורת ארי ליומא כאן. ולהעיר מסוטה (מד, א): ובנית ביתך זו אשה."],["15","15","ע״פ תענית ט, א."],["16","16","קיח, ב."],["17","17","משלי יד, ד."],["18","18","ועפ״ז ק״ק מה שפרש״י „לא קריתי לאשתי אשתי — שאף שיחת חולין שלי יש ללמוד הימנו חכמה“. ולפ״ז גם מש״כ בחדא״ג שם צ״ע. ובפרט צ״ע מהי הזהירות והמעלה דמימי לא קריתי. — וי״ל דרש״י מוסיף ביאור: מהו הלימוד לאחרים ואיך יבואו להנהגה כזו מצד עצמם. — ראה לקמן הערה 25*. 18*) ראה ב״ר רפל״ט."],["19","19","אבות ספ״ו. 19*) עפ״ז מובנת האריכות: א) מימי לא קריתי לאשתי אשתי, ב) אלא לאשתי ביתי."],["20","20","ראה רא״ש כתובות פ״א סי״ב."]]],[1300171188,"אויף קידושין („אקב״ו לקדש את האשה“), ווי מ׳האט מתקן געווען אויף אנדערע מצות — ווייל קידושין ונשואין זיינען נאר א הקדמה והכנה צום עיקר ותכלית וואס קומט שפעטער דורכן קיום פון מצות פו״ר²⁰*].\nאון דערמיט האט זיך אויסגעטיילט ר׳ יוסי׳ס הנהגה פון הנהגת חבירין:\nביי אנדערע תנאים איז געווען צייטן (ימים) וואס „קריתי לאשתי אשתי“; זיי האבן געזען דעם ענין פון „אשתו“ כשלעצמו — אן (און פאר) דעם תכלית פון „ביתי“. וואס דאס איז אויך א דרך און א חשיבות ע״פ תורה. ווי מ׳געפינט דעם דין בתורה²¹: „נקי יהי׳ לביתו“ (וועט קענען זיין „ושמח את אשתו“ — דעם ערשטן יאר) גלייך פון די נישואין אן, נאך פאר הולדת בנים; עד״ז דער ציווי (ברגלים וכו׳) „ושמח את אשתו“²² (ביז אז דאס באפרייט דעם מאן פון גע־וויסע אנדערע חיובים); „איש ואשה זכו שכינה ביניהם“²³, ובכלל די ענינים — ע״פ תורה — אין חיי נישואין פון „איש ואשה“ פאר זיך אליין.\nר׳ יוסי אבער האט געהאט אן אנדער סדר און דרך: די גאנצע מציאות פון זיינע חיי נישואין איז געווען נאר בכדי צו מקיים זיין דעם ציווי פון „פרו ורבו“, אויספירן די כוונה פון „לא תהו בראה לשבת יצרה“²⁴ — האט ער אין דעם (ענין אשתו) שוין מלכתחילה געזען נאר דעם (שפעטערדיקן) עיקר ותכלית, דעם ענין פון „ביתי“.\n[דוגמא לדבר — מרז״ל²⁵: „איזהו חכם הרואה את הנולד“, דער פירוש הפשוט אין דעם איז, אז דער חכם פאר־שטייט און ווייס אין יעדן ענין וואס עס וועט „נולד“ ווערן דערפון. אבער דער דיוק אין דעם איז: עס שטייט ניט „יודע את הנולד“ (אדער „מבין“ וכיו״ב), נאר „רואה את הנולד“: ס׳איז א סך מער ווי ידיעה און הבנה: דער חכם²⁵* זעט דעם קומענדיקן נולד — פונקט ווי אלע זען די זאכן וואס זיינען שוין דא בפועל. עס איז דאך „אינה דומה שמיעה לראי׳“²⁶, הגם אז די שמיעה איז אן אמתית בתכלית און אזא תוקף וואס פועלט אויפן מענטשן — ע״ד ווי מיר געפינען ביי יתרו: „(מה) שמועה שמע ובא“²⁷ — פונדעסטוועגן, בכדי ער זאל נעמען די זאך בשלימותה האט ער (יתרו) גע־דארפט קומען און זען מיט די אויגן, ווייל אינה דומה כו׳.\nאון אין דעם באשטייט די מעלה פון א „חכם“, אז כח שכלו (שמיעה) איז אזוי שטארק אז ער ווערט א „רואה את הנולד“, ניט נאר „יודע“ אדער „מבין“].\nדערמיט איז אויך מוסבר במיוחד וואס אט דער מאמר פון ר׳ יוסי — „מימי לא קריתי וכו׳“ — קומט באלד נאך זיין מאמר „חמש בעילות בעלתי ונטעתי חמשה ארזים בישראל“, ווייל אט דער פריערדיקער מאמר איז מגלה דעם תוכן הנקודה פון דעם מאמר שלאחריו: אין זיין סדר מיט „אשתי“ איז ביי אים ניט געווען קיין שום אנדער מציאות אויסער דאס אויפשטעלן א בית בישראל",[["","","20*) להעיר מהמד״א (כתובות נט, ב) אין אשה אלא לבנים. ודפליגי עלי׳ י״ל שהוא בנוגע להדיוק „אלא“."],["21","21","תצא כד, ה. ספהמ״צ מ״ע ריד."],["22","22","ראה ר״ה (ו, ב. וש״נ): אשה בעלה משמחה."],["23","23","סוטה יז, א."],["24","24","ישעי׳ מה, יח."],["25","25","תמיד לב, א. 25*) עפ״ז יומתק דיוק רש״י הנ״ל (בהערה 18) „ללמוד הימנו חכמה“."],["26","26","ראה מכילתא יתרו יט, ט."],["27","27","פרש״י ר״פ יתרו ממכילתא עה״פ. זבחים קטז, א."]]],[1300171189,"פון „חמשה ארזים“, און דערפאר האט ער זי באלד מלכתחילה („מימי“) שוין אנגערופן מיט׳ן נאמען פון איר תכלית — „ביתי“.\nנאכמער: ניט נאר אין דעם מין המדבר, ובפרט א בת ישראל, האט ער געזען נאר דעם תכלית, נאר ער האט אזוי געזען אויך דעם מין החי („שורי“), וואס דאס איז כולל אויך די תבואות כו׳, זיין „חלקו בעולם“ בכללות: אויך אין „שור“ האט ער געזען נאר דעם תכלית און די מטרה פון זיין מציאות — „שדי“, דעם ענין פון „ורב תבואות בכח שור“ וואס קומט דורך חרישה וזריעה און קצירה אין שדה. אויך דאס האט ער געזען פון פאראויס, נאך פאר די תוצאות פון חרישה וזריעה: „מימי“ — האט ער ניט געקאנט רופען שורו שורי, ער האט שוין אינעם „שור“ געזען און במילא אים גערופן — „שדי“.\nה. בכל הנ״ל איז פארשטאנדיק די גרויסע מעלה פון כה״ג וואס ער האט ביוהכ״פ געדארפט זיין א נשוי און דוקא אינעם אופן פון „ביתו זו אשתו“ — דאס מיינט כנ״ל, דער האבן בפועל „אשתו“ און אין א אופן פון זען דעם ענין פון „אשתו“ נאר אלס „ביתו“. און דאס איז א שלימות המעלה וואס קומט צו אויך אין אים אליין²⁸, ווי חז״ל²⁹ זאגן „כל מי שאין לו בית אינו אדם“, אז דורך דער האבן א „בית“ דערגרייכט ער צו מעלת „אדם“³⁰.\nדערפאר איז די תורה מדייק צו זאגן דעם לשון „ביתו“ (און ניט „אשתו“), בכדי צו מדגיש זיין אז דער כה״ג דארף שטיין אין דער דרגא פון „אשתי — ביתי“, ווי תורה שבע״פ טייטשט עס אויס אין דער הנהגה — כל ימיו — פון ר׳ יוסי.\nאון וויבאלד אז דער דין אז דער כה״ג דארף ביוהכ״פ זיין א נשוי איז ניט סתם א חיוב, נאר עס טראגט אין זיך די שלימות המעלה אין כה״ג — „ביתו זו אשתו“, כנ״ל — דערפאר איז (לויט סברא שנ׳ הנ״ל ס״ב איז) דאס ניט א דין אין דער עבודה פון יוהכ״פ, נאר א דין וגדר אין דעם כה״ג, אין וואס פאר א דרגא ער דארף שטיין.\nו. כידוע³¹, איז דא א קשר ושייכות צווישן דער התחלה פון א מסכת און איר סיום, וואס דערפאר איז מען נוהג — אין א הדרן — צו געפינען א תוכן משותף פון דעם סיום פון דער מסכתא מיט איר התחלה.\nאזוי אויך בנדו״ד: דער ענין פון „ביתו זו אשתו“ וואס איז געזאגט געווארן אין דער ערשטער משנה פון מס׳ יומא האט א קשר מיט (דעם סיום פון) דער לעצטער משנה אין דער מסכתא³²: „אמר ר׳ עקיבא³³ אשריכם ישראל לפני",[["28","28","נוסף על המפורש (יבמות סג, א) כל אדם שאין לו אשה אינו אדם. ובזח״ג (ז, ב. קט, ב. רצו, א) „פלג גופא“. ועוד: „ויברך אותם ויקרא את שמם אדם“ הי׳ רק כאשר „זכר ונקבה בראם“ (בראשית ה, ב. וראה זח״א קסה, א)."],["29","29","ראה יבמות שם: וא״ר אלעזר כל אדם שאין לו קרקע אינו אדם. ובתוד״ה שאין: קרקע לבנות עליו שידור בו."],["30","30","ועפ״ז מובנת שייכות והמשך ב׳ המימרות כל אדם שאין לו אשה — שאין לו קרקע כו׳. וראה בית האוצר מערכת א׳ כלל יד."],["31","31","ראה לעיל ע׳ 135 שוה״ג להערה 31. לקו״ש חט״ז ע׳ 311־2 ובהערות שם. וש״נ."],["32","32","פה, ב."],["33","33","ולהעיר משייכות המיוחדת של ר״ע ל„ביתו זו אשתו“, כמסופר בדחז״ל (כתובות סג, א) דר״ע תלה לימוד התורה שלו [שהי׳ באופן נעלה ביותר,"]]],[1300171190,"מי אתם מטהרין מי³³* מטהר אתכם אביכם שבשמים שנאמר³⁴ וזרקתי עליכם מים טהורים וטהרתם ואומר³⁵ מקוה ישראל ה׳³⁶ מה מקוה מטהר את הטמאים אף הקב״ה מטהר את ישראל“.\nצו פארשטיין דעם קשר דארף מען זיך פריער אפשטעלן אויף שאלות ודיוקים אין דברי ר׳ עקיבא:\nא) לכאורה וואס איז ר״ע מחדש — ס׳איז דאך א זעלבסטפארשטענדלעכע זאך, אז נאר דער אויבערשטער איז דער וואס איז מטהר (די חטאים פון) אידן, וכמפורש בכו״כ פסוקים אין חומש ונ״ך?\nובפרט אז גלייך פאר דעם מאמר פון ר״ע שטייט אין דער משנה: „דרש ראב״ע מכל חטאתיכם לפני ה׳ תטהרו³⁷ עבירות שבין אדם למקום יוהכ״פ מכפר עבירות שבין אדם לחבירו אין יוהכ״פ מכפר עד שירצה את חבירו“, וואס פון דעם וואס דא ווערט געזאגט אז די טהרה און כפרה פון יוהכ״פ איז „לפני ה׳“, איז מבואר אז די כפרה קומט פונעם אויבערשטן — היינט וואס, בכלל, גיט צו מאמר ר״ע אויף דעם וואס מ׳ווייס שוין דברי ראב״ע?\nב) נאכמער איז די תמי׳: פארוואס דארף ר״ע אנקומען צו ראיות אז הקב״ה איז מטהר די אידן פון א פסוק אין נביאים, פון א פסוק אין יחזקאל און (איז זיך דערמיט ניט מסתפק און ברענגט א צווייטע ראי׳³⁸ פון) ירמי׳ — בעת דאס איז א פסוק מפורש אין חומש (וואס ווערט געבראכט אין דברי ראב״ע כנ״ל): „(כי ביום הזה) יכפר עליכם לטהר אתכם מכל חטאתיכם לפני ה׳ תטהרו“?\nואדרבה: דוקא אין דעם פסוק ווערן במפורש דערמאנט די ביידע פרטים וואס זיינען דא אין די רייד פון ר״ע: (א) „לפני מי אתם מטהרין“ — „לפני ה׳ תטהרו“ (ב) „מי מטהר אתכם“ — „יכפר גו׳ לטהר אתכם“?\nמ׳קען ניט זאגן אז ר״ע איז מחולק מיט ראב״ע און האלט, אז דער אוי־בערשטער איז מטהר ומכפר (אויך) אויף עבירות שבין אדם לחבירו אפילו ווען לא ריצה את חבירו [און דעריבער קען ער אויך ניט ברענגען די ראי׳ פון פסוק (ווי עס ברענגט ראב״ע) „לפני ה׳ תטהרו“] — ווייל פון דעם לשון „אמר ר׳ עקיבא“, און ניט „ור׳ עקיבא אומר“, איז מובן אז ר״ע איז ניט מחולק³⁹ מיט ראב״ע⁴⁰, נאר ער איז מוסיף אויף זיינע ווערטער.",[["","","וראה מנחות (כט, ב) דמשה „לא הי׳ יודע וכו׳“, עד ש„בולהו אליבא דר״ע“ (סנהדרין פו, א)] באשתו — „שלי ושלכם שלה הוא“. 33*) כ״ה במשנה שלפנינו בש״ס ובמשניות. ובירושלמי, רי״ף וע״י שם — ומי. וראה שינויי נוסחאות במשניות שם."],["34","34","יחזקאל לו, כה."],["35","35","ירמי׳ יז, יג."],["36","36","במשניות ליתא תיבת „ה׳“. והוא כהפסוק בירמי׳ יד, ח. וראה על הגליון בש״ס שם שמציין דבירושלמי, ובריף ובע״י הוא כבפנים. וכ״ה באוה״ת יוהכ״פ ע׳ א׳תקעו. וראה שינויי נוסחאות במשניות שם."],["37","37","פרשתנו טז, ל."],["38","38","כדלקמן בקושיא הג׳."],["39","39","ראה שד״ח כללים (ח״א ע׳ מט וח״ז ע׳ א׳תעה) וש״נ."],["40","40","ועפ״ז מובן שצ״ע במ״ש בריף לע״י שם, דראב״ע ור״ע פליגי במי שיש לו עבירות שבין אדם לחבירו ולא ריצה את חבירו, האם מעכב הכפרה על עבירות שבין אדם למקום — דראב״ע ס״ל ד„אין יוהכ״פ מכפר כלל“*, ור״ע ס״ל דמ״מ מכפר על *) להעיר מפר״ח סי׳ תרו בשם מוהר״ש גארמיזאן (ובעץ יוסף לע״י כאן מפרש כן דברי הרי״ף שבפנים ההערה): „שהעבירה שבין אדם לחבירו יש בה חלק למקום .. וכ״ז שלא הרצה את חבירו אפי׳ מה שבין אדם למקום אינו מכפר“."]]],[1300171191,"אויך קען מען ניט זאגן אז ר״ע איז מוסיף און מדגיש, אז אויך נאכדעם ווי ער האט מרצה געווען את חבירו מוז מען (אויך ביי עבירות שבין אדם לחבירו) אנקומען צו טהרה ע״י אביכם שבשמים — ווייל, ווי מבואר בכו״כ מקומות, זיינען אויך מצות שבין אדם לחבירו — בעיקרן מצות שבין אדם למקום⁴¹, ווארום אויך זיי דארף מען מקיים זיין דערפאר ווייל זיי זיינען ציווים פון אויבערשטן⁴²; איז במילא פארשטאנדיק אז אויך נאכדעם וואס ער איז מרצה זיין חבר איז עס נאר דעם חלק פון די מצות וואס האט א שייכות מיט „חבירו“, אבער כדי ער זאל אינ־גאנצן טהור ווערן (אויך מצד דעם וואס זיי זיינען ציווי ה׳) מוז מען (גם לראב״ע) אנקומען צו טהרת הקב״ה ווי בא מצות שבין אדם למקום.\nאון דאס איז שוין מודגש אין די רייד פון ראב״ע: „עבירות שבין אדם לחבירו אין יוהכ״פ מכפר עד שירצה כו׳“, אז נאכן ריצוי מוז מען ערשט אנקומען צו דער כפרה פון יוהכ״פ, וואס איז דאך דורך הקב״ה.\nג) פארוואס דארף ר״ע האבן צווי ראיות, און ווי ער איז מדגיש „ואומר“ — וואס דאס איז א לשון וואס ווייזט אז די ערשטע ראי׳ איז ניט מספיק, ובל׳ הש״ס⁴³ „מאי ואומר“?\nז. דער ביאור בזה:\nאזוי ווי עס האט זיך גערעדט אין דער הסברה פון התחלת המסכתא — אז די מעלה פון „ביתו זו אשתו“ איז ניט א תנאי אין די עבודות פון יוהכ״פ, נאר א מעלה און שלימות אין כהן גדול גופא, און דערפאר האט עס א שייכות ניט בלויז מיט די עבודות המיוחדות ליוהכ״פ, נאר מיט אלע עבודות היום, כפס״ד הרמב״ם;\nעד״ז איז דאס אין דעם ענין וואס רעדט זיך אין סיום המסכתא — די כפרה און טהרה וואס טוט זיך אויף ביוהכ״פ: פון דברי ראב״ע ווייס מען נאר אז יוהכ״פ איז מכפר, וואס דאס קען זיין מצד דעם טאג פון יוהכ״פ (קדושת היום וכו׳); אויף דעם איז ר״ע מוסיף, אז דאס וואס יוהכ״פ איז מכפר איז עס ניט (נאר) מצד דעם טאג פון יוהכ״פ⁴⁴, נאר מצד (דעם וואס דעמאלט ווערט נתגלה) מעלת ישראל — „אשריכם ישראל“: די כפרה ביוהכ״פ איז מצד דעם פארבונד וואס איז דא צווישן אידן מיט „אביכם שבשמים“⁴⁵.\nאון אויף דעם חידוש ברענגט ר״ע א ראי׳ פון פסוק „וזרקתי עליכם מים טהורים וגו׳“, פון וועלכען ס׳איז מוכח אז דער אויבערשטער איז מטהר אידן אויך ניט ביוהכ״פ (ווארום דער פסוק רעדט דאך וועגן דעם זמן הגאולה);\nנאכמער: פון פסוק „וזרקתי גו׳“ איז מובן, אז די אמת׳ע טהרה בגאולה העתידה איז מצד דער מעלה פון א אידן בפ״ע (וואס אפילו כשחטאו בני הם⁴⁶)",[["","","עבירות שבין אדם למקום [נוסף על העיקר שמפשטות הל׳ דראב״ע משמע שהכפרה על עבירות שבין אדם למקום והכפרה על עבירות שבין אדם לחבירו אינן תלויות זב״ז]."],["41","41","ראה גם בהעתק בשוה״ג להערה הקודמת."],["42","42","ראה לקו״ש חי״ב ע׳ 670 ואילך. חי״ג ע׳ 889 ואילך. ובכ״מ."],["43","43","ברכות סג, א. וש״נ."],["44","44","ראה גם רי״ף לע״י שם."],["45","45","ראה עד״ז בלחם שמים (להיעב״ץ) יומא כאן (הובא ג״כ ב„לקוטים“ למשניות כאן. וראה לקו״ש ח״ד ע׳ 1145 ואילך)."],["46","46","ראה קדושין לו, א. ספרי האזינו לב, ה (ושם משמע דגם ר״י הודה לר״מ). במדב״ר פ״ב, טו. ועוד."]]],[1300171192,"ניט אפילו מצד דער עבודה ותשובה פון אידן, ווי עס שטייט דארט פריער⁴⁷ „לא למענכם אני עושה בית ישראל גו׳ וזרקתי גו׳“: ד.ה. די טהרה איז ניט מצד קדושת היום (יוהכ״פ), קדושת המקום (עבודה בקדה״ק), אדער אפילו מצד דעם וואס אידן שטייען אין א מצב פון קדושה — נאר מצד דער מעלה פון א אידן⁴⁷* בעצם, בכל זמן ובכל מקום —\nובמילא דארף מען זאגן, אז אויך ביוהכ״פ איז טהרת ישראל ניט בלויז מצד דעם טאג פון יוהכ״פ, נאר (בעיקר) מצד מעלת ישראל.\nאבער פון דעם פסוק איז נאך ניטא קיין ראי׳ גמורה אז ס׳איז מצד דער מעלה עצמית פון אידן, ווייל דארט רעדט זיך וועגן דעם זמן הגאולה, וואס דאס איז א זמן פון עת רצון (און מ׳קען זאגן אז הזמן גרמא, בדוגמת יום הכיפו־רים); דעריבער ברענגט ר״ע נאך א ראי׳ פון פסוק „מקוה ישראל ה׳“ — וואס דארט רעדט זיך (א) ניט וועגן א זמן פון עת רצון און (ב) אויך ווען אידן זיינען געווען אין א מצב שלא כדבעי, און פונ־דעסטוועגן זאגט דער פסוק: „מקוה ישראל ה׳“ — „מה מקוה כו׳ אף הקב״ה מטהר את ישראל“⁴⁸.\nח. מען דארף אבער פארשטיין: עפ״ז האט ר״ע געדארפט ברענגען נאר דעם צווייטן פסוק „מקוה ישראל ה׳“, און ניט דעם ערשטן?\nאיז דער ביאור אין דעם: דער חילוק צווישן די צווי פסוקים איז: „וזרקתי“ איז על דרך דער טהרה ע״י „הזאה“⁴⁹, און „מקוה ישראל“ — ע״ד טבילה במקוה⁵⁰. פון די אונטערשיידן צווישן „הזאה“ און „טבילה“: א) „הזאה“ איז „מן הטהור על הטמא, ע״י אחר“⁵¹, און טבילה איז „ע״י עצמו“⁵¹. ב) דוקא הזאה קען מטהר זיין פון טומאת מת.\nאון אזוי אויך ברוחניות הענינים: טהרה במקוה איז וואס א איד קען אויפ־טאן בכח עצמו, דורך זיין אייגענער עבודה; בשעת אבער ער איז אין א דרגא פון טמא מת ר״ל — עס איז ביי אים ניטא (בגילוי) דער „ואתם הדבקים בה״א (ובמילא — איז ניטא דער) חיים גו׳“⁵², דעמאלט דארף ער אנקומען צו „וזרקתי גו׳“ וואס קומט מלמעלה, ד.ה. ניט מצד זיין עבודה, נאר מצד זיין עצמיות׳דיקן פארבונד מיטן אויבערשטן וואס דער פארבונד איז אלעמאל גאנץ.\nאון דערפאר, בשעת ר״ע וויל ברענ־גען א ראי׳ אז טהרת בנ״י איז מצד זייער עצמיות׳דיקער מעלה, וואס איז העכער פון די הגבלות הזמן, און איז ניט אפ־הענגיק אין דעם מעמד ומצב פון בנ״י אין עבודת ה׳ — ברענגט ער צום ערשטן דעם פסוק „וזרקתי גו׳“ — די טהרה וואס איז פארבונדן מיט דעם עצמיות׳דיקן פארבונד פון אידן מיטן אויבערשטן.\nוויבאלד אבער דער פסוק רעדט דאך פארט וועגן א זמן פון עת רצון כנ״ל, ברענגט ער דעריבער דעם צווייטן פסוק „מקוה ישראל ה׳“ וואס רעדט ניט וועגן א זמן מיוחד כו׳, און דאס איז",[["47","47","יחזקאל שם, כב. 47*) וכשצריך לתשובה — י״ל שזהו ע״ד ביאור הרמב״ם (הל׳ גירושין ספ״ב) שמוכרח להיות כופין אותו, אבל רק לבטל את האונס שמבחוץ שתקפו."],["48","48","ראה ג״כ לחם שמים שם."],["49","49","ולהעיר, שגם בנוגע לכה״ג מצינו (בתחלת המסכתא — ח, א) שהיו מזין עליו בז׳ ימים שמפרישין אותו (ולדיעה א׳ — כל יום)."],["50","50","ראה גם חדא״ג כאן."],["51","51","חדא״ג כאן."],["52","52","ואתחנן ד, ד."]]],[1300171193,"מוכיח אויך אויף דעם פסוק „וזרקתי גו׳“ אז דאס איז דא בכל הזמנים.\nאבער לאידך גיסא איז דא א מעלה אין ערשטן פסוק (ואדרבה: דאס איז דער עיקר און דערפאר די ערשטע ראי׳), ווייל דוקא דארטן רעדט זיך וועגן דער טהרה וואס קומט מצד עצמיות פון א אידן, כנ״ל.\nט. כאטש די טהרה וואס קומט מלמעלה — מצד דער התקשרות עצמית כנ״ל — איז בעיקר ביי הזאה וואס איז מטהר פון טומאת מת, איז אבער דא א מעין זה אויך ביי טהרה במקוה; און דאס איז וואס ר״ע איז מחדש „מה מקוה כו׳ אף הקב״ה מטהר את ישראל“: אויך די טהרה אין דעם אופן פון מקוה נעמט זיך פון דעם וואס „הקב״ה⁵³ מטהר את ישראל“⁵⁴.\nאון עפ״ז איז מובן נאך א דיוק אין דברי ר״ע — „מה מקוה מטהר את הטמאים“ — דלכאורה: די ווערטער „את הטמאים“ זיינען איבעריק, עס האט געקענט שטיין „מה מקוה מטהר אף הקב״ה מטהר כו׳“? נאר דער ביאור בזה:\nדער דין ביי מקוה איז, אז טבילה איז מטהר אויך פון א „מקצת“ טומאה. ד.ה. אפילו ווען א מענטש האט אויף זיך נאך א טומאה וואס די טבילה קען ניט מטהר זיין, העלפט זי אבער צו מטהר זיין דעם מענטשן עכ״פ פון דער טומאה קלה⁵⁵.\nאון דערפאר איז ר״ע מדייק „מה מקוה מטהר את הטמאים אף הקב״ה מטהר את ישראל“⁵⁶: (לרמז אז) כשם ווי א מקוה איז מטהר אויך די וואס לאחרי הטבילה בלייבן זיי טמא, א טהרה פון מקצת טומאה; אזוי איז אויך „הקב״ה מטהר את ישראל“: א איד זאל ניט טראכטן אז ווען ער טוט תשובה נאר אויף א חלק פון זיינע עבירות וועט דער אויבערשטער ניט מקבל זיין זיין „מקצת“ תשובה⁵⁷, נאר אין דעם זעלבן אופן ווי א מקוה איז מטהר את הטמאים (אויך די וואס בלייבן טמא אויך לאחרי הטבילה), אזוי איז דער אויבערשטער מטהר אידן אויך ווען זיי זיינען נאך טמא ר״ל פון אנדערע עבירות⁵⁸.\nדי הסברה אין דעם איז: ווייל „הקב״ה מטהר את ישראל“: וויבאלד אז אויך די טהרה במקוה קומט ניט בכח דער עבודה פון אידן, נאר מצד „הקב״ה“ — מצד דער עצמיות׳דיקער התקשרות פון א אידן מיטן אויבערשטן — דערפאר האט עס ניט קיינע הגבלות: עס ווערט",[["53","53","להעיר מיהל אור (רשימות לתהלים) ע׳ לו: שבחי׳ מי מטהר אתכם כי מי דא עתיקא המתגלה בבינה ונק׳ מקוה ישראל ד׳ יודין דע״ב הנמשכים בבינה כו׳. וראה ג״כ אוה״ת יוהכ״פ ע׳ א׳תקעח ואילך."],["54","54","ועפ״ז יש לבאר מה שדימו הטבילה דעריוהכ״פ (להדיעה שהיא משום תשובה) „כגר המתגייר“ (שו״ע אדה״ז סתר״ו סי״ב — ע״פ המהרי״ו (הובא בד״מ שם)) — כי ע״י הטבילה במקוה נטהר האדם (לא רק לפי״ע העבודה והתשובה שלו, כ״א) „כגר המתגייר“ — שנעשה מציאות חדשה, ע״י ש„הקב״ה מטהר את ישראל“."],["55","55","משנה ספ״ג דברכות."],["56","56","ראה עד״ז בריף לע״י כאן. וראה גם לחם שמים כאן."],["57","57","אבל להעיר מאגה״ת פ״א: „שיגמור בלבו כו׳ ולא יעבור עוד כו׳ הן במ״ע הן במל״ת“. וראה בלקו״ב לתניא ח״ב ע׳ נט (אגה״ת עם ליקוט פירושים כו׳ (קה״ת) ע׳ עח). לקו״ש חי״ט ע׳ 394 הערה 20. לקר״ש ויקרא תשמ״ח ס״ב."],["58","58","ועפ״ז יובן ההמשך של דברי ר״ע לדרשת ראב״ע שיוהכ״פ מכפר על עבירות שבין אדם למקום גם (כשעדיין יש לו עבירות אחרות) כשלא נתכפר על עבירות שבין אדם לחבירו (כפשטות דברי ראב״ע, וכנ״ל הערה 40)."]]],[1300171194,"נמשך אין אלערליי זמנים און מצבים, ביז אויך צו אזא וואס אויך לאחרי הטהרה האט ער נאך אויף זיך אנדערע טומאות — אויך ביי אים איז דא דער „הקב״ה מטהר את ישראל“.\nיו״ד. און דאס איז די הוראה נפלאה וואס בדברי ר״ע: עס קומט צו גיין א איד צום אויבערשטן און בעט: איך האב ניט קיין (כח, ובמילא — ניט קיין) צייט חרטה צו האבן אויף אלע מיינע עבירות, איך האב אבער א פאר פרייע מינוטן, בין איך זיך מתחרט ומתוודה אויף די און די עבירות וואס זיינען מיר מעיק ביותר. קען ער מיינען אז דער אוי־בערשטער נעמט ניט אן אזא תשובה — זאגט ר״ע ניין, „אשריכם ישראל“: ווייל איז צו אידן אז ווען דער אויבערשטער זעט אז א איד האט זיך צו אים א קער געטאן, באיזה ענין שהוא, איז ער גלייך מכפר — „הקב״ה מטהר את ישראל“:\nאון דערנאך איז דער אויבערשטער אים מסייע⁵⁹ עס זאל זיין „מצוה גוררת מצוה“⁶⁰ — ער זאל פטור ווערן פון אלע זיינע עבירות, ביז ער ווערט אין אזא דרגא פון א בע״ת וואס צ״ג אין יכולים לעמוד שם⁶¹.\n(משיחת ו׳ תשרי תשל״א)",[["59","59","דהבא ליטהר מסייעים אותו (שבת קד, א. רש״י וש״נ). ובאגה״ת פי״א (ק, ב): הבא דייקא מיד שבא."],["60","60","אבות פ״ד מ״ב."],["61","61","ברכות לד, ב. רמב״ם הל׳ תשובה פ״ז ה״ד. וראה סה״מ תש״ט ע׳ 183 בהערה. לקו״ש חי״ד ע׳ 361 ואילך."]]],[1300171195,"<h3>אחרי ב*</h3>\nא. בסיום מסכת יומא זאָגט די גמרא „תנא דבי רבי ישמעאל הרואה קרי ביום הכיפורים ידאג כל השנה כולה ואם עלתה לו שנה מובטח לו שהוא בן העולם הבא אמר רב נחמן בר יצחק תדע שכל העולם כולו רעב והוא שבע כי אתא רב דימי אמר מפיש חיי סגי ומסגי\".\nבפשטות דאַרף מען זאָגן אַז די גמרא בריינגט די מימרות אלס המשך אין זייער תוכן צו דעם וואָס עס שטייט דאָרט פריער „הרואה קרי ביוהכ\"פ יורד וטובל וכו'\"<sup data-n=\"1\">1</sup>. מען דאַרף אָבער פאַר־שטיין: ווי קומט דאָס אַז דעם פרק יום הכיפורים — וואָס כללות ענינו איז (כשמו)<sup data-n=\"2\">2</sup> תשובה<sup data-n=\"3\">3</sup> וכפרה, און בפרט אַז דער תוכן פון דער לעצטער משנה און דער גמרא שלאח\"ז איז ענין התשובה וכו' — זאָל די גמרא מסיים וחותם זיין מיט אַן ענין הפכי<sup data-n=\"4\">4</sup> פון תשובה וכפרה, און דערצו נאָך איינע פון די האַרבסטע עבירות, ווען ס'איז במזיד, בנוגע תשובה וכפרה<sup data-n=\"5\">5</sup> און פון מזיד איז דאָך פאַר־שטאַנדיק בנוגע לשוגג<sup data-n=\"6\">6</sup>, וואָס איז דאָך בערך (קצת) צו מזיד — כמובן אויך פון חילוקי העונשין (במזיד) והקרבנות וכיו\"ב (בשוגג).\nאון הגם אַז די גמרא פירט אויס, אַז סוף־סוף איז אדרבה „מובטח לו שהוא בן העולם הבא כו' מפיש חיי סגי ומסגי\" — איז עס דאָך וואָס לאחר זמן (נאָך יוהכ\"פ) קומט ארויס דערפון אַן ענין טוב, אָבער ביוהכ\"פ גופא איז עס אַ זאַך וואָס איז היפך פון רצון ה'.\nאויך דאַרף מען פארשטיין אין עצם הענין: ווי קומט דאָס אַז פון אַ דבר בלתי רצוי בכפליים, „הרואה (א) קרי (ב) ביום הכיפורים\", זאָל ארויסקומען אַזאַ תועלת נפלאה — „מובטח לו שהוא בן העולם הבא\" און „מפיש חיי סגי ומסגי\"<sup data-n=\"7\">7</sup>?",[["","","*) וסיום מס' יומא."],["1","1","ושם בתחלת הע'. „כל חייבי טבילות טובלין כו' בעל קרי טובל והולך כו'\"."],["2","2","וכל מצות „עבודת היום — כלומר כלל כל הקרבנות והוידוין המתוקנין ביום צום כפור — (הוא) כדי שיכופר בהם כל העונות כמו שבא בכתוב והיא העבודה הכתובה באחרי מות\" (סהמ\"צ להרמבם מ\"ע מט)."],["3","3","וברמב\"ם (הלכות תשובה פ\"ב ה\"ז): יום הכפורים הוא זמן תשובה לכל ליחיד ולרבים והוא קץ מחילה וסליחה לישראל לפיכך חייבים הכל לעשות תשובה ולהתודות ביום הכפורים כו'. ובשערי תשובה (לר\"י) שער ד' י\"ז, דהכתוב (פרשתנו טז, ל) „מכל חטאתיכם לפני ה' תטהרו\" הוא מ\"ע על התשובה ביוהכ\"פ. — וראה לקו\"ש חכ\"ט שיחה ליוהכ\"פ (תשמ\"ה) ס\"ג."],["4","4","וגם היפך התחלת המסכת (דנעוץ סופן בתחלתן — וכמנהג בעלי ההדרנים) „שבעת ימים קודם יוהכ\"פ מפרישין כה\"ג מביתו כו' ומתקינין לו כהן אחר תחתיו שמא יארע בו פסול\" — „קרי או שאר טומאה\" (פרש\"י שם)."],["5","5","ראה זח\"א סב, א. ריט, ב. ועוד. וראה אגה\"ת פ\"ד."],["6","6","דגם הוא בעי כפרה (רש\"י ריש שבועות ד\"ה תולה. וראה אגה\"ק סוסכ\"ח. קרא ד\"ה ולהבין פרטי)."],["7","7","בפרש\"י „סגי ומסגי בבנים ובני בנים שכך הסימן יראה זרע ויאריך ימים\" (ישעי' נג, י). ובתוס' „רמז לדבר יראה זרע יאריך ימים\". והטעם שבשו\"ע אדה\"ז * או\"ח סו\"ס תרט כתב רק „מובטח לו שהוא בן עוה\"ב כו' והוא יאריך ימים\" ולא גם „בנים ובני בנים\" — י\"ל, כי הנ\"ל הוא *) ובמחבר כתב רק „מובטח לו שהוא בן העוה\"ב\". ובטור „מובטח לו שהוא בן העוה\"ב ויראה זרע ויאריך ימים\". ולשונו „ויראה זרע\" משמע שמפרש שיראה בנים."]]],[1300171196,"רש\"י איז מפרש אין דעם: „ואם עלתה לו שנה — שלא מת מובטח לו שמעשים טובים יש בידו שהגינו עליו וכו'\"<sup data-n=\"8\">8</sup>: דאָס איז אָבער לכאורה נאָר אַ הסברה אַז אַנאַנדער זאַך (מעש\"ט) זיינען מגין אַז דאָס זאָל אים ניט פארשאָטן, אָבער פון דעם וואָס מ'זאָגט „הרואה קרי\" איז אַ סימן<sup data-n=\"9\">9</sup> אַז מובטח כו', איז משמע אַז עס איז דאָ אַ שייכות ביניהם<sup data-n=\"10\">10</sup>, איז נישט מובן<sup data-n=\"11\">11</sup>: ווי אזוי פועל'ט עס דעם יתרון נעלה פון „מובטח לו שהוא בן העולם הבא\", און נאָכמער (אויך בעוה\"ז): מפיש חיי סגי ומסגי בבנים ובני בנים?\nב. בדומה צו דער שאלה, איז נאָך מער קשה בענין תשובה מאהבה, אויף וועלכע די גמרא<sup data-n=\"12\">12</sup> זאָגט אַז „זדונות נעשות לו כזכיות\", פרעגט דער חדא\"ג, אַז ס'איז אַ דבר תמוה, ווייל ס'קומט אויס אַז „חוטא נשכר\". און ער פאַר־ענטפערט אַז ווען אַ מענטש טוט תשובה מאהבה איז „ודאי דעושה תשובה גמורה ומוסיף במעשיו הטובים יתר מכדי הצורך לגבי אותו עון והרי אותן מעשים טובים שמוסיף הם נעשים לו כזכיות וקרא דמייתי מוכיח כן שנא'<sup data-n=\"13\">13</sup> ובשוב רשע מרשעתו ועשה משפט וצדקה עליהם חי' וגו'<sup data-n=\"14\">14</sup> דמשמע משפט וצדקה שהוסיף לעשות על תשובתו עליהם חי' יחי'\".\nדער תירוץ איז אָבער לכאורה ניט מובן, וואָרום פון לשון הגמרא „זדונות נעשו לו כזכיות\" איז מוכח אַז דאָ רעדט זיך ניט וועגן אַנאַנדער זאַך פון זדונות — אַ הוספה אין זכיות צוליב די זדונות, נאָר אַז די זדונות אַליין ווערן ווי זכיות<sup data-n=\"15\">15</sup>, בלייבט דאָך שווער כנ\"ל היתכן חוטא נשכר?\nאון הגם אַז לכאורה קען מען זאָגן אַז דאָס גופא מיינט די גמרא<sup data-n=\"16\">16</sup> מיט „זדונות נעשות לו כזכיות\": היות אַז די הוספה אין מעשים טובים קומט דערפון וואָס אַ מענטש האָט זיך געענדערט און איבערגעמאַכט דורך דער תשובה אויף די זדונות — הייסט עס דאָך אַז די „זדונות\" האָבן גורם געווען און זיינען סיבת התשובה מאהבה און פון די זכיות.",[["","","מילתא דשייכא בכל אדם, משא\"כ בנים ובני בנים שתלוי בגיל השנים וכו'. או י\"ל דתלוי בפי' „יראה זרע\" — האם יש ללמוד מזה ב' הענינים: לפרש\"י למדים „יראה זרע\" כפשוטו, וגם „יראה זרע\" — יראה בנים, מלבד השכר המפורש לאחר זה בכתוב „יאריך ימים\". משא\"כ לתוס' אין לפרש שב„יראה זרע\", שהיא הסיבה, נכלל גם השכר המסובב (בנים כו'), ולכן מפרש דהשכר בא בהמשך הכתוב „יאריך ימים\" [ולהעיר משינוי הלשון: דבפרש\"י „יראה זרע ויאריך ** ימים\" (ולא כבכתוב), ובתוס' „יראה זרע יאריך ימים\". אבל ראה פרש\"י לעיל ד\"ה עונותיו]: ובשו\"ע כתב רק הפשוט ואליבא דכו\"ע."],["8","8","ומסיים „בן עולם הבא\", וכ\"ה בשו\"ע אדה\"ז שם דזה „שבודאי יש לו זכיות כו'\" כתב כטעם ע\"ז „שהוא בן עוה\"ב\". משא\"כ בטור שכתוב בהסיום לאחר „ויראה זרע ויאריך ימים ושודאי יש לו הרבה זכיות כו'\". וראה לקמן בפנים ס\"י ובהערה 85."],["9","9","ובפרש\"י ד\"ה עונותיו מחולין — סימן טוב הוא זה כו'. וראה חדא\"ג כאן. אלי' זוטא ללבוש שם סק\"ג. ב\"ח כאן."],["10","10","אפילו את\"ל שהוא רק סימן המברר את המציאות הנמצאת כבר ולא הגורם המציאות (ראה צפע\"נ להרמב\"ם הל' מא\"ס רפ\"א)."],["11","11","ראה פר\"ח לשו\"ע שם. **) כ\"ה בכמה דפוסים, וכ\"ה בפרש\"י על הרי\"ף. משא\"כ בע\"י ובדפוס ווילנא ליתא הוא\"ו."],["12","12","יומא פו, ב."],["13","13","יחזקאל לג, יט."],["14","14","כן הובא בחדא\"ג (ובגמרא תיבת „חי'\" הוא בחצע\"ג). אבל בכתוב הנ\"ל „הוא יחי'\", וראה פסוק טז. ושם יח, כז-כח. כפות תמרים ליומא שם."],["15","15","והל' „כזכיות\" (בכ\"ף הדמיון) — ראה לקמן הערה 48."],["16","16","אבל ראה פרש\"י שם ד\"ה „עליהם (חיו) יחי'\", על כל מה שעשה ואף על העבירות\"."]]],[1300171197,"ע\"ד ווי מען געפינט ביי אַ שטר<sup data-n=\"17\">17</sup>, וואָס הגם אַז סתם אַ שטר איז בחזקת כשרות, איז אָבער דורכדעם וואָס ס'ווערט אויף אים אַן ערעור און מ'איז אים מקיים בב\"ד, באַקומט דער שטר מער תוקף ווי סתם אַ שטר, וואָס האָט ניט געהאַט קיין ערעור<sup data-n=\"18\">18</sup>. קומט אויס, אַז דער ערעור האָט גורם געווען תוקף השטר<sup data-n=\"19\">19</sup>.\nדאָס איז אָבער ניט מספיק, וואָרום דער ערעור איז נאָר גורם אַן עילוי אין דעם שטר; און עד\"ז בנדו\"ד, זיינען די „זדונות\" גורם אַן עילוי אין דעם גברא וואָס טוט תשובה<sup data-n=\"20\">20</sup>, אָבער פון לשון „זדונות נעשות לו כזכיות\" איז משמע אַז די חפצא פון די זדונות עצמן ווערן נהפך לזכיות<sup data-n=\"21\">21</sup>.\nג. וועט עס זיין פארשטאַנדיק ע\"פ הביאור אין דעם סיום מס' יומא במשנה<sup data-n=\"22\">22</sup> „אמר ר' עקיבא אשריכם ישראל לפני מי אתם מטהרין ומי מטהר אתכם אביכם שבשמים שנאמר<sup data-n=\"23\">23</sup> וזרקתי עליכם מים טהורים וטהרתם ואומר<sup data-n=\"24\">24</sup> מקוה ישראל ה' מה מקוה מטהר את הטמאים אף הקב\"ה מטהר את ישראל\".\nר\"ע זאָגט דאָ צוויי ענינים: א) „לפני מי אתם מטהרין\", ב) „ומי<sup data-n=\"25\">25</sup> מטהר אתכם\", און אויף דעם ברענגט ער די צוויי פסוקים: א) „וזרקתי עליכם מים טהורים\", ב) „מקוה ישראל ה'\" — איז מבאר דער ראַגאַטשאָוער<sup data-n=\"26\">26</sup> אַז אין די צוויי ענינים דריקט זיך אויס דער חילוק צווישן די צוויי עניני טהרה — הזאה און מקוה, וואָס אויף הזאה דאַרף מען האָבן כוונה לטהרה<sup data-n=\"27\">27</sup>, און די טהרה במקוה דאַרף ניט האָבן קיין כוונה, אַ מקוה איז מטהר אויך אָן כוונה לטבילה<sup data-n=\"28\">28</sup>.\nאון עפ\"ז איז מובן דער חילוק אין לשון הכתובים וואָס ר\"ע ברענגט: „וזרקתי עליכם מים טהורים\" און „מקוה ישראל ה'\", וואָס הגם אַז ביידע פסוקים ריידן וועגן דער טהרה ע\"י הקב\"ה, איז אָבער אין ערשטן פסוק געזאָגט געוואָרן: „וזרקתי עליכם גו'\", דער אויבערשטער איז זורק — פועל זריקה; אין צווייטן פסוק אָבער ווערט בכלל ניט דערמאָנט קיין פעולה (— כוונת הטהרה), ווייל אין דעם סוג טהרה איז כוונה ניט קיין דבר הכרחי.\nאון פונקט ווי ס'זיינען פאַראַן צוויי אופנים אין טהרה מצד דעם מטהר, בנדו\"ד מצד דעם אויבערשטן, אזוי זיינען זיי אויך פאַראַן אין עבודת התשובה והטהרה פון מענטשן — און דאָס זיינען, ווי די גמרא<sup data-n=\"29\">29</sup> איז מבאר, די",[["17","17","ראה טושו\"ע חו\"מ ר\"ס מו."],["18","18","ולהעיר מהדיעה וההסברה בטור ושו\"ע שם (ס\"ז) סמ\"ע שם (סקב\"ב) דמקיימין שטר רק משטר שקרא עליו ערעור והוחזק, דאז דקדקו בקיומו, אבל לא משטר שקיימוהו בלא ערעור."],["19","19","להעיר מלקו\"ש חלק ג' ע' 780 דע\"ס הלכה נמצא „אַז די שטאַרקייט פון דעם שטר הייבט זיך אָן פון דער צייט פון דעם ערעור\"."],["20","20","וכן הוא לפי ביאור הכפות תמרים שם. ועד\"ז מ\"ש הרמב\"ם דלקמן הערה 49."],["21","21","וראה נתיבות עולם (להמהר\"ל) נתיב התשובה פ\"ב. שלי\"ה כה, סע\"א ואילך (בהגה\"ה). ובכ\"מ. לקו\"ש חכ\"ז ע' 110 ואילך."],["22","22","פה, ב."],["23","23","יחזקאל לו, כה."],["24","24","ירמי' יז, יג. וראה לעיל ע' 177 הערה 36."],["25","25","במשנה לפנינו בש\"ס ובמשניות „מי\". אבל בירושלמי, רי\"ף ועי' כאן — „ומי\". וראה שינוי נוסחאות במשניות כאן."],["26","26","צפע\"נ לרמב\"ם הלכות תשובה פ\"ב ה\"ב."],["27","27","ראה פרה פי\"ב מ\"ב. רמב\"ם הלכות פרה פ\"ה ה\"י-ח. וראה בהמצויין בצפע\"נ שם."],["28","28","ורק מעלה עשאו בתרומה וקדשים שצריך כוונה (ראה חגיגה יח, ב ואילך. רמב\"ם הלכות מקואות פ\"א ה\"ח)."],["29","29","פו, סע\"א."]]],[1300171198,"צוויי כללות'דיקע סוגים אין תשובה: תשובה מיראה (וע\"י יסורין) און תשובה מאהבה. תשובה מאהבה קומט מיט דער אמת'ער כוונה ומבוקש לשוב אל ה' ולתקן כו', אָבער תשובה מיראה (ועאכו\"כ — ע\"י יסורין) איז כוונתו ניט קומען לעונש ובמילא האָט ער חרטה וכו'.\nאון דער אונטערשייד אין זייער אויפטו — איז מבואר אין דער גמרא, אַז בתשובה מיראה זאָגט דער פסוק<sup data-n=\"30\">30</sup> „ארפה משובתם\", ווי רש\"י<sup data-n=\"31\">31</sup> טייטשט „כבעל מום שנתרפא שמקצת שמו עליו\": אָבער ביי תשובה מאהבה איז „נעקר עונו מתחלתו\"<sup data-n=\"32\">32</sup>.\nוואָס דער חילוק איז נוגע אויך להלכה: בשעת איינער איז מקדש אַן אשה על מנת אַז זי האָט ניט קיין עבירות — איז אויב זי האָט דערנאָך (אויף די עבירות וואָס זי האָט יע געהאַט) געטאָן תשובה מיראה<sup data-n=\"33\">33</sup>, איז זי ניט מקודשת, היות אַז די עבירות פון שעת הקידושין זיינען ניט נעקר געוואָרן<sup data-n=\"34\">34</sup>; אָבער אויב זי האָט תשובה געטאָן מאהבה, איז זי מקודשת, ווייל אירע עבירות זיינען נעקר געוואָרן פון פריער ובמילא האָט זי אויך בשעת הקידושין ניט געהאַט קיין עבירות. און ווי די גמרא<sup data-n=\"35\">35</sup> איז מחלק בנוגע לנדרים ומומים: „הלכה אצל חכם והתירה (הנדרים) מקודשת אצל רופא וריפא אותה אינה מקודשת\", ווייל „חכם עוקר את הנדר מעיקרו ורופא אינו מרפא אלא מכאן ולהבא\".\nד. אַט דער חילוק צווישן תשובה מאהבה און תשובה מיראה בכלל — אַז תשובה מאהבה איז הכוונה לשוב וכו', משא\"כ תשובה מיראה — איז פאַראַן בפרט אין די אופני התשובה מאהבה<sup data-n=\"36\">36</sup> גופא:\nדאָס וואָס דורך תשובה מאהבה ווערט „נעקר עונו מתחלתו\" איז נאָך ניט דער תכלית השלימות אין תשובה מאהבה; תכלית השלימות אין תשובה מאהבה איז, ווען „זדונות נעשות לו כזכיות\", אַז די „זדונות\" ווערן ניט בלויז „נעקר\", נאָר זיי ווערן „כזכיות\".\nאין אהבה איז דאָך דאָ כו\"כ דרגות, ובכללות: בכל לבבך בכל נפשך בכל מאדך — ובמילא ווערן אויך כו\"כ דרגות אין דער תשובה וואָס קומט על ידם.\nאון וויבאַלד אַז די מעלה פון תשובה מאהבה איז דאָס וואָס זי קומט בכוונה כנ\"ל, איז מובן אַז שלימות הכוונה איז אין דעם העכערן אופן פון תשובה מאהבה, ביז אַז מ'קען זאָגן אַז די כוונה",[["30","30","הושע יד, ה."],["31","31","ד\"ה וכתיב ארפא."],["32","32","פרש\"י ד\"ה כאן מאהבה."],["33","33","בצפע\"נ שם (בסופו) מחלק „דיש נ\"מ בין ג' תשובות א' מאהבה הוה כמו חכם עוקר, והב' מיראה דהיא כמו מכה ורפואה, אף הרפואה באה קודם המכה וחיילין ובטלין כו' והג' יסורין דזה הוי מכאן ולהבא\". וע\"ז מביא הך דכתובות לקמן. והוא ע\"פ מאמר ר\"י יומא שם דלכמה גי' ופירושים מחלקם בג' — ראה חדא\"ג ודק\"ס שם. ובפרש\"י שם אינו מחלקם בג'. ובמאמר ר\"ח לפנ\"ז גבי תשובה מיראה כ': „מכאן ואילך כו'\" (כנ\"ל בפנים)."],["34","34","כן צריך לפרש ע\"פ פרש\"י כתובות (עד, ב) דלקמן בפנים ד\"ה מכאן ולהבא, משא\"כ לפי התוס' שם ד\"ה חכם. אבל גם לפי' התוס' „שאף עתה לאחר שנתרפאת היא נמאסת בעינינו כשזוכר שהיה בה כו'\". יש לפרש בנדו\"ד (ע\"פ פרש\"י הנ\"ל) כיון שבתשובה מיראה „מקצת שמו עליו\"."],["35","35","כתובות עד, רע\"ב."],["36","36","ראה המפרש לרמב\"ם רפ\"ב מהלכות יסוה\"ת ב' מדריגות באהבת ה'. ובארוכה שלי\"ה מאמר עש\"מ (מו, ב ואילך)."]]],[1300171199,"פון דעם נידעריקן אופן ווען „נעקר עונו מתחלתו\" הייסט ניט קיין כוונה<sup data-n=\"37\">37</sup>:\nוע\"ד מרז\"ל<sup data-n=\"38\">38</sup> אַז באהבה בכל לבבכם ובכל נפשכם — אַן בכל מאדכם — ווערט מען אנגערופן אין עושין רצונו של מקום.\nבכללות איז דאָס מוסבר אין דעם לשון פון ראַגאַטשאָוער „להעביר החטא לא בעי כוונה ולתקן החטא בעי כוונה\".\nאַ מעין הכרח, אַז ס'איז דאָ דער חילוק הנ\"ל אין תשובה מאהבה גופא, איז פון אַ הלכה פסוקה:\nדי גמרא<sup data-n=\"39\">39</sup> זאָגט, אַז איינער איז מקדש אַן אשה „ע\"מ שאני צדיק אפילו רשע גמור מקודשת שמא הרהר תשובה בדעתו\". פרעגט מען דערויף: ממנ\"פ — רעדט זיך דאָ וועגן תשובה מיראה — איז דאָך ניט מקוים געוואָרן דער תנאי, ווייל דורך תשובה מיראה ווערט ער ניט קיין צדיק, וויבאַלד „מקצת שמו עליו\": און אויב ס'איז געווען תשובה מאהבה, דאַרף זי אויך ניט זיין מקודשת, ווייל אַ בע\"ת איז דאָך העכער פון אַ צדיק, וכמרז\"ל<sup data-n=\"40\">40</sup> במקום שבע\"ת עומדין אין צדיקים גמורים יכולין<sup data-n=\"41\">41</sup> לעמוד<sup data-n=\"42\">42</sup>, און דער דין איז דאָך אַז אויך ווען „הטעה לשבח\"<sup data-n=\"43\">43</sup> [צי לשבח יוחסין, זאָג־ענדיק אַז ער איז אַ קלענערער מיוחס ווי ער איז באמת<sup data-n=\"44\">44</sup>: אָדער לשבח ממון, „ע\"מ שאני עני ונמצא עשיר\"] איז אינה מקודשת<sup data-n=\"45\">45</sup>.\nוהתירוץ אַז „שמא הרהר (מאהבה אזא) תשובה\" וואָס פועל'ט נאָר אַז „נעקר עונו מתחלתו\", אָבער ניט אַז זדונות נעשו לו כזכיות, וואָס דוקא אויף דער דרגא איז געזאָגט געוואָרן אַז „במקום שבע\"ת עומדין אין צ\"ג יכולין לעמוד\".\nויתרה מזה י\"ל: בשעת ס'איז אַ חשש פון „הרהר תשובה\" בשעתא חדא ורגעא חדא, קען ניט זיין קיין שלימות הכוונה. ולכן פועל'ט עס ניט זדונות נעשות לו כזכיות, אַז ער זאָל זיין העכער פון אַ צדיק<sup data-n=\"46\">46</sup>.\nדי הסברה אין דעם<sup data-n=\"47\">47</sup>: די מעלה פון אַ בע\"ת לגבי אַ צדיק גמור (וואָס מעולם לא חטא) איז ניט בלויז מצד דעם יתרון בכמות — אַז נוסף צו זיינע זכיות מצ\"ע",[["37","37","וע\"ד חגיגה (יח, ב): טבל לחולין הוחזק לחולין אסור למעשר (פרש\"י שם „הוחזק — לשון כוונה\") כו' טבל לקודש הוחזק לקודש אסור לחטאת כו' בגדי קודש מדרס לחטאת."],["38","38","ברכות לה, ב. חדא\"ג שם. לקו\"ת שלח מב, ג. ועוד."],["39","39","קדושין מט, ב."],["40","40","דעת ר\"א ברכות לד, ב. וכ\"פ הרמב\"ם הל' תשובה פ\"ז ה\"ד."],["41","41","בגמרא הגירסא אינם עומדין. אבל ברמב\"ם שם „אין צ\"ג יכולין לעמוד בו'\" (וכ\"ה בדק\"ס שם מ„גליון\"). ובכ\"מ בדא\"ח „צ\"ג אין יכולין לעמוד (שם)\"."],["42","42","ראה שלי\"ה (לו, א) דזה שנאמר בגמרא שם ו„פליגי\" „ר\"ל הם מחולקים כל אחד מדבר בענין בפ\"ע כו' צדיק גמור עדיף מבע\"ת כשהוא מיראה, בע\"ת עדיף מצדיק גמור כשהוא שב מאהבה\", וראה הערה בסה\"מ תש\"ט ע' 183. לקו\"ש חי\"ד ע' 361 ואילך."],["43","43","קדושין מח, ב (במשנה). מט, א."],["44","44","בגמרא שם „מחלוקת (ר\"ש ורבנן במשנה) בשבח ממון אבל בשבח יוחסין דברי הכל אינה מקודשת\", ובנדו\"ד דומה לכאורה לשבח יוחסין (אף דהטעם דמתגאה עלי' (פרש\"י שם ד\"ה אבל) לא שייכא הכא)."],["45","45","ועפ\"ז צע\"ק מה שהביא במועדים להלכה להרש\"י שי' [ז\"ל] זויין (ע' סח) בשם הראצגובי מקור להכרעת הרמב\"ם (הלכות תשובה פ\"ז ה\"ד) דבע\"ת גדולים מצדיקים מהא דקדושין הנ\"ל — שהרי ע\"פ הנ\"ל אית\"ל דבע\"ת גדול אינה מקודשת. וראה לקוטי ביאורים (לתניא) ח\"א ע' עז. לקו\"ש חי\"ד שם ע' 363."],["46","46","הכרח גמור אינו — כי יש לדחות דבגמרא שם אינו נוגע אמיתית הדרגא דצדיק ובע\"ת כ\"א מה שנקרא צדיק בל' בנ\"א (ראה לקו\"ב שם. לקו\"ש חי\"ד שם)."],["47","47","ראה דרמ\"צ קצא, א ואילך."]]],[1300171200,"האָט דער בע\"ת אויך די זכיות וואָס ווערן פון די זדונות — נאָר אויך (ובעיקר) מצד היתרון באיכות: „זדונות נעשות לו כזכיות\", זכיות פון אַן אַנדער איכות. און דערפאַר איז „במקום שבע\"ת עומדין אין צ\"ג יכולין לעמוד\": וויפל זכיות אַ צ\"ג זאָל האָבן דורך זיין עבודה נעלית, קען ער ניט צוקומען צו דער נייער עבודה, אַן אַנדער איכות<sup data-n=\"48\">48</sup> אין זכיות<sup data-n=\"49\">49</sup>. אָבער דאָס קען זיין נאָר ווען די תשובה קומט מצד שלימות האהבה כנ\"ל, ובמילא — שלימות הכוונה (כדלקמן), וואָס דאָס פועל'ט צו מתקן זיין דעם חטא אַז די זדונות גופא זאָלן ווערן זכיות.\nה. דער ביאור הענין פון שלימות האהבה והכוונה, און ווי אזוי די זדונות ווערן כזכיות, איז דער אלטער רבי מסביר אין תניא<sup data-n=\"50\">50</sup>, אַז מאכלות אסורות וכו' זיינען „אסורים וקשורים בידי החיצונים לעולם ואין עולים משם כו' עד שיעשה 50*) תשובה גדולה כל כך שזדונות נעשו לו כזכיות ממש שהיא תשובה מאהבה מעומקא דלבא באהבה רבה וחשיקה ונפש שוקקה לדבקה בו ית' וצמאה נפשו לה' כארץ עיפה וצי' להיות כי עד הנה היתה נפשו בארץ צי' וצלמות היא הסטרא אחרא ורחוקה\nמאור פני ה' בתכלית ולזאת צמאה נפשו ביתר עז מצמאון נפשות הצדיקים כמאמרם ז\"ל במקום שבעלי תשובה עומדים כו' ועל תשובה מאהבה רבה זו אמרו שזדונות נעשו לו כזכיות הואיל ועל ידי זה בא לאהבה רבה זו\".\nוואָס דאָ זאָגט ער ביידע ענינים: דער עילוי וואָס ווערט אין גברא — זדונות רופן ארויס דעם „צמאה נפשו ביתר עז מצמאון נפשות הצדיקים\"; דעם שינוי חפצא וואָס ווערט אין די זדונות, „הואיל ועל ידי זה בא לאהבה רבה כו'\".\nדי הסברה בזה ע\"ד ההלכה:\nבנוגע דעם ענין פון הכנה והכשרה צו אַ געוויסער פעולה, געפינט מען כו\"כ חילוקי דינים ודרגות אין זייער חשיבות און אין זייער יחס צו דער פעולה<sup data-n=\"51\">51</sup>.\nלדוגמא — מכשירי מצוה, היות אַז אַן זיי קען מען ניט מקיים זיין די מצוה, באַקומען זיי אַליין אַ חשיבות; ולדעת ר\"א<sup data-n=\"52\">52</sup> „כורתים עצים לעשות פחמים ברזל\" צוליב אַן איזמל למילה בשבת, לדעתו זיינען (רוב) מכשירי מצוה דוחין את השבת<sup data-n=\"53\">53</sup>.\nלמעלה מזה געפינט מען לדעת הירושלמי<sup data-n=\"54\">54</sup> בנוגע דער הכנה והכשרה צו מצות סוכה לולב וכיו\"ב, אַז „העושה סוכה לעצמו אומר ברוך אשר קידשנו במצותיו וציונו לעשות<sup data-n=\"55\">55</sup> סוכה כו'",[["48","48","ועפ\"ז אולי יל\"פ הל' „כזכיות\" — שהכ\"ף הדמיון הוא (לא לגריעותא כ\"א) למעליותא, כי ה„זדונות\" הנעשות „כזכיות\" הם למעלה מזכיות מצ\"ע (ראה דרמ\"צ שם) והם רק „כזכיות\"."],["49","49","אבל ברמב\"ם הלכות תשובה שם: „כאילו לא חטא מעולם, ולא עוד אלא ששכרו הרבה כו' אמרו חכמים במקום שבע\"ת עומדין כו' כלומר מעלתן גדולה ממעלת אלו שלא חטאו מעולם מפני שהן כובשין יצרם יותר מהם\". ומשמע שהמעלה הוא מצד הגברא דבע\"ת עצמו, ולא מצד החפצא שיש לו גם זדונות כזכיות."],["50","50","פ\"ז. *50) שאז עולים המאכלות אסורות וכו' עצמן — וכנ\"ל בפנים סוס\"ב."],["51","51","להעיר מלקו\"ש חי\"ב ע' 196 ואילך. וראה גם לקמן ע' 235 ואילך."],["52","52","שבת קל, א."],["53","53","שם קלא, א."],["54","54","ברכות פ\"ט, ה\"ג."],["55","55","החידוש בזה על דעת ר\"א הנ\"ל במכשירין, דלר\"א הרי חשיבות המצוה שמצינו שיש בהם הוא רק בזה שדוחה שבת, ונשארו בגדר מכשירין, משא\"כ להירושלמי שמברך וציונו. ואף שבסוכה י\"ל דסמיך על מש\"נ חה\"ס תעשה (ראה טז, יג) הרי בלולב ל\"נ זה. וראה לקמן הערה 57."]]],[1300171201,"העושה לולב לעצמו אומר ברוך אשר קידשנו במצותיו וציונו לעשות לולב וכו'\"<sup data-n=\"56\">56</sup>, און אזוי אויך ביי מזוזה תפילין ציצית וכו'<sup data-n=\"57\">57</sup>.\nוואָס בפשטות איז די הסברה אין דעם: היות אַז די תורה האָט אנגעזאָגט צו מקיים זיין אַ געוויסע מצוה, וואָס קען דורכגעפירט ווערן נאָר דורך אַ\nבאַשטימטע פעולה פון הכנה<sup data-n=\"58\">58</sup> דאַרף מען זאָגן אַז דאָס איז אויך נכלל אין דער מצוה<sup data-n=\"59\">59</sup> (אָדער: באַקומט די פעולה גופא אַ חשיבות מעין פון חשיבות המצוה (און לדעת הירושלמי — בא סוכה וכו' ווערט עס אויך אַ מצוה)).\nנאָך אַ העכערע דרגא אין הכשרת המצות געפינט מען ביי עבודת המקדש — ובפרט ביי הולכת הדם למזבח, וואָס הגם אַז די הולכה איז נאָר צוליב דער עבודה פון זריקת דם על המזבח, איז דער דין<sup data-n=\"60\">60</sup> אַז די הולכה גופא האָט די חשיבות און דעם גדר פון עבודה<sup data-n=\"61\">61</sup> ביז אַז „מחשבה פוסלת\" בה<sup data-n=\"62\">62</sup>.\nובכללות יותר, איז דאָ דער ענין פון עבודה מעין הכשרה, עבודה שאינה תמה<sup data-n=\"63\">63</sup>: זי האָט דינים און גדרים פון אַן עבודה, עס איז אָבער ניט קיין „עבודה שהיא גומרת ומתממת את הדבר\" (וואָרום יש אחרי' עבודה), ובמילא איז אַ זר ניט חייב מיתה ווען ער טוט די עבודה.\nעד\"ז איז אויך מובן בנדו\"ד: וויבאַלד אַז צום העכסטן אופן פון תשובה מאהבה קען ער צוקומען (כנ\"ל בתניא) נאָר דורך זיינע פריערדיקע זדונות (און דורך זיי איז דערנאָך (אויך) זיין קיום",[["56","56","וגם להבבלי דאינו מברך בשעת עשייתן (סוכה מו, א. מנחות מב, ב. ראה תוד\"ה ואלו שם (ובכ\"מ בראשונים) „וחולק על הש\"ס שלנו\") י\"ל שזהו רק בנוגע לברכה אבל גם לש\"ס דילן הוי מצוה — ראה מנחות שם „וכל מצוה דעשייתה לאו גמר מצוה כגון תפילין כו'\" (וראה שם ע\"א). וברמב\"ם הל' ברכות פי\"א ה\"ח „כל מצוה שיש אחר עשייתה ציווי אחר כו' כגון העושה סוכה או לולב או שופר או ציצית או תפילין או מזוזה\", ובשו\"ע אדה\"ז סי' תרמ\"א ס\"א בסוכה: „לפי שעשייתה אינה גמר המצוה שעיקר המצוה כו'\" (וראה ט\"ז שם). ובסי' תרכ\"ה (מרמ\"א ומג\"א שם): „ומצוה לתקן הסוכה ולבנותה כולה כו' מצוה הבאה לידו כו'\". וראה מכות ח, א. ובפרש\"י ד\"ה השתא. ולהעיר מלשון הגמרא (כתובות פו, סע\"א) „אבל במצות עשה כגון שאומרין לו עשה סוכה ואינו עושה לולב ואינו עושה כו'\". וראה הערה הבאה."],["57","57","אף שממצות הנ\"ל רק בסוכה ובציצית נאמר תעשה (ראה טז, יג. שלח טו, לח. תצא כב, יב. ראה סוכה יא, א ואילך. מנחות שם. ובכ\"מ) — ראה לקו\"ש חי\"ב ע' 214. וראה ר\"ח סוכה שם, ב: קציצתן זו היא עשייתן .. לקיטתן זו היא עשייתן. ולהעיר משינוי לשון הרמב\"ם בסהמ\"צ: בתפילין (מ\"ע יב יג): „שצונו להניח כו'\". בציצית (מ\"ע יד) „שצוונו לעשות ציצית כו'\". במזוזה (מ\"ע טו) „לעשות מזוזה כו'\" *). בסוכה (מ\"ע קסח) „לישב בסוכה כו'\". בלולב (מ\"ע קסט) „ליטול לולב כו'\". וראה הלשון בהוצאת קאפאח במצות הנ\"ל. *) ובטור יו\"ד ר\"ס רפה „מ\"ע לכתוב כו'\" אבל במנין המצות בתחלת היד „לקבוע מזוזה\". ועד\"ז בהכותרת להל' תפלין ומזוזה כו'. ובהלכות מזוזה פ\"ה ה\"ז „שקביעתה זו היא המצוה\". ולהעיר משו\"ע אדה\"ז (או\"ח סכ\"ה ס\"א): „יכוון בהנחת תפלין שצונו הקב\"ה לכתוב כו'\". וראה ביאור הרי\"פ פערלא לרס\"ג (ח\"ג) מילואים ס\"ד. ואכ\"מ."],["58","58","להעיר מאו\"ז ח\"א סי' תקסג „וסברת תלמוד ירושלמי כו'\"."],["59","59","להעיר מצפע\"נ על הרמב\"ם הל' שבועות פ\"ה הט\"ו."],["60","60","זבחים יג, א במשנה (תק ור\"א). רמב\"ם הלכות פסוה\"מ פי\"ג ה\"ד."],["61","61","ראה צפע\"נ עה\"ת ר\"פ מסעי. מהדו\"ת נא, ג. ובכ\"מ."],["62","62","וגם לר\"ש (בזבחים שם) ד„מכשיר בהילוך\" כי ס\"ל „אפשר בלא הילוך\" אבל במקום שהכשר מצוה כו' מוכרח, י\"ל שגם ר\"ש מודה דנעשה כגדר מצוה כו'."],["63","63","יומא כד, א ואילך. ובפרש\"י שם."]]],[1300171202,"המצות (זיינע זכיות) אין אַ העכערן אופן), ווערן די זדונות אַליין נתעלה און קריגן דעם גדר פון זכיות — בדוגמא ווי דאָס איז ביי מכשירי מצוה.\nו. דאָס איז אָבער לכאורה ניט מספיק:\nא) די מכשירי מצוה אַליין ווערן דאָך ניט נתהפך ונעשה מצוה, זיי בלייבן מכשירין אפילו לדעת ר\"א:\nאויך לדעת הירושלמי, אַז אויף עשיית סוכה ולולב מאכט מען די ברכה „אשר .. וציונו וכו'\", בלייבט עס אַלץ נאָר אַ מצוה פון עשיית סוכה און ניט די מצוה פון בסוכות תשבו: עד\"ז — הולכת הדם למזבח איז ניט קיין עבודה תמה: ב) ועיקר: בכל הנ\"ל איז דאָס אַ הכנה און פעולה וואָס איז אין סוג און נאָכמער — שייך ממש צו דער מצוה גופא, ער מאכט אַ סוכה ולולב כו', ער איז מוליך דעם דם למזבח — משא\"כ בנדו\"ד האָט ער דאָך מצד אחד, געטאָן אַ פעולה הפכית פונעם ענין הזכיות, און מאידך גיסא, זאָגט מען גאר, אַז זיי אַליין ווערן „כזכיות\".\nדי קושיא ווערט נאָך שטארקער — זעענדיק אַז אפילו ווען די מכשירין און די פעולות ההכנה זיינען רשות, ווי חרישה וזריעה כו' און דער גאנצער סדר פון „ואספת דגנך ותירושך ויצהרך\", איז הגם אַז אין דעם אלעם קען מען ניט מקיים זיין די מצות וואָס זיינען מיט זיי פארבונדן: תרומות מעשרות וכו', פונדעסטוועגן געפינט מען ניט אַז דאָס זאָל זיי האָבן אַ חשיבות פון אַ מצוה, אפילו ניט אלס מכשירי מצוה<sup data-n=\"64\">64</sup>. וי\"ל הטעם — ווייל לויט דעת רשב\"י<sup data-n=\"65\">65</sup> איז עס ניט רצוי: „אפשר אדם חורש כו'\nוזורע כו' תורה מה תהא עלי'\". ומיני' — לדעת רבנן איז עס עכ\"פ ניט בסוג פון רצוי (מכשירי מצוה וכיו\"ב).\nז. איז דער ביאור אין דעם בקיצור:\nבאַ יעדער מצוה איז דאָ דער ענין הכללי און דער צד השווה מיט אלע מצות — ובלשון חז\"ל „עושה רצונו של מקום\" „אמרתי ונעשה רצוני\" (והפכו באַ יעדער עבירה — „עובר רצונו של מקום\"), און די ענינים פרטים אירע: מילת הערלה, בסוכות תשבו וכו'.\nביי כל ענינים הפרטים הנ\"ל, כאטש אַז די הכנה און הכשרה איז אין דעם חפץ אדער בשייכות צום חפץ וואָס מ'טוט דערמיט אַ מצוה, זיינען זיי אָבער ניט אַ חלק און פרט פון דער מצוה עצמה: צוגרייטן דעם איזמל למילה איז ניט קיין טייל פון כריתת הערלה; עשיית סוכה ולולב איז ניט קיין חלק פון בסוכות תשבו וכו'; הולכת הדם איז ניט קיין טייל פון זריקה.\nתשובה בכלל — איז ענינה, בלשון הרמב\"ם<sup data-n=\"66\">66</sup>: „ומה היא התשובה הוא שיעזוב החוטא חטאו ויסירו ממחשבתו ויגמור בלבו שלא יעשהו עוד<sup data-n=\"67\">67</sup>, שנאמר יעזוב רשע דרכו וגו'\"<sup data-n=\"68\">68</sup>. — ד. ה. זי איז אין בסוג און נאָכמער אין דעם זעלבן „ארט\" פון דעם ענין הכללי פון מצות (און עבירות): החלטה ברצון ו„יגמור בלבו\".\nאון וויבאַלד אַז די תשובה מאהבה מיט",[["64","64","להעיר מלקו\"ש ח\"ה ע' 74."],["65","65","ברכות לה, ב."],["66","66","הלכות תשובה פ\"ב ה\"ב."],["67","67","ואף שצ\"ל והשיב את הגזילה וכו' — הרי אפילו רשע גמור ובזמן שביהמ\"ק הי' קיים — תומ\"י כשהרהר תשובה נעשה צד\"ג, כמפורש בקידושין שם. ראה חלקת מחוקק לשו\"ע אה\"ע סל\"ח סק\"ד מד, ב\"ש שם סקנ\"ה. וראה לקמן ע' 197 ואילך."],["68","68","וממשיך „וכן יתנחם על שעבר כו'\", וראה אגה\"ת פ\"א, ובלקו\"ב לשם (אגה\"ת עם ליקוט פירושים כו' (קה\"ת) ע' טז ואילך. ע' סו ואילך). לקמן שם."]]],[1300171203,"אזאַ צמאון איז געוואָרן ארויסגערופן דורך די זדונות, דערפאַר ווערן די זדונות גופא כזכיות<sup data-n=\"69\">69</sup>.\nדאָס איז נאָר בשעת ס'איז דאָ שלימות האהבה והכוונה הנ\"ל, וואָס דעמולט ווערן (מצד דער אהבה וכוונה) די זדונות אַ חלק פון עבודת התשובה, ובמילא כזכיות: אָבער בשעת ס'איז ניטאָ די שלימות, כאטש אַז ער טוט תשובה מאהבה, דעמאָלט ווערן ניט די זדונות כזכיות, מערניט וואָס „נעקר עונו מתחלתו\"<sup data-n=\"70\">70</sup>.\nח. דוגמאות להנ\"ל — עכ\"פ מעין הנ\"ל ובדרך אפשר — בקיצור:\nמכשירי מצוה אין דעם זעלבן ענין פון דער מצוה און זיי ווערן אַ מצוה:\nסוג דחינוך: קרבנות ועבודות ימי המילואים (החינוך<sup data-n=\"71\">71</sup>). מנחת חינוך פון כהנים. דעם פאָטער'ס חינוך הבן לת\"ת וואָס איז מן התורה*<sup data-n=\"71\">71</sup>. ועוד.\nקיום המצות בגלות — לויט דעם ספרי<sup data-n=\"72\">72</sup> עה\"פ ואבדתם גו' ושמתם את דברי גו': אע\"פ שאני מגלה אתכם כו' היו מצוינים במצות שכשאתם חוזרים לא יהיו לכם חדשים<sup data-n=\"73\">73</sup>. ועוד.\nמעין זדונות נעשו לו כזכיות אין מצות גופא: שעיר המשתלח ופרה אדומה (ועגלה ערופה) — אַז דוקא די עבודה<sup data-n=\"74\">74</sup> בחוץ — ווערט עבודה המכפרת (חטאת קריא רחמנא<sup data-n=\"75\">75</sup>) ווי בא אלע קרבנות עבודתם בפנים דוקא, און נאָכמער<sup data-n=\"76\">76</sup>.\nמעין זה — פר דאלי' בהר הכרמל (בהוראת שעה). ועוד.\nיתרה מזה — מרז\"ל: מינ' ובי' אבא לשדי בי' נרגא*<sup data-n=\"76\">76</sup>.\nהכלל גדול בתורה — פקו\"נ (אפילו) ע\"י כל<sup data-n=\"77\">77</sup> עבירות שבתורה חוץ הפכו — שלש דיהרג (אף דהמאבד עצמו לדעת אין לו חלק לעוה\"ב*<sup data-n=\"77\">77</sup>) ואל יעבור, ועוד.\nויש להאריך בכ\"ז. ואכ\"מ.",[["69","69","ולפ\"ז י\"ל שהוא ע\"ד מש\"כ הר\"ן (רפ\"ב דקדושין) „דאע\"ג דאשה אינה מצווה בפרי' ורבי' מ\"מ יש לה מצוה מפני שהיא מסייעת לבעלה לקיים מצוותו\", ונתבאר בזה (ראה לקו\"ש חי\"ד ע' 41 ואילך. וראה לקמן ע' 236) כיון שאא\"פ בלעדה — שזהו גדר המצוה, לכן יש לה מצוה (— רבה דפו\"ר)."],["70","70","והיינו כי בתשובה מאהבה (דוקא, משא\"כ בתשובה מיראה) נתגלה עצם מהותו, שהוא טוב וקדושה ומצד זה מתבטלת מציאות הזדונות (למפרע) לגמרי — ראה בכ\"ז לקו\"ש חי\"ו ע' 54 ואילך (והערה 46). ועד\"ז אי\"צ כוונה בשלימות. משא\"כ הנ\"ל בתניא."],["71","71","ראה פרש\"י תצוה כח, מא. צו ז, לז. *71) הל' ת\"ת לאדה\"ז בתחלתן. וש\"נ."],["72","72","לעקב יא, יז. הובא בפרש\"י שם."],["73","73","ועפ\"י המבואר בפנים — מתורצת הקושיא המפורסמת שהרי המדובר במצות שאינן תלויות בארץ. וראה רמב\"ן אחרי יח, כה."],["74","74","להעיר ממרז\"ל דחיתו זוהי שחיטתו (יומא סד, א. וראה צפע\"נ: הל' תשובה פ\"ח ה\"ד. הל' כלאים בסופו (כד, ד). שו\"ת דורינסק ח\"ב סי' לג. לסנהדרין קיא, ב. (רא, א)). ועפ\"י המבואר בצפע\"נ שם מובן דכשעיר המשתלח בא ענין דזדונות נעשו לו כזכיות בנוגע לכל ישראל — „כל עונות בני ישראל ואת כל פשעיהם לכל חטאתם\" (פרשתנו טז, כא)."],["75","75","ע\"ז כג, ב."],["76","76","ראה בכ\"ז — אגה\"ק סכ\"ח. סהמ\"צ להצ\"צ מצות עגלה ערופה. — וסיבת היתרון אשר בזה ראה דרושי ביאור ענין הנסיונות (עה\"פ כי מנסה (לקו\"ת דברים יט, א ואילך. ועוד), סהמ\"צ להצ\"צ בסופו (קפה, ב ואילך)). *76) סנהדרין לט, ב. וראה תניא רפל\"א. ולהעיר מרמב\"ם הל' דעות פ\"ב הי\"ב."],["77","77","סנהדרין עד, א. *77) מהרי\"ט לכתובות קג, ב. שבט מוסר פ\"כ. מלחמות היהודים ג, ח, ה. יוסיפון פע\"א. חוה\"ל"]]]]});
